#' Wrapper function to generate blitzGSEA parameters
#'
#' @param min_size Integer. Minimum number of genes per gene set. Defaults to
#' `5L`.
#' @param max_size Integer. Maximum number of genes per gene set. Defaults to
#' `500L`.
#' @param permutations Integer. Random gene sets drawn per anchor size during
#' calibration. Below `1000L` the two tails are pooled into a single gamma
#' regardless of `symmetric`. Defaults to `2000L`.
#' @param anchors Integer. Number of log-spaced anchor sizes requested. Sizes
#' that collide after rounding are collapsed, so the realised grid is usually a
#' little smaller. Defaults to `40L`.
#' @param symmetric Boolean. Pool both tails into one gamma instead of fitting
#' them separately. Defaults to `FALSE`.
#' @param centre Boolean. Centre the signature on its mean before scoring. The
#' enrichment score is not invariant to an offset, so the calibration and the
#' scoring have to agree on this. Defaults to `TRUE`.
#' @param ks_test Boolean. Run the Kolmogorov-Smirnov goodness-of-fit diagnostic
#' at every anchor. Costs a sort per anchor. Defaults to `TRUE`.
#' @param seed Numeric. Random seed for the calibration. Defaults to `42.0`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item min_size - Integer. Minimum number of genes per gene set. Defaults to
#'  `5L`.
#'  \item max_size - Integer. Maximum number of genes per gene set. Defaults to
#'  `500L`.
#'  \item permutations - Integer. Random gene sets drawn per anchor size during
#'  calibration. Below `1000L` the two tails are pooled into a single gamma
#'  regardless of `symmetric`. Defaults to `2000L`.
#'  \item anchors - Integer. Number of log-spaced anchor sizes requested. Sizes
#'  that collide after rounding are collapsed, so the realised grid is usually a
#'  little smaller. Defaults to `40L`.
#'  \item symmetric - Boolean. Pool both tails into one gamma instead of fitting
#'  them separately. Defaults to `FALSE`.
#'  \item centre - Boolean. Centre the signature on its mean before scoring. The
#'  enrichment score is not invariant to an offset, so the calibration and the
#'  scoring have to agree on this. Defaults to `TRUE`.
#'  \item ks_test - Boolean. Run the Kolmogorov-Smirnov goodness-of-fit
#'  diagnostic at every anchor. Costs a sort per anchor. Defaults to `TRUE`.
#'  \item seed - Numeric. Random seed for the calibration. Defaults to `42.0`.
#' }
#'
#' @references Lachmann, et al., Bioinformatics, 2022
#'
#' @export
params_blitzgsea <- function(
  min_size = 5L,
  max_size = 500L,
  permutations = 2000L,
  anchors = 40L,
  symmetric = FALSE,
  centre = TRUE,
  ks_test = TRUE,
  seed = 42.0
) {
  # Checks
  checkmate::qassert(min_size, "I1[3,)")
  checkmate::qassert(max_size, "I1[4,)")
  checkmate::qassert(permutations, "I1[2,)")
  checkmate::qassert(anchors, "I1[2,)")
  checkmate::qassert(symmetric, "B1")
  checkmate::qassert(centre, "B1")
  checkmate::qassert(ks_test, "B1")
  checkmate::qassert(seed, "N1[0,)")

  if (permutations < BLITZ_MIN_PERMUTATIONS_SPLIT) {
    warning(sprintf(
      paste(
        "%i permutations is below %i, so the positive and negative tails",
        "will be pooled into a single gamma regardless of `symmetric`."
      ),
      permutations,
      BLITZ_MIN_PERMUTATIONS_SPLIT
    ))
  }
  seed <- as.double(seed)

  # Return
  list(
    min_size = min_size,
    max_size = max_size,
    permutations = permutations,
    anchors = anchors,
    symmetric = symmetric,
    centre = centre,
    ks_test = ks_test,
    seed = seed
  )
}

