#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item strategy - String. Which dropout strategy to apply. Currently only
#'  `"seq_depth"`. One of `"seq_depth"`. Defaults to `"seq_depth"`.
#'  \item target_library_size - Numeric. Reference library size per sample.
#'  Defaults to `20000.0`.
#'  \item capture_efficiency_sigma - Numeric. Standard deviation of the
#'  LogNormal size-factor distribution. Larger values spread the library sizes
#'  further apart. Defaults to `0.5`.
#'  \item seed - Integer. Seed for reproducibility purposes. Defaults to `123L`.
#' }
#'
#' @references Zappia, et al., Genome Biol, 2017
#'
#' @export
params_bulk_sparsity <- function(
  strategy = "seq_depth",
  target_library_size = 20000.0,
  capture_efficiency_sigma = 0.5,
  seed = 123L
) {
  strategy <- match.arg(strategy)

  # Checks
  checkmate::assertChoice(strategy, "seq_depth")
  checkmate::qassert(target_library_size, "N1(0,)")
  checkmate::qassert(capture_efficiency_sigma, "N1(0,)")
  checkmate::qassert(seed, "I1[0,)")

  # Return
  list(
    strategy = strategy,
    target_library_size = target_library_size,
    capture_efficiency_sigma = capture_efficiency_sigma,
    seed = seed
  )
}

#' Wrapper function to CisTarget parameters
#'
#' @description `auc_threshold` and `max_rank` are two different cutoffs and are
#' easy to confuse. The first truncates the recovery curve used to score motif
#' enrichment, the second sets how deep into the ranking the background curve
#' (mean + 2 SD across all motifs) is built, and therefore where the leading
#' edge cuts. RcisTarget uses `maxRank = 5000` and `nMean = 100`; the defaults
#' here follow it. `auc_threshold` follows pySCENIC at 5%, RcisTarget itself
#' uses 3%.
#'
#' @param auc_threshold Numeric. Numeric between 0 and 1. Proportion of genes to
#' use for AUC threshold calculation. Default is 0.05 (5% of genes). Defaults to
#' `0.05`.
#' @param nes_threshold Numeric. Normalised Enrichment Score threshold for
#' significant motifs. Default is 3.0. Defaults to `3.0`.
#' @param max_rank Integer. Depth of the recovery curves used to derive the
#' background and the leading edge. Clamped to the number of genes in the
#' ranking database. Default is 5000, the RcisTarget value. Defaults to `5000L`.
#' @param n_mean Integer. Window for the rolling mean smoothing the background
#' recovery curve. Only read when `rcc_method = "approx"`. Default is 100, the
#' RcisTarget value. Defaults to `100L`.
#' @param rcc_method String. Method for recovery curve calculation. Either
#' "approx" (approximate, faster) or "icistarget" (exact, slower). One of
#' `c("approx", "icistarget")`. Defaults to `"approx"`.
#' @param high_conf_cats String vector. Annotation categories considered high
#' confidence. Default includes direct annotations and orthology-based
#' inferences. Defaults to `c("directAnnotation", "inferredBy_Orthology")`.
#' @param low_conf_cats String vector. Annotation categories considered lower
#' confidence. Default includes motif similarity-based inferences. Defaults to
#' `c("inferredBy_MotifSimilarity", "inferredBy_MotifSimilarity_n_Orthology")`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item auc_threshold - Numeric. Numeric between 0 and 1. Proportion of genes
#'  to use for AUC threshold calculation. Default is 0.05 (5% of genes).
#'  Defaults to `0.05`.
#'  \item nes_threshold - Numeric. Normalised Enrichment Score threshold for
#'  significant motifs. Default is 3.0. Defaults to `3.0`.
#'  \item max_rank - Integer. Depth of the recovery curves used to derive the
#'  background and the leading edge. Clamped to the number of genes in the
#'  ranking database. Default is 5000, the RcisTarget value. Defaults to
#'  `5000L`.
#'  \item n_mean - Integer. Window for the rolling mean smoothing the background
#'  recovery curve. Only read when `rcc_method = "approx"`. Default is 100, the
#'  RcisTarget value. Defaults to `100L`.
#'  \item rcc_method - String. Method for recovery curve calculation. Either
#'  "approx" (approximate, faster) or "icistarget" (exact, slower). One of
#'  `c("approx", "icistarget")`. Defaults to `"approx"`.
#'  \item high_conf_cats - String vector. Annotation categories considered high
#'  confidence. Default includes direct annotations and orthology-based
#'  inferences. Defaults to `c("directAnnotation", "inferredBy_Orthology")`.
#'  \item low_conf_cats - String vector. Annotation categories considered lower
#'  confidence. Default includes motif similarity-based inferences. Defaults to
#'  `c("inferredBy_MotifSimilarity", "inferredBy_MotifSimilarity_n_Orthology")`.
#' }
#'
#' @export
params_cistarget <- function(
  auc_threshold = 0.05,
  nes_threshold = 3.0,
  max_rank = 5000L,
  n_mean = 100L,
  rcc_method = c("approx", "icistarget"),
  high_conf_cats = c("directAnnotation", "inferredBy_Orthology"),
  low_conf_cats = c(
    "inferredBy_MotifSimilarity",
    "inferredBy_MotifSimilarity_n_Orthology"
  )
) {
  rcc_method <- match.arg(rcc_method)

  # Checks
  checkmate::qassert(auc_threshold, "N1[0,1]")
  checkmate::qassert(nes_threshold, "N1")
  checkmate::qassert(max_rank, "I1[1,)")
  checkmate::qassert(n_mean, "I1[1,)")
  checkmate::assertChoice(rcc_method, c("approx", "icistarget"))
  checkmate::qassert(high_conf_cats, "S+")
  checkmate::qassert(low_conf_cats, "S+")

  # Return
  list(
    auc_threshold = auc_threshold,
    nes_threshold = nes_threshold,
    max_rank = max_rank,
    n_mean = n_mean,
    rcc_method = rcc_method,
    high_conf_cats = high_conf_cats,
    low_conf_cats = low_conf_cats
  )
}

