#' Wrapper function to generate CoReMo parameters
#'
#' @param epsilon Numeric. Epsilon parameter for the chosen RBF function, see
#' `rbf_func`. The higher, the more aggressively low correlations will be
#' shrunk. Defaults to `2.0`.
#' @param k_min Integer. Minimum and maximum number of cuts to use for the
#' hierarchical clustering. Defaults to `2L`.
#' @param k_max Integer. Minimum and maximum number of cuts to use for the
#' hierarchical clustering. Defaults to `150L`.
#' @param min_size Integer or `NULL`. Minimum size of the clusters. Smaller
#' clusters will be combined together. Defaults to `NULL`.
#' @param junk_module_threshold Numeric. Threshold for the minimum correlation
#' to be observed in a module. Defaults to `0.05`.
#' @param rbf_func String. Type of RBF you wish to apply to down-weigh weak
#' correlations. One of `c("gaussian", "inverse_quadratic", "bump")`. Defaults
#' to `"gaussian"`.
#' @param cor_method String. The type of correlation to use. One of
#' `c("spearman", "pearson")`. Defaults to `"spearman"`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item epsilon - Numeric. Epsilon parameter for the chosen RBF function, see
#'  `rbf_func`. The higher, the more aggressively low correlations will be
#'  shrunk. Defaults to `2.0`.
#'  \item k_min - Integer. Minimum and maximum number of cuts to use for the
#'  hierarchical clustering. Defaults to `2L`.
#'  \item k_max - Integer. Minimum and maximum number of cuts to use for the
#'  hierarchical clustering. Defaults to `150L`.
#'  \item min_size - Integer or `NULL`. Minimum size of the clusters. Smaller
#'  clusters will be combined together. Defaults to `NULL`.
#'  \item junk_module_threshold - Numeric. Threshold for the minimum correlation
#'  to be observed in a module. Defaults to `0.05`.
#'  \item rbf_func - String. Type of RBF you wish to apply to down-weigh weak
#'  correlations. One of `c("gaussian", "inverse_quadratic", "bump")`. Defaults
#'  to `"gaussian"`.
#'  \item cor_method - String. The type of correlation to use. One of
#'  `c("spearman", "pearson")`. Defaults to `"spearman"`.
#' }
#'
#' @export
params_coremo <- function(
  epsilon = 2.0,
  k_min = 2L,
  k_max = 150L,
  min_size = NULL,
  junk_module_threshold = 0.05,
  rbf_func = c("gaussian", "inverse_quadratic", "bump"),
  cor_method = c("spearman", "pearson")
) {
  rbf_func <- match.arg(rbf_func)
  cor_method <- match.arg(cor_method)

  # Checks
  checkmate::qassert(epsilon, "N1")
  checkmate::qassert(k_min, "I1")
  checkmate::qassert(k_max, "I1")
  checkmate::qassert(min_size, c("I1", "0"))
  checkmate::qassert(junk_module_threshold, "N1")
  checkmate::assertChoice(rbf_func, c("gaussian", "inverse_quadratic", "bump"))
  checkmate::assertChoice(cor_method, c("spearman", "pearson"))

  # Return
  list(
    epsilon = epsilon,
    k_min = k_min,
    k_max = k_max,
    min_size = min_size,
    junk_module_threshold = junk_module_threshold,
    rbf_func = rbf_func,
    cor_method = cor_method
  )
}

