#'  \item sparsity - Integer. Sparsity constraint (max non-zero coefficients per
#'  signal) Defaults to `5L`.
#'  \item dict_size - Integer. Dictionary size Defaults to `5L`.
#'  \item alpha - Numeric. Sample context regularisation weight. Defaults to
#'  `1.0`.
#'  \item beta - Numeric. Feature effect regularisation weight. Defaults to
#'  `1.0`.
#'  \item max_iter - Integer. Maximum number of iterations for the main
#'  algorithm. Defaults to `20L`.
#'  \item k_neighbours - Integer. Number of neighbours in the KNN graph.
#'  Defaults to `5L`.
#'  \item admm_iter - Integer. ADMM iterations for sparse coding. Defaults to
#'  `5L`.
#'  \item rho - Numeric. ADMM step size. Defaults to `1.0`.
#' }
#'
#' @export
params_dgrdl <- function(
  sparsity = 5L,
  dict_size = 5L,
  alpha = 1.0,
  beta = 1.0,
  max_iter = 20L,
  k_neighbours = 5L,
  admm_iter = 5L,
  rho = 1.0
) {
  # Checks
  checkmate::qassert(sparsity, "I1")
  checkmate::qassert(dict_size, "I1")
  checkmate::qassert(alpha, "N1")
  checkmate::qassert(beta, "N1")
  checkmate::qassert(max_iter, "I1")
  checkmate::qassert(k_neighbours, "I1")
  checkmate::qassert(admm_iter, "I1")
  checkmate::qassert(rho, "N1")

  # Return
  list(
    sparsity = sparsity,
    dict_size = dict_size,
    alpha = alpha,
    beta = beta,
    max_iter = max_iter,
    k_neighbours = k_neighbours,
    admm_iter = admm_iter,
    rho = rho
  )
}

#' Wrapper function for the DIALOGUE mixed model parameters
#'
#' @description Stage two of DIALOGUE: for every ordered pair of cell types and
#' every candidate gene, a random-intercept mixed model over samples asking
#' whether a cell's own programme score tracks the partner cell type's
#' expression of that gene in the same sample.
#'
#' @details
#' This stage dominates the runtime, and `satterthwaite` is the knob that
#' decides how badly. Turning it off falls back to the residual count for the
#' denominator degrees of freedom, which is far cheaper and barely differs once
#' a cell type has thousands of cells.
#'
#' `use_cell_quality` conditions on the cell's own quality covariate, which
#' stage one has already regressed out of the scores by ordinary least squares.
#' The default conditions on it twice, because upstream does.
#'
#' @param min_cells_per_sample Integer. Minimum cells a sample must contribute,
#' in *both* cell types of a pair, before it takes part in that pair's models.
#' Defaults to `2L`.
#' @param use_tme_qc Boolean. Include the partner cell type's mean quality in
#' that sample as a fixed effect. Upstream's `tme.qc`. Defaults to `TRUE`.
#' @param use_cell_quality Boolean. Include the responding cell's own quality as
#' a fixed effect. Upstream's `cellQ`. Defaults to `TRUE`.
#' @param satterthwaite Boolean. Compute Satterthwaite denominator degrees of
#' freedom, as `lmerTest` does. Defaults to `TRUE`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item min_cells_per_sample - Integer. Minimum cells a sample must
#'  contribute, in *both* cell types of a pair, before it takes part in that
#'  pair's models. Defaults to `2L`.
#'  \item use_tme_qc - Boolean. Include the partner cell type's mean quality in
#'  that sample as a fixed effect. Upstream's `tme.qc`. Defaults to `TRUE`.
#'  \item use_cell_quality - Boolean. Include the responding cell's own quality
#'  as a fixed effect. Upstream's `cellQ`. Defaults to `TRUE`.
#'  \item satterthwaite - Boolean. Compute Satterthwaite denominator degrees of
#'  freedom, as `lmerTest` does. Defaults to `TRUE`.
#' }
#'
#' @references Jerby-Arnon & Regev, Nature Biotechnology, 2022
#'
#' @export
params_dialogue_hlm <- function(
  min_cells_per_sample = 2L,
  use_tme_qc = TRUE,
  use_cell_quality = TRUE,
  satterthwaite = TRUE
) {
  # Checks
  checkmate::qassert(min_cells_per_sample, "I1[0,)")
  checkmate::qassert(use_tme_qc, "B1")
  checkmate::qassert(use_cell_quality, "B1")
  checkmate::qassert(satterthwaite, "B1")

  # Return
  list(
    min_cells_per_sample = min_cells_per_sample,
    use_tme_qc = use_tme_qc,
    use_cell_quality = use_cell_quality,
    satterthwaite = satterthwaite
  )
}

#' Wrapper function for the DIALOGUE decomposition parameters
#'
#' @description Stage one of DIALOGUE: the penalised matrix decomposition that
#' turns the per-cell-type features into multicellular programmes, and the
#' provisional gene signatures that come off it.
#'
#' @details
#' The defaults follow upstream's `DLG.get.param`. Two knobs are worth thinking
#' about before anything else. `k` is how many programmes you are asking for,
#' and there is no sweep to help you pick it. `n_permutations` sets the
#' resolution of the empirical p-value: with the default of `100` the smallest
#' p you can observe is `0.01`, so lower it for a quick look and leave it alone
#' for anything you intend to believe.
#'
#' `averaging` is exposed and honoured here. Upstream takes the same argument
#' and then ignores it, hard-coding column medians, so `"median"` is what every
#' published DIALOGUE run actually used.
#'
#' @param k Integer. Number of multicellular programmes to extract. Must be at
#' least 1. Defaults to `2L`.
#' @param n_permutations Integer. Permutations backing the empirical p-value per
#' programme. Must be at least 2. Defaults to `100L`.
#' @param extra_sparse Boolean. Tune the L1 bound by permutation instead of
#' fixing it at `sqrt(p_1) / 2`. Costs ten more fits per permutation. Defaults
#' to `FALSE`.
#' @param abn_c Integer. Minimum cells a sample must contribute, within a cell
#' type, before it counts towards the feature-level ANOVA. Defaults to `15L`.
#' @param p_anova Numeric. BH-adjusted ANOVA cutoff for keeping a feature. Must
#' be in `(0, 1]`. Defaults to `0.05`.
#' @param centre Boolean. Centre and scale the sample-level feature matrix, then
#' winsorise it. Defaults to `TRUE`.
#' @param cap Numeric. Winsorising tail fraction applied to each column. Must be
#' in `[0, 0.5)`. Defaults to `0.01`.
#' @param spatial Boolean. Spatial data: skip the ANOVA feature filter entirely.
#' Niches are small, so a feature need not vary across them to be real. Defaults
#' to `FALSE`.
#' @param n_genes Integer. Genes taken per programme per direction when building
#' a signature. Defaults to `200L`.
#' @param min_ci Numeric. Minimum absolute correlation for a gene to enter a
#' signature. Must be in `[0, 1]`. Defaults to `0.05`.
#' @param averaging String. How cell-level features are collapsed per sample.
#' One of `c("median", "mean")`. Defaults to `"median"`.
#' @param mcp_assignment_p Numeric. Empirical p below which a cell type pair
#' counts as connected when deciding which cell types a programme spans. Must be
#' in `(0, 1]`. Defaults to `0.1`.
#' @param seed Integer. Seed for the permutation null. Defaults to `1234L`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item k - Integer. Number of multicellular programmes to extract. Must be at
#'  least 1. Defaults to `2L`.
#'  \item n_permutations - Integer. Permutations backing the empirical p-value
#'  per programme. Must be at least 2. Defaults to `100L`.
#'  \item extra_sparse - Boolean. Tune the L1 bound by permutation instead of
#'  fixing it at `sqrt(p_1) / 2`. Costs ten more fits per permutation. Defaults
#'  to `FALSE`.
#'  \item abn_c - Integer. Minimum cells a sample must contribute, within a cell
#'  type, before it counts towards the feature-level ANOVA. Defaults to `15L`.
#'  \item p_anova - Numeric. BH-adjusted ANOVA cutoff for keeping a feature.
#'  Must be in `(0, 1]`. Defaults to `0.05`.
#'  \item centre - Boolean. Centre and scale the sample-level feature matrix,
#'  then winsorise it. Defaults to `TRUE`.
#'  \item cap - Numeric. Winsorising tail fraction applied to each column. Must
#'  be in `[0, 0.5)`. Defaults to `0.01`.
#'  \item spatial - Boolean. Spatial data: skip the ANOVA feature filter
#'  entirely. Niches are small, so a feature need not vary across them to be
#'  real. Defaults to `FALSE`.
#'  \item n_genes - Integer. Genes taken per programme per direction when
#'  building a signature. Defaults to `200L`.
#'  \item min_ci - Numeric. Minimum absolute correlation for a gene to enter a
#'  signature. Must be in `[0, 1]`. Defaults to `0.05`.
#'  \item averaging - String. How cell-level features are collapsed per sample.
#'  One of `c("median", "mean")`. Defaults to `"median"`.
#'  \item mcp_assignment_p - Numeric. Empirical p below which a cell type pair
#'  counts as connected when deciding which cell types a programme spans. Must
#'  be in `(0, 1]`. Defaults to `0.1`.
#'  \item seed - Integer. Seed for the permutation null. Defaults to `1234L`.
#' }
#'
#' @references Jerby-Arnon & Regev, Nature Biotechnology, 2022
#'
#' @export
params_dialogue_pmd <- function(
  k = 2L,
  n_permutations = 100L,
  extra_sparse = FALSE,
  abn_c = 15L,
  p_anova = 0.05,
  centre = TRUE,
  cap = 0.01,
  spatial = FALSE,
  n_genes = 200L,
  min_ci = 0.05,
  averaging = c("median", "mean"),
  mcp_assignment_p = 0.1,
  seed = 1234L
) {
  averaging <- match.arg(averaging)

  # Checks
  checkmate::qassert(k, "I1[1,)")
  checkmate::qassert(n_permutations, "I1[2,)")
  checkmate::qassert(extra_sparse, "B1")
  checkmate::qassert(abn_c, "I1[0,)")
  checkmate::qassert(p_anova, "N1(0,1]")
  checkmate::qassert(centre, "B1")
  checkmate::qassert(cap, "N1[0,0.5)")
  checkmate::qassert(spatial, "B1")
  checkmate::qassert(n_genes, "I1[1,)")
  checkmate::qassert(min_ci, "N1[0,1]")
  checkmate::assertChoice(averaging, c("median", "mean"))
  checkmate::qassert(mcp_assignment_p, "N1(0,1]")
  checkmate::qassert(seed, "I1")

  # Return
  list(
    k = k,
    n_permutations = n_permutations,
    extra_sparse = extra_sparse,
    abn_c = abn_c,
    p_anova = p_anova,
    centre = centre,
    cap = cap,
    spatial = spatial,
    n_genes = n_genes,
    min_ci = min_ci,
    averaging = averaging,
    mcp_assignment_p = mcp_assignment_p,
    seed = seed
  )
}

#' Wrapper function for the DIALOGUE refinement parameters
#'
#' @description Stage three of DIALOGUE: the cross-partner meta-analysis that
#' decides which genes survive, and the non-negative refit of the programme
#' scores onto them.
#'
#' @details
#' Two gene lists come out. The permissive one asks only for a Fisher-combined
#' p below `permissive_p`; the strict one is looser on the p-value but also
#' demands that *every* partner supports the gene. They are not nested by
#' threshold, they are nested by evidence, and the strict list is the one to
#' quote.
#'
#' @param support_p Numeric. Adjusted p below which one partner counts as
#' supporting a gene. Must be in `(0, 1]`. Defaults to `0.1`.
#' @param min_support_fraction Numeric. Minimum supporting fraction for a
#' stratum to enter the staged fit. Must be in `[0, 1]`. Defaults to
#' `0.3333333333333333`.
#' @param min_stratum Integer. Minimum genes in a stratum before it is worth
#' fitting. Defaults to `5L`.
#' @param early_stop_cor Numeric. Correlation between the original score and the
#' running fit at which the staged fit stops early. Must be in `(0, 1]`.
#' Defaults to `0.95`.
#' @param permissive_p Numeric. Fisher-combined p for the permissive gene list,
#' where a gene is carried by partner support rather than by a positive
#' coefficient. Must be in `(0, 1]`. Defaults to `0.001`.
#' @param strict_p Numeric. Fisher-combined p for the strict gene list, which
#' also demands that every partner supports the gene. Must be in `(0, 1]`.
#' Defaults to `0.05`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item support_p - Numeric. Adjusted p below which one partner counts as
#'  supporting a gene. Must be in `(0, 1]`. Defaults to `0.1`.
#'  \item min_support_fraction - Numeric. Minimum supporting fraction for a
#'  stratum to enter the staged fit. Must be in `[0, 1]`. Defaults to
#'  `0.3333333333333333`.
#'  \item min_stratum - Integer. Minimum genes in a stratum before it is worth
#'  fitting. Defaults to `5L`.
#'  \item early_stop_cor - Numeric. Correlation between the original score and
#'  the running fit at which the staged fit stops early. Must be in `(0, 1]`.
#'  Defaults to `0.95`.
#'  \item permissive_p - Numeric. Fisher-combined p for the permissive gene
#'  list, where a gene is carried by partner support rather than by a positive
#'  coefficient. Must be in `(0, 1]`. Defaults to `0.001`.
#'  \item strict_p - Numeric. Fisher-combined p for the strict gene list, which
#'  also demands that every partner supports the gene. Must be in `(0, 1]`.
#'  Defaults to `0.05`.
#' }
#'
#' @references Jerby-Arnon & Regev, Nature Biotechnology, 2022
#'
#' @export
params_dialogue_refine <- function(
  support_p = 0.1,
  min_support_fraction = 0.3333333333333333,
  min_stratum = 5L,
  early_stop_cor = 0.95,
  permissive_p = 0.001,
  strict_p = 0.05
) {
  # Checks
  checkmate::qassert(support_p, "N1(0,1]")
  checkmate::qassert(min_support_fraction, "N1[0,1]")
  checkmate::qassert(min_stratum, "I1[0,)")
  checkmate::qassert(early_stop_cor, "N1(0,1]")
  checkmate::qassert(permissive_p, "N1(0,1]")
  checkmate::qassert(strict_p, "N1(0,1]")

  # Return
  list(
    support_p = support_p,
    min_support_fraction = min_support_fraction,
    min_stratum = min_stratum,
    early_stop_cor = early_stop_cor,
    permissive_p = permissive_p,
    strict_p = strict_p
  )
}

#' Wrapper function for parameters for the edgeR quasi-likelihood workflow
#'
#' @description Parameters for the edgeR quasi-likelihood chain, implemented in
#' Rust via the `edge-rs` crate and gated against edgeR 4.8.2. Defaults are
#' edgeR's own. The `legacy` switch picks between two genuinely different
#' pipelines. The current route estimates its own dispersion from the most
#' abundant genes and skips `estimateDisp()`, which is where most of the runtime
#' went and is edgeR 4's own recommendation. The legacy route shrinks the raw
#' residual deviance, needs a dispersion handed to it, and is the only one where
#' the Poisson bound bites.
#'
#' @param norm_method String. Library size normalisation. `"none"` leaves every
#' factor at one, which is what Milo's `logMS` amounts to. One of `c("TMM",
#' "TMMwsp", "RLE", "upperquartile", "none")`. Defaults to `"TMM"`.
#' @param filter Boolean. Run `filterByExpr()` before fitting. Turn this off for
#' anything that is not gene expression, e.g. Milo neighbourhood counts, where
#' the heuristic means nothing. Defaults to `TRUE`.
#' @param min_mean Numeric. Drop features whose mean count across samples is
#' below this. Applied on top of `filter`. Defaults to `0.0`.
#' @param robust Boolean. Robust empirical Bayes squeezing, giving outlier
#' features their own smaller prior degrees of freedom. Defaults to `FALSE`.
#' @param legacy Boolean. Take edgeR's pre-4.0 quasi-likelihood pipeline.
#' Defaults to `FALSE`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item norm_method - String. Library size normalisation. `"none"` leaves
#'  every factor at one, which is what Milo's `logMS` amounts to. One of
#'  `c("TMM", "TMMwsp", "RLE", "upperquartile", "none")`. Defaults to `"TMM"`.
#'  \item filter - Boolean. Run `filterByExpr()` before fitting. Turn this off
#'  for anything that is not gene expression, e.g. Milo neighbourhood counts,
#'  where the heuristic means nothing. Defaults to `TRUE`.
#'  \item min_mean - Numeric. Drop features whose mean count across samples is
#'  below this. Applied on top of `filter`. Defaults to `0.0`.
#'  \item robust - Boolean. Robust empirical Bayes squeezing, giving outlier
#'  features their own smaller prior degrees of freedom. Defaults to `FALSE`.
#'  \item legacy - Boolean. Take edgeR's pre-4.0 quasi-likelihood pipeline.
#'  Defaults to `FALSE`.
#' }
#'
#' @references Chen, Lun and Smyth, F1000Research, 2016
#'
#' @export
params_edger_ql <- function(
  norm_method = c("TMM", "TMMwsp", "RLE", "upperquartile", "none"),
  filter = TRUE,
  min_mean = 0.0,
  robust = FALSE,
  legacy = FALSE
) {
  norm_method <- match.arg(norm_method)

  # Checks
  checkmate::assertChoice(
    norm_method,
    c("TMM", "TMMwsp", "RLE", "upperquartile", "none")
  )
  checkmate::qassert(filter, "B1")
  checkmate::qassert(min_mean, "N1[0,)")
  checkmate::qassert(robust, "B1")
  checkmate::qassert(legacy, "B1")

  # Return
  list(
    norm_method = norm_method,
    filter = filter,
    min_mean = min_mean,
    robust = robust,
    legacy = legacy
  )
}

#' Helper function to generate default parameters for the fast clustering for
#' the doublet detection methods
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item km_type - String. The type of k-means clustering. One of
#'  `c("minibatch", "standard")`. Defaults to `"minibatch"`.
#'  \item n_centroids - Integer or `NULL`. The number of centroids to use.
#'  `NULL` uses `sqrt(N_cells) * 4` centroids. Defaults to `NULL`.
#'  \item kmeans_iters - Integer. Number of maximum k-means iterations. Defaults
#'  to `100L`.
#'  \item batch_size - Integer. Max batch size, capped at `N_cells / 2`
#'  depending on the data set. Defaults to `4098L`.
#' }
#'
#' @export
params_fast_cluster_default <- function() {
  list(
    km_type = "minibatch",
    n_centroids = NULL,
    kmeans_iters = 100L,
    batch_size = 4098L
  )
}

#' Wrapper function to generate resolution parameters for Leiden or Louvain
#' clustering.
#'
#' @param min_res Numeric. Minimum resolution to test. Defaults to `0.1`.
#' @param max_res Numeric. Maximum resolution to test. Defaults to `10.0`.
#' @param number_res Integer. Number of resolutions to test between the
#' `max_res` and `min_res.` Defaults to `15L`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item min_res - Numeric. Minimum resolution to test. Defaults to `0.1`.
#'  \item max_res - Numeric. Maximum resolution to test. Defaults to `10.0`.
#'  \item number_res - Integer. Number of resolutions to test between the
#'  `max_res` and `min_res.` Defaults to `15L`.
#' }
#'
#' @export
params_graph_resolution <- function(
  min_res = 0.1,
  max_res = 10.0,
  number_res = 15L
) {
  # Checks
  checkmate::qassert(min_res, "R1")
  checkmate::qassert(max_res, "R1")
  checkmate::qassert(number_res, "I1")

  # Return
  list(
    min_res = min_res,
    max_res = max_res,
    number_res = number_res
  )
}

#' Wrapper function to generate GSEA parameters
#'
#' @param min_size Integer. Minimum number of genes per gene set. Defaults to
#' `5L`.
#' @param max_size Integer. Maximum number of genes per gene set. Defaults to
#' `500L`.
#' @param gsea_param Numeric. GSEA parameter. Defaults to `1.0`.
#' @param sample_size Integer. Number of samples to iterate through for the
#' multi-level implementation of fgsea. Defaults to `101L`.
#' @param eps Numeric. Boundary for calculating the p-value. Used for the multi-
#' level implementation of fgsea. Defaults to `1e-50`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item min_size - Integer. Minimum number of genes per gene set. Defaults to
#'  `5L`.
#'  \item max_size - Integer. Maximum number of genes per gene set. Defaults to
#'  `500L`.
#'  \item gsea_param - Numeric. GSEA parameter. Defaults to `1.0`.
#'  \item sample_size - Integer. Number of samples to iterate through for the
#'  multi-level implementation of fgsea. Defaults to `101L`.
#'  \item eps - Numeric. Boundary for calculating the p-value. Used for the
#'  multi- level implementation of fgsea. Defaults to `1e-50`.
#' }
#'
#' @export
params_gsea <- function(
  min_size = 5L,
  max_size = 500L,
  gsea_param = 1.0,
  sample_size = 101L,
  eps = 1e-50
) {
  # Checks
  checkmate::qassert(min_size, "I1[3,)")
  checkmate::qassert(max_size, "I1[4,)")
  checkmate::qassert(gsea_param, "N1")
  checkmate::qassert(sample_size, "I1")
  checkmate::qassert(eps, "N1")

  # Return
  list(
    min_size = min_size,
    max_size = max_size,
    gsea_param = gsea_param,
    sample_size = sample_size,
    eps = eps
  )
}

#' Wrapper function to generate GSVA parameters
#'
#' @param tau Numeric. Tau parameter, usual recommendation is to use `1.0` here.
#' Larger values emphasise the tails more. Defaults to `1.0`.
#' @param min_size Integer. Minimum number of genes per gene set. Defaults to
#' `5L`.
#' @param max_size Integer. Maximum number of genes per gene set. Defaults to
#' `500L`.
#' @param max_diff Boolean. Scoring mode for GSVA, if `TRUE` = difference; if
#' `FALSE` = larger absolute value. Defaults to `TRUE`.
#' @param abs_rank Boolean. If `TRUE` = pos - neg, `FALSE` = pos + neg. Defaults
#' to `FALSE`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item tau - Numeric. Tau parameter, usual recommendation is to use `1.0`
#'  here. Larger values emphasise the tails more. Defaults to `1.0`.
#'  \item min_size - Integer. Minimum number of genes per gene set. Defaults to
#'  `5L`.
#'  \item max_size - Integer. Maximum number of genes per gene set. Defaults to
#'  `500L`.
#'  \item max_diff - Boolean. Scoring mode for GSVA, if `TRUE` = difference; if
#'  `FALSE` = larger absolute value. Defaults to `TRUE`.
#'  \item abs_rank - Boolean. If `TRUE` = pos - neg, `FALSE` = pos + neg.
#'  Defaults to `FALSE`.
#' }
#'
#' @export
params_gsva <- function(
  tau = 1.0,
  min_size = 5L,
  max_size = 500L,
  max_diff = TRUE,
  abs_rank = FALSE
) {
  # Checks
  checkmate::qassert(tau, "N1")
  checkmate::qassert(min_size, "I1[3,)")
  checkmate::qassert(max_size, "I1[4,)")
  checkmate::qassert(max_diff, "B1")
  checkmate::qassert(abs_rank, "B1")

  # Return
  list(
    tau = tau,
    min_size = min_size,
    max_size = max_size,
    max_diff = max_diff,
    abs_rank = abs_rank
  )
}

#' Helper function to generate HVG defaults
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item min_gene_var_pctl - Numeric. Which percentile of the highly variable
#'  genes to include. Defaults to `0.7`.
#'  \item hvg_method - String. Which method to use to identify HVG. One of
#'  `c("vst", "mvb", "dispersion")`. Defaults to `"vst"`.
#'  \item loess_span - Numeric. In case of `"vst"` the span of the loess
