  )
}

#' Wrapper function for standard ICA parameters
#'
#' @param maxit Integer. Maximum number of iterations for ICA. Defaults to
#' `200L`.
#' @param alpha Numeric. The alpha parameter for the logcosh version of ICA.
#' Should be between 1 to 2. Defaults to `1.0`.
#' @param max_tol Numeric. Should be `0 < max_tol < 1`. Maximum tolerance of the
#' algorithm. Defaults to `1e-04`.
#' @param verbose Boolean. Controls verbosity of the function. Defaults to
#' `FALSE`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item maxit - Integer. Maximum number of iterations for ICA. Defaults to
#'  `200L`.
#'  \item alpha - Numeric. The alpha parameter for the logcosh version of ICA.
#'  Should be between 1 to 2. Defaults to `1.0`.
#'  \item max_tol - Numeric. Should be `0 < max_tol < 1`. Maximum tolerance of
#'  the algorithm. Defaults to `1e-04`.
#'  \item verbose - Boolean. Controls verbosity of the function. Defaults to
#'  `FALSE`.
#' }
#'
#' @export
params_ica_general <- function(
  maxit = 200L,
  alpha = 1.0,
  max_tol = 1e-04,
  verbose = FALSE
) {
  # Checks
  checkmate::qassert(maxit, "I1")
  checkmate::qassert(alpha, "R1[1, 2]")
  checkmate::qassert(max_tol, "R1(0, 1)")
  checkmate::qassert(verbose, "B1")

  # Return
  list(
    maxit = maxit,
    alpha = alpha,
    max_tol = max_tol,
    verbose = verbose
  )
}

#' Wrapper function for ICA ncomp iterations
#'
#' @description Wrapper function to provide parameters through which ncomps to
#' iterate through.
#'
#' @param max_no_comp Integer. Maximum number of ncomp to test. Defaults to
#' `75L`.
#' @param steps Integer. In which steps to move from 5 onwards. Defaults to
#' `5L`.
#' @param custom_seq Integer vector or `NULL`. If you wish to provide a custom
#' version of no_comp to iterate through. If NULL, you will iterate through
#' `c(2, 3, 4, 5, 5 + step, ... max_no_comp - step, max_no_comp)` Defaults to
#' `NULL`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item max_no_comp - Integer. Maximum number of ncomp to test. Defaults to
#'  `75L`.
#'  \item steps - Integer. In which steps to move from 5 onwards. Defaults to
#'  `5L`.
#'  \item custom_seq - Integer vector or `NULL`. If you wish to provide a custom
#'  version of no_comp to iterate through. If NULL, you will iterate through
#'  `c(2, 3, 4, 5, 5 + step, ... max_no_comp - step, max_no_comp)` Defaults to
#'  `NULL`.
#' }
#'
#' @export
params_ica_ncomp <- function(
  max_no_comp = 75L,
  steps = 5L,
  custom_seq = NULL
) {
  # Checks
  checkmate::qassert(max_no_comp, "I1")
  checkmate::qassert(steps, "I1")
  checkmate::qassert(custom_seq, c("I+", "0"))

  # Return
  list(
    max_no_comp = max_no_comp,
    steps = steps,
    custom_seq = custom_seq
  )
}

#' Wrapper function for ICA randomisation
#'
#' @param cross_validate Boolean. Do you want to apply a cross-validation type
#' approach and split the data into `folds` folds to assess within data
#' stability of the component. Defaults to `FALSE`.
#' @param random_init Integer. Number of random initialisations to use. Defaults
#' to `50L`.
#' @param folds Integer. Number of folds to use if `cross_validate` is set to
#' `TRUE`. To note, you will be running `random_init * folds` ICA runs. Defaults
#' to `10L`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item cross_validate - Boolean. Do you want to apply a cross-validation type
#'  approach and split the data into `folds` folds to assess within data
#'  stability of the component. Defaults to `FALSE`.
#'  \item random_init - Integer. Number of random initialisations to use.
#'  Defaults to `50L`.
#'  \item folds - Integer. Number of folds to use if `cross_validate` is set to
#'  `TRUE`. To note, you will be running `random_init * folds` ICA runs.
#'  Defaults to `10L`.
#' }
#'
#' @export
params_ica_randomisation <- function(
  cross_validate = FALSE,
  random_init = 50L,
  folds = 10L
) {
  # Checks
  checkmate::qassert(cross_validate, "B1")
  checkmate::qassert(random_init, "I1")
  checkmate::qassert(folds, "I1")

  # Return
  list(
    cross_validate = cross_validate,
    random_init = random_init,
    folds = folds
  )
}

#' K-mean parameter defaults.
#'
#' @description Helper function to generate defaults for the k-mean clustering
#' were more control is needed.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item k_means_iter - Integer. The number of iterations to use for the
#'  clustering. Defaults to `30L`.
#'  \item k_means_init - String. The initialisation. One of `c("parallel",
#'  "random")`. Defaults to `"parallel"`.
#'  \item gemm - Boolean or `NULL`. Controls which CPU implementation is used by
#'  the method. GEMM is faster with large dimensionality. Defaults to `FALSE`.
#'  \item hamerly - Boolean or `NULL`. Shall a faster exact method be used
#'  leveraging the triangle inequality. Faster on large data sets with large
#'  numbers of centroids. Defaults to `TRUE`.
#' }
#'
#' @export
params_kmeans_defaults <- function() {
  list(
    k_means_iter = 30L,
    k_means_init = "parallel",
    gemm = FALSE,
    hamerly = TRUE
  )
}

#' Helper function to generate kNN defaults
#'
#' @description This function generates various sensible default parameters for
#' all of the different approximate nearest neighbours that are available within
#' this package.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item k - Integer. Number of neighbours. Defaults to `15L`.
#'  \item knn_method - String. Which method to use for the approximate nearest
#'  neighbour search. One of `c("kmknn", "hnsw", "annoy", "nndescent", "ivf",
#'  "exhaustive")`. Defaults to `"kmknn"`.
#'  \item ann_dist - String. Which distance metric to use for the approximate
#'  nearest neighbour search. One of `c("euclidean", "cosine")`. Defaults to
#'  `"euclidean"`.
#'  \item n_trees - Integer. Annoy param: number of trees to generate for Annoy.
#'  Defaults to `50L`.
#'  \item search_budget - Integer or `NULL`. Annoy param: optional search budget
#'  per tree for Annoy. If not provided, it will default to `n_tree * k * 20L`.
#'  Defaults to `NULL`.
#'  \item delta - Numeric. NNDescent param: early termination criterium for
#'  NNDescent. Defaults to `0.001`.
#'  \item diversify_prob - Numeric. NNDescent param: diversification probability
#'  for the NNDescent index. This will diversify the index at the end and
#'  identify potentially better edges. Defaults to `0.0`.
#'  \item ef_budget - Integer or `NULL`. NNDescent param: optional query budget
#'  parameter. Can accelerate querying, but at the cost of Recall. Defaults to
#'  `NULL`.
#'  \item extract_knn - Boolean. NNDescent param: hand back the graph the
#'  descent already built instead of beam searching it. Skips the query pass
#'  entirely, so it is much faster, at the cost of some recall. Rows the descent
#'  never filled come back padded with duplicate edges. Ignored by every other
#'  method. Defaults to `FALSE`.
#'  \item m - Integer. HNSW param: number of connections between layers for
#'  HNSW. Defaults to `16L`.
#'  \item ef_construction - Integer. HNSW param: size of dynamic candidate list
#'  during construction. Defaults to `200L`.
#'  \item ef_search - Integer. HNSW param: size of candidate list (higher =
#'  better recall, slower). Defaults to `100L`.
#'  \item n_list - Integer or `NULL`. IVF param: number of clusters/centroids to
#'  generate. `NULL` generates `sqrt(n)` lists. Defaults to `NULL`.
#'  \item n_probe - Integer or `NULL`. IVF param: number of clusters/centroids
#'  to query. `NULL` queries `sqrt(n_lists)` clusters. Defaults to `NULL`.
#' }
#'
#' @export
params_knn_defaults <- function() {
  list(
    k = 15L,
    knn_method = "kmknn",
    ann_dist = "euclidean",
    n_trees = 50L,
    search_budget = NULL,
    delta = 0.001,
    diversify_prob = 0.0,
    ef_budget = NULL,
    extract_knn = FALSE,
    m = 16L,
    ef_construction = 200L,
    ef_search = 100L,
    n_list = NULL,
    n_probe = NULL
  )
}

#' Wrapper function to generate label propagation parameters
#'
#' @param alpha Numeric. Controls the spreading strength. Higher values anchor
#' labelled nodes more strongly to their original label. Defaults to `0.9`.
#' @param iter Integer. Maximum number of iterations to run. Defaults to `100L`.
#' @param tolerance Numeric. Convergence threshold. Stops early if the maximum
#' change across all nodes falls below this value. Defaults to `1e-06`.
#' @param symmetrise Boolean. Whether to symmetrise the graph. Defaults to
#' `TRUE`.
#' @param symmetry_strategy String. Strategy to resolve weight conflicts when
#' symmetrising. Only relevant when `symmetrise = TRUE` and edge weights are
#' provided. One of `c("average", "avg", "min", "max")`. Defaults to
#' `"average"`.
#' @param max_hops Integer or `NULL`. If provided, restricts label spreading to
#' nodes within this many hops of any labelled node. Nodes beyond this limit
#' remain all-zeroes. Defaults to `NULL`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item alpha - Numeric. Controls the spreading strength. Higher values anchor
#'  labelled nodes more strongly to their original label. Defaults to `0.9`.
#'  \item iter - Integer. Maximum number of iterations to run. Defaults to
#'  `100L`.
#'  \item tolerance - Numeric. Convergence threshold. Stops early if the maximum
#'  change across all nodes falls below this value. Defaults to `1e-06`.
#'  \item symmetrise - Boolean. Whether to symmetrise the graph. Defaults to
#'  `TRUE`.
#'  \item symmetry_strategy - String. Strategy to resolve weight conflicts when
#'  symmetrising. Only relevant when `symmetrise = TRUE` and edge weights are
#'  provided. One of `c("average", "avg", "min", "max")`. Defaults to
#'  `"average"`.
#'  \item max_hops - Integer or `NULL`. If provided, restricts label spreading
#'  to nodes within this many hops of any labelled node. Nodes beyond this limit
#'  remain all-zeroes. Defaults to `NULL`.
#' }
#'
#' @export
params_label_propagation <- function(
  alpha = 0.9,
  iter = 100L,
  tolerance = 1e-06,
  symmetrise = TRUE,
  symmetry_strategy = c("average", "avg", "min", "max"),
  max_hops = NULL
) {
  symmetry_strategy <- match.arg(symmetry_strategy)

  # Checks
  checkmate::qassert(alpha, "R1[0, 1]")
  checkmate::qassert(iter, "I1[1,]")
  checkmate::qassert(tolerance, "R1")
  checkmate::qassert(symmetrise, "B1")
  checkmate::assertChoice(symmetry_strategy, c("average", "avg", "min", "max"))
  checkmate::qassert(max_hops, c("I1[0,]", "0"))

  # Return
  list(
    alpha = alpha,
    iter = iter,
    tolerance = tolerance,
    symmetrise = symmetrise,
    symmetry_strategy = symmetry_strategy,
    max_hops = max_hops
  )
}

#' Wrapper function for the LDA parameters
#'
#' @description Solver options for the variational Bayes latent Dirichlet
#' allocation, see [bixverse::run_lda()].
#'
#' @details
#' The defaults follow pycisTopic, so the knobs mean the same thing on both
#' sides. `alpha_by_topic = TRUE` turns `alpha` into the Griffiths and
#' Steyvers `50 / k` heuristic that cisTopic defaults to; set it to `FALSE` if
#' you want `alpha` taken literally.
#'
#' `learning = "batch"` sweeps every document once per iteration and is
#' monotone in the bound. `"online"` takes decaying steps from shuffled
#' mini-batches, which reaches a usable fit in far fewer passes on a large
#' corpus at the cost of that guarantee. `batch_size` and `n_epochs` are only
#' read by the online variant.
#'
#' @param alpha Numeric. Dirichlet prior on the document-topic distributions.
#' Defaults to `50.0`.
#' @param alpha_by_topic Boolean. Shall `alpha` be divided by the topic count.
#' Defaults to `TRUE`.
#' @param eta Numeric. Dirichlet prior on the topic-term distributions. Defaults
#' to `0.1`.
#' @param eta_by_topic Boolean. Shall `eta` be divided by the topic count.
#' Defaults to `FALSE`.
#' @param max_iter Integer. Maximum outer iterations. Ignored by the online
#' variant, which counts epochs instead. Defaults to `150L`.
#' @param tol Numeric. Relative change in the bound below which the solver
#' stops. Defaults to `0.001`.
#' @param inner_max_iter Integer. Maximum fixed-point iterations of the
#' per-document E-step. Defaults to `100L`.
#' @param inner_tol Numeric. Relative L1 change in the variational parameters
#' below which the per-document E-step stops. Defaults to `0.001`.
#' @param check_every Integer. Iterations between bound evaluations. Defaults to
#' `10L`.
#' @param learning String. Batch or online variational inference. One of
#' `c("batch", "online")`. Defaults to `"batch"`.
#' @param batch_size Integer. Documents per mini-batch. Online only. Defaults to
#' `1024L`.
#' @param n_epochs Integer. Passes over the corpus. Online only. Defaults to
#' `10L`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item alpha - Numeric. Dirichlet prior on the document-topic distributions.
#'  Defaults to `50.0`.
#'  \item alpha_by_topic - Boolean. Shall `alpha` be divided by the topic count.
#'  Defaults to `TRUE`.
#'  \item eta - Numeric. Dirichlet prior on the topic-term distributions.
#'  Defaults to `0.1`.
#'  \item eta_by_topic - Boolean. Shall `eta` be divided by the topic count.
#'  Defaults to `FALSE`.
#'  \item max_iter - Integer. Maximum outer iterations. Ignored by the online
#'  variant, which counts epochs instead. Defaults to `150L`.
#'  \item tol - Numeric. Relative change in the bound below which the solver
#'  stops. Defaults to `0.001`.
#'  \item inner_max_iter - Integer. Maximum fixed-point iterations of the
#'  per-document E-step. Defaults to `100L`.
#'  \item inner_tol - Numeric. Relative L1 change in the variational parameters
#'  below which the per-document E-step stops. Defaults to `0.001`.
#'  \item check_every - Integer. Iterations between bound evaluations. Defaults
#'  to `10L`.
#'  \item learning - String. Batch or online variational inference. One of
#'  `c("batch", "online")`. Defaults to `"batch"`.
#'  \item batch_size - Integer. Documents per mini-batch. Online only. Defaults
#'  to `1024L`.
#'  \item n_epochs - Integer. Passes over the corpus. Online only. Defaults to
#'  `10L`.
#' }
#'
#' @references Hoffman, Blei and Bach, NIPS, 2010; Bravo Gonzalez-Blas, et al.,
#' Nat Methods, 2019
#'
#' @export
params_lda <- function(
  alpha = 50.0,
  alpha_by_topic = TRUE,
  eta = 0.1,
  eta_by_topic = FALSE,
  max_iter = 150L,
  tol = 0.001,
  inner_max_iter = 100L,
  inner_tol = 0.001,
  check_every = 10L,
  learning = c("batch", "online"),
  batch_size = 1024L,
  n_epochs = 10L
) {
  learning <- match.arg(learning)

  # Checks
  checkmate::qassert(alpha, "N1(0,)")
  checkmate::qassert(alpha_by_topic, "B1")
  checkmate::qassert(eta, "N1(0,)")
  checkmate::qassert(eta_by_topic, "B1")
  checkmate::qassert(max_iter, "I1[1,)")
  checkmate::qassert(tol, "N1(0,)")
  checkmate::qassert(inner_max_iter, "I1[1,)")
  checkmate::qassert(inner_tol, "N1(0,)")
  checkmate::qassert(check_every, "I1[1,)")
  checkmate::assertChoice(learning, c("batch", "online"))
  checkmate::qassert(batch_size, "I1[1,)")
  checkmate::qassert(n_epochs, "I1[1,)")

  # Return
  list(
    alpha = alpha,
    alpha_by_topic = alpha_by_topic,
    eta = eta,
    eta_by_topic = eta_by_topic,
    max_iter = max_iter,
    tol = tol,
    inner_max_iter = inner_max_iter,
    inner_tol = inner_tol,
    check_every = check_every,
    learning = learning,
    batch_size = batch_size,
    n_epochs = n_epochs
  )
}

#' Parameters for ligand to target influence computation
#'
#' @param lr_sig_hub Numeric. Numeric in `[0, 1]`. Hub correction strength for
#' the ligand-receptor / signalling layer. 0 disables correction. Defaults to
#' `0.0`.
#' @param gr_hub Numeric. Numeric in `[0, 1]`. Hub correction strength for the
#' gene regulatory layer. 0 disables correction. Defaults to `0.0`.
#' @param ltf_cutoff Numeric. Numeric in `[0, 1]`. Quantile cutoff applied to
#' the intermediate ligand-to-TF matrix. Defaults to `0.99`.
#' @param damping_factor Numeric. Numeric in `[0, 1]`. PageRank-style damping
#' factor. Defaults to `0.5`.
#' @param tol Numeric. Numeric > 0. Convergence tolerance for the propagation
#' step. Defaults to `1e-06`.
#' @param max_iter Integer. Integer >= 1. Maximum iterations for the propagation
#' step. Defaults to `1000L`.
#' @param topology_correction Boolean. Apply topology correction. Defaults to
#' `FALSE`.
#' @param secondary_targets Boolean. Run a second round through targets.
#' Defaults to `FALSE`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item lr_sig_hub - Numeric. Numeric in `[0, 1]`. Hub correction strength for
#'  the ligand-receptor / signalling layer. 0 disables correction. Defaults to
#'  `0.0`.
#'  \item gr_hub - Numeric. Numeric in `[0, 1]`. Hub correction strength for the
#'  gene regulatory layer. 0 disables correction. Defaults to `0.0`.
#'  \item ltf_cutoff - Numeric. Numeric in `[0, 1]`. Quantile cutoff applied to
#'  the intermediate ligand-to-TF matrix. Defaults to `0.99`.
#'  \item damping_factor - Numeric. Numeric in `[0, 1]`. PageRank-style damping
#'  factor. Defaults to `0.5`.
#'  \item tol - Numeric. Numeric > 0. Convergence tolerance for the propagation
#'  step. Defaults to `1e-06`.
#'  \item max_iter - Integer. Integer >= 1. Maximum iterations for the
#'  propagation step. Defaults to `1000L`.
#'  \item topology_correction - Boolean. Apply topology correction. Defaults to
#'  `FALSE`.
#'  \item secondary_targets - Boolean. Run a second round through targets.
#'  Defaults to `FALSE`.
#' }
#'
#' @export
params_ligand_target <- function(
  lr_sig_hub = 0.0,
  gr_hub = 0.0,
  ltf_cutoff = 0.99,
  damping_factor = 0.5,
  tol = 1e-06,
  max_iter = 1000L,
  topology_correction = FALSE,
  secondary_targets = FALSE
) {
  # Checks
  checkmate::qassert(lr_sig_hub, "N1[0,1]")
  checkmate::qassert(gr_hub, "N1[0,1]")
  checkmate::qassert(ltf_cutoff, "N1[0,1]")
  checkmate::qassert(damping_factor, "N1[0,1]")
  checkmate::qassert(tol, "N1(0,)")
  checkmate::qassert(max_iter, "X1[1,)")
  checkmate::qassert(topology_correction, "B1")
  checkmate::qassert(secondary_targets, "B1")

  max_iter <- as.integer(max_iter)

  # Return
  list(
    lr_sig_hub = lr_sig_hub,
    gr_hub = gr_hub,
    ltf_cutoff = ltf_cutoff,
    damping_factor = damping_factor,
    tol = tol,
    max_iter = max_iter,
    topology_correction = topology_correction,
    secondary_targets = secondary_targets
  )
}

#' Wrapper function for parameters for the limma-voom workflow
#'
#' @description Parameters for the limma linear model chain, implemented in Rust
#' via the `edge-rs` crate and gated against limma 3.66.0. Defaults are limma's
#' own, except for `filter`: inside [bixverse::BulkDge()] the genes were already
#' filtered by [bixverse::qc_bulk_dge()]. `route = "voom"` is `voomLmFit()`:
#' precision weights from the mean-variance trend, then weighted least squares.
#' `route = "trend"` is limma-trend: log-CPM straight into `lmFit()`, with the
#' trend absorbed by `eBayes(trend = TRUE)`. The empirical Bayes trend follows
#' the route.
#'
#' @param route String. Whether to run the voom or the limma-trend route. One of
#' `c("voom", "trend")`. Defaults to `"voom"`.
#' @param norm_method String. Library size normalisation. One of `c("TMM",
#' "TMMwsp", "RLE", "upperquartile", "none")`. Defaults to `"TMM"`.
#' @param filter Boolean. Run `filterByExpr()` before fitting. Defaults to
#' `FALSE`.
#' @param min_mean Numeric. Drop genes whose mean count across samples is below
#' this. Applied on top of `filter`. Defaults to `0.0`.
#' @param robust Boolean. Robust empirical Bayes, `eBayes(robust = TRUE)`.
#' Defaults to `FALSE`.
#' @param prior_count Numeric or `NULL`. Count added before the log. `NULL`
#' takes the route's own default, `0.5` for voom and `2` for trend. Defaults to
#' `NULL`.
#' @param adaptive_span Boolean. Derive the lowess span from the number of
#' genes, as limma does since 3.56. Only used by voom. Defaults to `TRUE`.
#' @param span Numeric. Lowess span for the voom trend, only read if
#' `adaptive_span = FALSE`. Defaults to `0.5`.
#' @param proportion Numeric. Assumed proportion of differentially expressed
#' genes, only used for the B-statistic. Defaults to `0.01`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item route - String. Whether to run the voom or the limma-trend route. One
#'  of `c("voom", "trend")`. Defaults to `"voom"`.
#'  \item norm_method - String. Library size normalisation. One of `c("TMM",
#'  "TMMwsp", "RLE", "upperquartile", "none")`. Defaults to `"TMM"`.
#'  \item filter - Boolean. Run `filterByExpr()` before fitting. Defaults to
#'  `FALSE`.
#'  \item min_mean - Numeric. Drop genes whose mean count across samples is
#'  below this. Applied on top of `filter`. Defaults to `0.0`.
#'  \item robust - Boolean. Robust empirical Bayes, `eBayes(robust = TRUE)`.
#'  Defaults to `FALSE`.
#'  \item prior_count - Numeric or `NULL`. Count added before the log. `NULL`
#'  takes the route's own default, `0.5` for voom and `2` for trend. Defaults to
#'  `NULL`.
#'  \item adaptive_span - Boolean. Derive the lowess span from the number of
#'  genes, as limma does since 3.56. Only used by voom. Defaults to `TRUE`.
#'  \item span - Numeric. Lowess span for the voom trend, only read if
#'  `adaptive_span = FALSE`. Defaults to `0.5`.
#'  \item proportion - Numeric. Assumed proportion of differentially expressed
#'  genes, only used for the B-statistic. Defaults to `0.01`.
#' }
#'
#' @references Law, et al., Genome Biol, 2014; Smyth, Stat Appl Genet Mol Biol,
#' 2004
#'
#' @export
params_limma_voom <- function(
  route = c("voom", "trend"),
  norm_method = c("TMM", "TMMwsp", "RLE", "upperquartile", "none"),
  filter = FALSE,
  min_mean = 0.0,
  robust = FALSE,
  prior_count = NULL,
  adaptive_span = TRUE,
  span = 0.5,
  proportion = 0.01
) {
  route <- match.arg(route)
  norm_method <- match.arg(norm_method)

  # Checks
  checkmate::assertChoice(route, c("voom", "trend"))
  checkmate::assertChoice(
    norm_method,
    c("TMM", "TMMwsp", "RLE", "upperquartile", "none")
  )
  checkmate::qassert(filter, "B1")
  checkmate::qassert(min_mean, "N1[0,)")
  checkmate::qassert(robust, "B1")
  checkmate::qassert(prior_count, c("N1(0,)", "0"))
  checkmate::qassert(adaptive_span, "B1")
  checkmate::qassert(span, "N1(0,1]")
  checkmate::qassert(proportion, "N1(0,1)")

  # Return
  list(
    route = route,
    norm_method = norm_method,
    filter = filter,
    min_mean = min_mean,
    robust = robust,
    prior_count = prior_count,
    adaptive_span = adaptive_span,
    span = span,
    proportion = proportion
  )
}

#' Constructor for MELD parameters
#'
#' @param beta Numeric. Smoothing strength; larger values produce smoother
#' densities. Must be strictly positive. Defaults to `60.0`.
#' @param offset Numeric. Shift of the filter centre in the rescaled spectrum.
#' Must be in `[0, 1]`. Defaults to `0.0`.
#' @param order Numeric. Filter falloff sharpness; larger values approach a
#' square low-pass. Must be strictly positive. Defaults to `1.0`.
#' @param filter String. Filter family to use. One of `c("heat", "laplacian")`.
#' Defaults to `"heat"`.
#' @param chebyshev_order Integer. Number of Chebyshev coefficients (polynomial
#' terms). Must be >= 2. Defaults to `50L`.
#' @param lap_type String. Type of Laplacian to use for spectral filtering. One
#' of `c("combinatorial", "normalised")`. Defaults to `"combinatorial"`.
#' @param normalise_indicators Boolean. If `TRUE`, each column of the indicator
#' matrix is divided by its column sum before filtering, making cross-condition
#' densities comparable regardless of cells-per-condition. Defaults to `TRUE`.
#' @param knn List. Optional overrides for kNN parameters. See
#' [bixverse::params_knn_defaults()] for available parameters: `k`,
#' `knn_method`, `ann_dist`, `search_budget`, `n_trees`, `delta`,
#' `diversify_prob`, `ef_budget`, `m`, `ef_construction`, `ef_search`, `n_list`
#' and `n_probe`. See [params_knn_defaults()] for the available elements.
#' Defaults to `list()`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item The elements of [params_knn_defaults()], overridden by `knn`, spliced
#'  in at this position.
#'  \item beta - Numeric. Smoothing strength; larger values produce smoother
#'  densities. Must be strictly positive. Defaults to `60.0`.
#'  \item offset - Numeric. Shift of the filter centre in the rescaled spectrum.
#'  Must be in `[0, 1]`. Defaults to `0.0`.
#'  \item order - Numeric. Filter falloff sharpness; larger values approach a
#'  square low-pass. Must be strictly positive. Defaults to `1.0`.
#'  \item filter - String. Filter family to use. One of `c("heat",
#'  "laplacian")`. Defaults to `"heat"`.
#'  \item chebyshev_order - Integer. Number of Chebyshev coefficients
#'  (polynomial terms). Must be >= 2. Defaults to `50L`.
#'  \item lap_type - String. Type of Laplacian to use for spectral filtering.
#'  One of `c("combinatorial", "normalised")`. Defaults to `"combinatorial"`.
#'  \item normalise_indicators - Boolean. If `TRUE`, each column of the
#'  indicator matrix is divided by its column sum before filtering, making
#'  cross-condition densities comparable regardless of cells-per-condition.
#'  Defaults to `TRUE`.
#' }
#'
#' @export
params_meld <- function(
  beta = 60.0,
  offset = 0.0,
  order = 1.0,
  filter = c("heat", "laplacian"),
  chebyshev_order = 50L,
  lap_type = c("combinatorial", "normalised"),
  normalise_indicators = TRUE,
  knn = list()
) {
  filter <- match.arg(filter)
  lap_type <- match.arg(lap_type)

  # Checks
  checkmate::qassert(beta, "N1(0,)")
  checkmate::qassert(offset, "N1[0,1]")
  checkmate::qassert(order, "N1(0,)")
  checkmate::assertChoice(filter, c("heat", "laplacian"))
  checkmate::qassert(chebyshev_order, "I1[2,)")
  checkmate::assertChoice(lap_type, c("combinatorial", "normalised"))
  checkmate::qassert(normalise_indicators, "B1")

  # Merge
  knn <- utils::modifyList(params_knn_defaults(), knn, keep.null = TRUE)

  # Return
  c(
    knn,
    list(
      beta = beta,
      offset = offset,
      order = order,
      filter = filter,
      chebyshev_order = chebyshev_order,
      lap_type = lap_type,
      normalise_indicators = normalise_indicators
    )
  )
}

#' Wrapper function to generate module membership parameters
#'
#' @description Controls how a `gene x k` loading matrix from ICA, NMF or DGRDL
#' is turned into module membership. Genes are kept where they sit in the tail
#' of a component's loading distribution, which means membership is not
#' exclusive: a gene loading strongly on three components belongs to three
#' modules. Genes in no tail belong to nothing, which is the background category
#' an argmax assignment cannot give you.
#'
#' @param method String. `"zscore"` standardises each component and keeps
#' `abs(z) > cutoff`. `"fdr"` converts to two-sided p-values against a Normal
#' null fitted the same way, Benjamini-Hochberg adjusts, and keeps `padj < fdr`.
#' One of `c("zscore", "fdr")`. Defaults to `"zscore"`.
#' @param cutoff Numeric. Absolute z threshold for `method = "zscore"`. Defaults
#' to `3.0`.
#' @param fdr Numeric. Adjusted p-value threshold for `method = "fdr"`. Defaults
#' to `0.05`.
#' @param tails String. `"auto"` uses an upper-tail-only test when every loading
#' is non-negative (the NMF case) and a two-sided one otherwise. `"upper"` and
#' `"both"` force the choice. One of `c("auto", "upper", "both")`. Defaults to
#' `"auto"`.
#' @param scaling String. `"robust"` centres and scales each component by its
#' median and MAD. `"standard"` uses the mean and standard deviation instead,
#' which is stricter and less forgiving of skewed loadings (e.g. NMF). One of
#' `c("robust", "standard")`. Defaults to `"robust"`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item method - String. `"zscore"` standardises each component and keeps
#'  `abs(z) > cutoff`. `"fdr"` converts to two-sided p-values against a Normal
#'  null fitted the same way, Benjamini-Hochberg adjusts, and keeps `padj <
#'  fdr`. One of `c("zscore", "fdr")`. Defaults to `"zscore"`.
#'  \item cutoff - Numeric. Absolute z threshold for `method = "zscore"`.
#'  Defaults to `3.0`.
#'  \item fdr - Numeric. Adjusted p-value threshold for `method = "fdr"`.
#'  Defaults to `0.05`.
#'  \item tails - String. `"auto"` uses an upper-tail-only test when every
#'  loading is non-negative (the NMF case) and a two-sided one otherwise.
#'  `"upper"` and `"both"` force the choice. One of `c("auto", "upper",
#'  "both")`. Defaults to `"auto"`.
#'  \item scaling - String. `"robust"` centres and scales each component by its
#'  median and MAD. `"standard"` uses the mean and standard deviation instead,
#'  which is stricter and less forgiving of skewed loadings (e.g. NMF). One of
#'  `c("robust", "standard")`. Defaults to `"robust"`.
#' }
#'
#' @references Biton, et al., Cell Rep, 2014
#'
#' @export
params_module_membership <- function(
  method = c("zscore", "fdr"),
  cutoff = 3.0,
  fdr = 0.05,
  tails = c("auto", "upper", "both"),
  scaling = c("robust", "standard")
) {
  method <- match.arg(method)
  tails <- match.arg(tails)
  scaling <- match.arg(scaling)

  # Checks
  checkmate::assertChoice(method, c("zscore", "fdr"))
  checkmate::qassert(cutoff, "N1(0,)")
  checkmate::qassert(fdr, "N1(0,1]")
  checkmate::assertChoice(tails, c("auto", "upper", "both"))
  checkmate::assertChoice(scaling, c("robust", "standard"))

  # Return
  list(
    method = method,
    cutoff = cutoff,
    fdr = fdr,
    tails = tails,
    scaling = scaling
  )
}

#' Wrapper function for parameters for NEBULA
#'
#' @description Parameters for the NEBULA negative binomial gamma mixed model,
#' implemented in Rust via the `edge-rs` crate and ported from the `nebula`
#' package's own C++. Defaults are the R package's own. NEBULA splits the
#' variance into a subject-level random effect and a cell-level overdispersion.
#' Run it on meta cells and the cell-level term becomes the spread between
#' aggregates within a subject rather than between cells, so it is smaller and
#' absorbs whatever the aggregation smoothed away. The subject-level term keeps
#' its meaning either way.
#'
#' @param nebula_method String. Which variant to run. NEBULA downgrades `"ln"`
#' to `"hl"` below 30 cells per subject, as the R package does. One of `c("ln",
#' "hl")`. Defaults to `"ln"`.
#' @param min_sigma Numeric. Lower bound on the subject-level overdispersion.
#' Defaults to `1e-04`.
#' @param min_phi Numeric. Lower bound on the cell-level overdispersion.
#' Defaults to `1e-04`.
#' @param max_sigma Numeric. Upper bound on the subject-level overdispersion.
#' Defaults to `10.0`.
#' @param max_phi Numeric. Upper bound on the cell-level overdispersion.
#' Defaults to `1000.0`.
#' @param cutoff_cell Numeric. Refit both overdispersions when the product of
#' the cells per subject and the estimated `phi` falls below this. Defaults to
#' `20.0`.
#' @param kappa Numeric. Threshold on NEBULA's `kappa_obs` above which the
#' subject-level overdispersion from stage one is trusted as is. Defaults to
#' `800.0`.
#' @param cpc Numeric. Drop a gene whose mean count per cell is at most this.
#' Defaults to `0.005`.
#' @param mincp Integer. Drop a gene expressed in fewer than this many cells.
#' Defaults to `5L`.
#' @param reml Boolean. Estimate the overdispersions by restricted maximum
#' likelihood. The R package only honours this for `NBLMM`, which the Rust port
#' does not implement, so this arm has not been validated against an R
#' reference. Leave it off unless you know why you want it. Defaults to `FALSE`.
#' @param eps Numeric. Absolute stopping tolerance for the optimiser. Defaults
#' to `1e-06`.
#' @param gene_batch_size Integer. Genes read and fitted per batch. Bounds how
#' much of the store is resident at once and changes nothing about the answer,
#' since NEBULA is gene-independent. Defaults to `1000L`.
#' @param shrink_dispersion Boolean. Shrink the cell-level overdispersions
#' towards an empirical Bayes prior once the sweep is done. Defaults to `TRUE`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item nebula_method - String. Which variant to run. NEBULA downgrades `"ln"`
#'  to `"hl"` below 30 cells per subject, as the R package does. One of `c("ln",
#'  "hl")`. Defaults to `"ln"`.
#'  \item min_sigma - Numeric. Lower bound on the subject-level overdispersion.
#'  Defaults to `1e-04`.
#'  \item min_phi - Numeric. Lower bound on the cell-level overdispersion.
#'  Defaults to `1e-04`.
#'  \item max_sigma - Numeric. Upper bound on the subject-level overdispersion.
#'  Defaults to `10.0`.
#'  \item max_phi - Numeric. Upper bound on the cell-level overdispersion.
#'  Defaults to `1000.0`.
#'  \item cutoff_cell - Numeric. Refit both overdispersions when the product of
#'  the cells per subject and the estimated `phi` falls below this. Defaults to
#'  `20.0`.
#'  \item kappa - Numeric. Threshold on NEBULA's `kappa_obs` above which the
#'  subject-level overdispersion from stage one is trusted as is. Defaults to
#'  `800.0`.
#'  \item cpc - Numeric. Drop a gene whose mean count per cell is at most this.
#'  Defaults to `0.005`.
#'  \item mincp - Integer. Drop a gene expressed in fewer than this many cells.
#'  Defaults to `5L`.
#'  \item reml - Boolean. Estimate the overdispersions by restricted maximum
#'  likelihood. The R package only honours this for `NBLMM`, which the Rust port
#'  does not implement, so this arm has not been validated against an R
#'  reference. Leave it off unless you know why you want it. Defaults to
#'  `FALSE`.
#'  \item eps - Numeric. Absolute stopping tolerance for the optimiser. Defaults
#'  to `1e-06`.
#'  \item gene_batch_size - Integer. Genes read and fitted per batch. Bounds how
#'  much of the store is resident at once and changes nothing about the answer,
#'  since NEBULA is gene-independent. Defaults to `1000L`.
#'  \item shrink_dispersion - Boolean. Shrink the cell-level overdispersions
#'  towards an empirical Bayes prior once the sweep is done. Defaults to `TRUE`.
#' }
#'
#' @references He, et al., Commun Biol, 2021
#'
#' @export
params_nebula <- function(
  nebula_method = c("ln", "hl"),
  min_sigma = 1e-04,
  min_phi = 1e-04,
  max_sigma = 10.0,
  max_phi = 1000.0,
  cutoff_cell = 20.0,
  kappa = 800.0,
  cpc = 0.005,
  mincp = 5L,
  reml = FALSE,
  eps = 1e-06,
  gene_batch_size = 1000L,
  shrink_dispersion = TRUE
) {
  nebula_method <- match.arg(nebula_method)

  # Checks
  checkmate::assertChoice(nebula_method, c("ln", "hl"))
  checkmate::qassert(min_sigma, "N1(0,)")
  checkmate::qassert(min_phi, "N1(0,)")
  checkmate::qassert(max_sigma, "N1(0,)")
  checkmate::qassert(max_phi, "N1(0,)")
  checkmate::qassert(cutoff_cell, "N1[0,)")
  checkmate::qassert(kappa, "N1[0,)")
  checkmate::qassert(cpc, "N1[0,)")
  checkmate::qassert(mincp, "I1[0,)")
  checkmate::qassert(reml, "B1")
  checkmate::qassert(eps, "N1(0,)")
  checkmate::qassert(gene_batch_size, "I1[1,)")
  checkmate::qassert(shrink_dispersion, "B1")

  if (min_sigma >= max_sigma) {
    stop("`min_sigma` needs to be below `max_sigma`.")
  }
  if (min_phi >= max_phi) {
    stop("`min_phi` needs to be below `max_phi`.")
  }

  # Return
  list(
    nebula_method = nebula_method,
    min_sigma = min_sigma,
    min_phi = min_phi,
    max_sigma = max_sigma,
    max_phi = max_phi,
    cutoff_cell = cutoff_cell,
    kappa = kappa,
    cpc = cpc,
    mincp = mincp,
    reml = reml,
    eps = eps,
    gene_batch_size = gene_batch_size,
    shrink_dispersion = shrink_dispersion
  )
}

#' Wrapper function for consensus NMF parameters
#'
#' @description Controls the clustering step of consensus NMF: the components of
#' every restart are pooled, outliers are dropped by local density, and the
#' survivors are k-means clustered into `k` groups whose median becomes the
#' consensus factor.
#'
#' @param consensus_target String. `"h"` clusters the gene programmes (the
#' spectra), which is what cNMF does and what you almost always want. `"w"`
#' clusters in sample space instead, which on single cell data means cell space:
#' it pools a dense `(k * n_runs) x n_cells` matrix and runs an exhaustive
#' cosine search over it, so it gets expensive fast. One of `c("h", "w")`.
#' Defaults to `"h"`.
#' @param n_neighbours Integer. Neighbours used for the local density estimate.
#' `0L` picks `ceiling(0.3 * n_runs)` for you. Defaults to `0L`.
#' @param density_threshold Numeric. Components whose mean cosine distance to
#' their neighbours exceeds this are dropped as unstable. Cosine distance cannot
#' exceed 2, so any value `>= 2` disables the filter entirely. Defaults to
#' `0.5`.
#' @param kmeans_iters Integer. Maximum k-means iterations. Defaults to `100L`.
#' @param kmeans_n_init Integer. Number of k-means restarts. Defaults to `3L`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item consensus_target - String. `"h"` clusters the gene programmes (the
#'  spectra), which is what cNMF does and what you almost always want. `"w"`
#'  clusters in sample space instead, which on single cell data means cell
#'  space: it pools a dense `(k * n_runs) x n_cells` matrix and runs an
#'  exhaustive cosine search over it, so it gets expensive fast. One of `c("h",
#'  "w")`. Defaults to `"h"`.
#'  \item n_neighbours - Integer. Neighbours used for the local density
#'  estimate. `0L` picks `ceiling(0.3 * n_runs)` for you. Defaults to `0L`.
#'  \item density_threshold - Numeric. Components whose mean cosine distance to
#'  their neighbours exceeds this are dropped as unstable. Cosine distance
#'  cannot exceed 2, so any value `>= 2` disables the filter entirely. Defaults
#'  to `0.5`.
#'  \item kmeans_iters - Integer. Maximum k-means iterations. Defaults to
#'  `100L`.
#'  \item kmeans_n_init - Integer. Number of k-means restarts. Defaults to `3L`.
#' }
#'
#' @references Kotliar et al., eLife, 2019
#'
#' @export
params_nmf_consensus <- function(
  consensus_target = c("h", "w"),
  n_neighbours = 0L,
  density_threshold = 0.5,
  kmeans_iters = 100L,
  kmeans_n_init = 3L
) {
  consensus_target <- match.arg(consensus_target)

  # Checks
  checkmate::assertChoice(consensus_target, c("h", "w"))
  checkmate::qassert(n_neighbours, "I1[0,)")
  checkmate::qassert(density_threshold, "N1[0,2]")
  checkmate::qassert(kmeans_iters, "I1[1,)")
  checkmate::qassert(kmeans_n_init, "I1[1,)")

  # Return
  list(
    consensus_target = consensus_target,
    n_neighbours = n_neighbours,
    density_threshold = density_threshold,
    kmeans_iters = kmeans_iters,
    kmeans_n_init = kmeans_n_init
  )
}

#' Wrapper function for NMF (HALS) parameters
#'
#' @param max_iter Integer. Maximum number of HALS iterations. Defaults to
#' `250L`.
#' @param tol Numeric. Convergence tolerance on the relative change in
#' reconstruction loss. Defaults to `1e-04`.
#' @param eps Numeric. Numerical floor for non-negativity / division safety.
#' Defaults to `1e-10`.
#' @param check_every Integer. Convergence check interval in iterations.
#' Defaults to `10L`.
#' @param nmf_init String. `"nndsvd"` and `"svd"` both map to deterministic
#' NNDSVD initialisation; `"random"` uses random non-negative draws. For
#' stabilised (multi-run) NMF this field is ignored and random init is always
#' used. One of `c("nndsvd", "svd", "random")`. Defaults to `"nndsvd"`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item max_iter - Integer. Maximum number of HALS iterations. Defaults to
#'  `250L`.
#'  \item tol - Numeric. Convergence tolerance on the relative change in
#'  reconstruction loss. Defaults to `1e-04`.
#'  \item eps - Numeric. Numerical floor for non-negativity / division safety.
#'  Defaults to `1e-10`.
#'  \item check_every - Integer. Convergence check interval in iterations.
#'  Defaults to `10L`.
#'  \item nmf_init - String. `"nndsvd"` and `"svd"` both map to deterministic
#'  NNDSVD initialisation; `"random"` uses random non-negative draws. For
#'  stabilised (multi-run) NMF this field is ignored and random init is always
#'  used. One of `c("nndsvd", "svd", "random")`. Defaults to `"nndsvd"`.
#' }
#'
#' @export
params_nmf_hals <- function(
  max_iter = 250L,
  tol = 1e-04,
  eps = 1e-10,
  check_every = 10L,
  nmf_init = c("nndsvd", "svd", "random")
) {
  nmf_init <- match.arg(nmf_init)

  # Checks
  checkmate::qassert(max_iter, "I1[1,)")
  checkmate::qassert(tol, "N1(0,)")
  checkmate::qassert(eps, "N1(0,)")
  checkmate::qassert(check_every, "I1[1,)")
  checkmate::assertChoice(nmf_init, c("nndsvd", "svd", "random"))

  # Return
  list(
    max_iter = max_iter,
    tol = tol,
    eps = eps,
    check_every = check_every,
    nmf_init = nmf_init
  )
}

#' Helper function to generate normalisation defaults for doublet detection.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item log_transform - Boolean. Shall the counts be log-normalised. Defaults
#'  to `TRUE`.
#'  \item mean_center - Boolean. Shall mean centring be applied. Defaults to
#'  `FALSE`.
#'  \item normalise_variance - Boolean. Shall the variance be normalised.
#'  Defaults to `FALSE`.
#'  \item target_size - Numeric. Target library size. Defaults to `1000000.0`.
#' }
#'
#' @export
params_norm_doublets_defaults <- function() {
  list(
    log_transform = TRUE,
    mean_center = FALSE,
    normalise_variance = FALSE,
    target_size = 1000000.0
  )
}

#' Helper function to generate default parameters for PCA
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item no_pcs - Integer. Number of PCs to consider. Defaults to `30L`.
#'  \item random_svd - Boolean. Shall randomised SVD be used. Defaults to
#'  `TRUE`.
#'  \item sparse - Boolean. Shall sparse solvers be used that do not do scaling.
#'  If set to yes, in the case of `random_svd = FALSE`, Lanczos iterations are
#'  used to solve the sparse SVD. With `random_svd = TRUE`, the sparse initial
#'  matrix is multiplied with the random matrix, yielding a much smaller dense
#'  matrix that does not increase the memory pressure massively. Defaults to
#'  `FALSE`.
#' }
#'
#' @export
params_pca_defaults <- function() {
  list(
    no_pcs = 30L,
    random_svd = TRUE,
    sparse = FALSE
  )
}

#' Wrapper function for analytic Pearson residual parameters
#'
#' @description The closed-form alternative to scTransform: one shared
#' dispersion instead of a fitted model per gene. Much cheaper, and on most data
#' sets it ranks genes about as well.
#'
#' @param theta Numeric. The shared negative binomial dispersion. `Inf` gives
#' the Poisson limit. Defaults to `100.0`.
#' @param min_cells Integer. Minimum number of cells a gene must be detected in
#' to be retained. `0L` keeps everything. Defaults to `5L`.
#' @param clip_min Numeric or `NULL`. Lower residual clipping bound. `NULL` uses
#' `-sqrt(n_cells)`. Must be given together with `clip_max`. Defaults to `NULL`.
#' @param clip_max Numeric or `NULL`. Upper residual clipping bound. `NULL` uses
#' `sqrt(n_cells)`. Must be given together with `clip_min`. Defaults to `NULL`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item theta - Numeric. The shared negative binomial dispersion. `Inf` gives
#'  the Poisson limit. Defaults to `100.0`.
#'  \item min_cells - Integer. Minimum number of cells a gene must be detected
#'  in to be retained. `0L` keeps everything. Defaults to `5L`.
#'  \item clip_min - Numeric or `NULL`. Lower residual clipping bound. `NULL`
#'  uses `-sqrt(n_cells)`. Must be given together with `clip_max`. Defaults to
#'  `NULL`.
#'  \item clip_max - Numeric or `NULL`. Upper residual clipping bound. `NULL`
#'  uses `sqrt(n_cells)`. Must be given together with `clip_min`. Defaults to
#'  `NULL`.
#' }
#'
#' @references Lause, Berens and Kobak, Genome Biology, 2021.
#'
#' @export
params_sc_apr <- function(
  theta = 100.0,
  min_cells = 5L,
  clip_min = NULL,
  clip_max = NULL
) {
  # Checks
  checkmate::qassert(theta, "N1(0,]")
  checkmate::qassert(min_cells, "I1[0,)")
  checkmate::qassert(clip_min, c("N1", "0"))
  checkmate::qassert(clip_max, c("N1", "0"))

  assert_clip_range(clip_min, clip_max)

  # Return
  list(
    theta = theta,
    min_cells = min_cells,
    clip_min = clip_min,
    clip_max = clip_max
  )
}

#' Wrapper function for parameters for AUCell
#'
#' @description The three statistics consume the same within-cell ranking, but
#' weight it very differently. `"wilcox"` is a pure function of the gene set's
#' rank sum, so a gene at rank 2 and one at rank 200 count for almost the same
#' thing. `"recovery"` and `"ap"` are top-heavy. For SCENIC use `"recovery"`,
#' the default. `"wilcox"` is a bixverse addition and its flatter score does not
#' separate into on/off populations, so it binarises badly. Ranking ties are
#' averaged (midranks) rather than broken at random the way AUCell does it,
#' which is why there is no need for SCENIC's trick of setting the cutoff to the
#' 1st percentile of genes detected per cell. Undetected genes all collapse onto
#' one rank well outside any sensible `max_rank`. Note the recovery AUC is
#' normalised by `max_rank * length(gene_set)`, matching pySCENIC and AUCell's
#' `normAUC = FALSE`. Modern AUCell divides by the attainable maximum instead,
#' so absolute values differ by a per-gene-set constant. Cell ordering within a
#' regulon is unaffected.
#'
#' @param auc_type String. Which statistic to calculate. `"wilcox"` is the AUC
#' derived from the Mann-Whitney U statistic over the full ranking, with the
#' null at 0.5 for any gene set size. `"recovery"` is the recovery-curve AUC
#' under a rank cutoff, i.e. the actual AUCell statistic of Aibar, et al. `"ap"`
#' is average precision, the most top-heavy of the three, but its null tracks
#' the gene set prevalence so raw values are not comparable across gene sets of
#' different size unless `standardise` is on. One of `c("recovery", "wilcox",
#' "ap")`. Defaults to `"recovery"`.
#' @param max_rank Numeric or `NULL`. Rank cutoff for `"recovery"`, counted from
#' the top of the within-cell ranking. If `NULL`, resolves to the top 5% of the
#' gene universe, following Aibar, et al. Ignored by the other two statistics.
#' Defaults to `NULL`.
#' @param standardise Boolean. Shall each gene set's scores be z-scored across
#' the cells. This is what makes `"ap"` comparable across gene sets of different
#' size. Defaults to `FALSE`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item auc_type - String. Which statistic to calculate. `"wilcox"` is the AUC
#'  derived from the Mann-Whitney U statistic over the full ranking, with the
#'  null at 0.5 for any gene set size. `"recovery"` is the recovery-curve AUC
#'  under a rank cutoff, i.e. the actual AUCell statistic of Aibar, et al.
#'  `"ap"` is average precision, the most top-heavy of the three, but its null
#'  tracks the gene set prevalence so raw values are not comparable across gene
#'  sets of different size unless `standardise` is on. One of `c("recovery",
#'  "wilcox", "ap")`. Defaults to `"recovery"`.
#'  \item max_rank - Numeric or `NULL`. Rank cutoff for `"recovery"`, counted
#'  from the top of the within-cell ranking. If `NULL`, resolves to the top 5%
#'  of the gene universe, following Aibar, et al. Ignored by the other two
#'  statistics. Defaults to `NULL`.
#'  \item standardise - Boolean. Shall each gene set's scores be z-scored across
#'  the cells. This is what makes `"ap"` comparable across gene sets of
#'  different size. Defaults to `FALSE`.
#' }
#'
#' @references Aibar, et al., Nat Methods, 2017
#'
#' @export
params_sc_aucell <- function(
  auc_type = c("recovery", "wilcox", "ap"),
  max_rank = NULL,
  standardise = FALSE
) {
  auc_type <- match.arg(auc_type)

  # Checks
  checkmate::assertChoice(auc_type, c("recovery", "wilcox", "ap"))
  checkmate::qassert(max_rank, c("N1[1,)", "0"))
  checkmate::qassert(standardise, "B1")

  if (!is.null(max_rank)) {
    max_rank <- as.double(max_rank)
  }

  # Return
  list(
    auc_type = auc_type,
    max_rank = max_rank,
    standardise = standardise
  )
}

#' Wrapper function for the BBKNN parameters
#'
#' @param neighbours_within_batch Integer. Number of neighbours to consider per
#' batch. Defaults to `3L`.
#' @param set_op_mix_ratio Numeric. Mixing ratio between union (1.0) and
#' intersection (0.0). Defaults to `1.0`.
#' @param local_connectivity Numeric. UMAP connectivity computation parameter,
#' how many nearest neighbours of each cell are assumed to be fully connected.
#' Defaults to `1.0`.
#' @param trim Integer or `NULL`. Trim the neighbours of each cell to these many
#' top connectivities. May help with population independence and improve the
#' tidiness of clustering. If `NULL`, it defaults to `10 *
#' neighbours_within_batch`. Defaults to `NULL`.
#' @param knn List. Optional overrides for kNN parameters. See
#' [bixverse::params_knn_defaults()] for available parameters: `k`,
#' `knn_method`, `ann_dist`, `search_budget`, `n_trees`, `delta`,
#' `diversify_prob`, `ef_budget`, `extract_knn`, `m`, `ef_construction`,
#' `ef_search`, `n_list` and `n_probe`. See [params_knn_defaults()] for the
#' available elements. Defaults to `list()`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item neighbours_within_batch - Integer. Number of neighbours to consider
#'  per batch. Defaults to `3L`.
#'  \item set_op_mix_ratio - Numeric. Mixing ratio between union (1.0) and
#'  intersection (0.0). Defaults to `1.0`.
#'  \item local_connectivity - Numeric. UMAP connectivity computation parameter,
#'  how many nearest neighbours of each cell are assumed to be fully connected.
#'  Defaults to `1.0`.
#'  \item trim - Integer or `NULL`. Trim the neighbours of each cell to these
#'  many top connectivities. May help with population independence and improve
#'  the tidiness of clustering. If `NULL`, it defaults to `10 *
#'  neighbours_within_batch`. Defaults to `NULL`.
#'  \item The elements of [params_knn_defaults()], overridden by `knn`, spliced
#'  in at this position.
#' }
#'
#' @export
params_sc_bbknn <- function(
  neighbours_within_batch = 3L,
  set_op_mix_ratio = 1.0,
  local_connectivity = 1.0,
  trim = NULL,
  knn = list()
) {
  # Checks
  checkmate::qassert(neighbours_within_batch, "I1[1,)")
  checkmate::qassert(set_op_mix_ratio, "N1[0,1]")
  checkmate::qassert(local_connectivity, "N1")
  checkmate::qassert(trim, c("I1[1,)", "0"))

  # Merge
  knn <- utils::modifyList(
    params_knn_defaults(),
    utils::modifyList(
      list(
        k = neighbours_within_batch *
          2L
      ),
      knn,
      keep.null = TRUE
    ),
    keep.null = TRUE
  )

  # Return
  c(
    list(
      neighbours_within_batch = neighbours_within_batch,
      set_op_mix_ratio = set_op_mix_ratio,
      local_connectivity = local_connectivity,
      trim = trim
    ),
    knn
  )
}

#' Wrapper function for the branch cell selection parameters
#'
#' @description Parameters controlling which cells
#' [bixverse::run_gene_trends_sc()] assigns to each branch. The threshold on a
#' fate's probability is an expanding quantile over the pseudotime-sorted cells,
#' made monotone with a cumulative maximum, so a fate's bar can only rise as
#' differentiation proceeds. The defaults are the reference ones.
#'
#' @param q Numeric. Upper-tail quantile of the fate probability used as the
#' threshold. Defaults to `0.01`.
#' @param eps Numeric. Slack subtracted from the threshold before the
#' comparison. Defaults to `0.01`.
#' @param resolution Integer. Number of pseudotime buckets, capped at the cell
#' count. Defaults to `500L`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item q - Numeric. Upper-tail quantile of the fate probability used as the
#'  threshold. Defaults to `0.01`.
#'  \item eps - Numeric. Slack subtracted from the threshold before the
#'  comparison. Defaults to `0.01`.
#'  \item resolution - Integer. Number of pseudotime buckets, capped at the cell
#'  count. Defaults to `500L`.
#' }
#'
#' @references Setty, et al., Nat. Biotechnol., 2019.
#'
#' @export
params_sc_branch_selection <- function(
  q = 0.01,
  eps = 0.01,
  resolution = 500L
) {
  # Checks
  checkmate::qassert(q, "N1[0,1]")
  checkmate::qassert(eps, "N1[0,)")
  checkmate::qassert(resolution, "I1[1,)")

  # Return
  list(
    q = q,
    eps = eps,
    resolution = resolution
  )
}

#' Wrapper function for parameters for bootstrapped meta cell generation
#'
#' @description This function generates parameters for the bootstrapped meta
#' cell generation based on hdWGCNA, see Morabito, et al., Cell Rep. Methods,
#' 2023.
#'
#' @param max_shared Integer. Maximum number of allowed shared neighbours for
#' the meta cell to be considered. Defaults to `15L`.
#' @param target_no_metacells Integer. Target number of meta-cells to generate.
#' Defaults to `1000L`.
#' @param max_iter Integer. Maximum number of iterations for the algorithm.
#' Defaults to `5000L`.
#' @param knn List. Optional overrides for kNN parameters. See
#' [bixverse::params_knn_defaults()] for available parameters: `k`,
#' `knn_method`, `ann_dist`, `search_budget`, `n_trees`, `delta`,
#' `diversify_prob`, `ef_budget`, `extract_knn`, `m`, `ef_construction`,
#' `ef_search`, `n_list` and `n_probe`. See [params_knn_defaults()] for the
#' available elements. Defaults to `list()`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item max_shared - Integer. Maximum number of allowed shared neighbours for
#'  the meta cell to be considered. Defaults to `15L`.
#'  \item target_no_metacells - Integer. Target number of meta-cells to
#'  generate. Defaults to `1000L`.
#'  \item max_iter - Integer. Maximum number of iterations for the algorithm.
#'  Defaults to `5000L`.
#'  \item The elements of [params_knn_defaults()], overridden by `knn`, spliced
#'  in at this position.
#' }
#'
#' @export
params_sc_bt_metacells <- function(
  max_shared = 15L,
  target_no_metacells = 1000L,
  max_iter = 5000L,
  knn = list()
) {
  # Checks
  checkmate::qassert(max_shared, "I1[1,)")
  checkmate::qassert(target_no_metacells, "I1[1,)")
  checkmate::qassert(max_iter, "I1[1,)")

  # Merge
  knn <- utils::modifyList(
    params_knn_defaults(),
    utils::modifyList(
      list(k = 25L, ann_dist = "cosine"),
      knn,
      keep.null = TRUE
    ),
    keep.null = TRUE
  )

  # Return
  c(
    list(
      max_shared = max_shared,
      target_no_metacells = target_no_metacells,
      max_iter = max_iter
    ),
    knn
  )
}

#' Default parameters for CellSweep denoising
#'
#' @description Mirrors the CellSweep reference implementation's defaults. The
#' pseudocounts (`celltype_lambda`, `ambient_lambda`, `bulk_lambda`) are given
#' on the scale you see here and divided by the gene count internally. Two of
#' these are worth knowing about before you touch anything else.
#' `freeze_ambient_profile = TRUE` keeps the ambient profile at its
#' empty-droplet estimate, which is the recommended path and the only one where
#' `alpha_cap`, the repulsion terms and cell-type reassignment are live. And
#' `freeze_empties` only accepts `TRUE`: the reference gives empty droplets a
#' cell-type component they have no label for, which indexes past the end of the
#' profile matrix and wraps onto the last cell type.
#'
#' @param freeze_empties Boolean. Keep the contamination fraction of empty
#' droplets pinned at 1. Only `TRUE` is supported, see the description. Defaults
#' to `TRUE`.
#' @param freeze_ambient_profile Boolean. Keep the ambient profile at its
#' empty-droplet estimate rather than re-estimating it as a mixture over the
#' cell-type profiles. Defaults to `TRUE`.
#' @param init_alpha Numeric. Starting ambient fraction for every real barcode.
#' With `freeze_ambient_profile = TRUE` the final result barely depends on it,
#' so it sits at `alpha_cap`. Defaults to `0.9`.
#' @param init_beta Numeric. Starting bulk contamination fraction. Set below
#' `init_alpha` on purpose: bulk and ambient are not fully separable, so this
#' biases unassignable contamination towards ambient. Defaults to `0.1`.
#' @param alpha_cap Numeric. Ceiling on the per-cell ambient fraction before the
#' log-likelihood converges. Barcodes wanting to exceed it are excluded from the
#' cell-type profile update and allowed to switch cell type. Defaults to `0.9`.
#' @param repulsion_strength Numeric. Strength of the repulsion pushing
#' cell-type profiles away from the ambient profile. Scales with cluster mass,
#' so it is inert on small data and only bites at realistic cell counts.
#' Defaults to `1e-04`.
#' @param max_frac_gene_repulsion Numeric. Ceiling on the fraction of any single
#' profile entry that repulsion may remove. Defaults to `0.2`.
#' @param celltype_lambda Numeric. Pseudocount smoothing the cell-type profile
#' update. Higher values give smoother profiles. Defaults to `50.0`.
#' @param ambient_lambda Numeric. Pseudocount smoothing the ambient profile
#' estimate. Defaults to `50.0`.
#' @param bulk_lambda Numeric. Pseudocount smoothing the bulk profile estimate.
#' Defaults to `10.0`.
#' @param eps Numeric. Floor on denominators. Defaults to `1e-12`.
#' @param log_eps Numeric. Floor on the argument of `log`. Defaults to `1e-300`.
#' @param max_iter Integer. Hard cap on EM iterations. Defaults to `2000L`.
#' @param del0_ll_tol Numeric. Log-likelihood change, as a fraction of the first
#' EM step's change, below which stage one ends and parameter convergence starts
#' being checked. Defaults to `0.001`.
#' @param min_ll_tol Numeric. Floor on the adaptive tolerance, relative to the
#' current log-likelihood. Stops `del0_ll_tol` chasing floating point noise.
#' Defaults to `1e-06`.
#' @param tol_p Numeric. Convergence threshold on the maximum row-wise L1 change
#' in the cell-type profiles. Defaults to `1e-04`.
#' @param tol_f Numeric. Convergence threshold on the change in the total
#' contamination fraction. Defaults to `1e-04`.
#' @param norm_from_rounded Boolean. Derive the normalised layer from the
#' integerised counts rather than the denoised floats. Consistent across the two
#' layers at the cost of the sub-integer signal, which is where CellSweep is
#' most informative. Defaults to `FALSE`.
#' @param seed Integer. Seed for the stochastic rounding of the denoised counts.
#' Defaults to `42L`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item freeze_empties - Boolean. Keep the contamination fraction of empty
#'  droplets pinned at 1. Only `TRUE` is supported, see the description.
#'  Defaults to `TRUE`.
#'  \item freeze_ambient_profile - Boolean. Keep the ambient profile at its
#'  empty-droplet estimate rather than re-estimating it as a mixture over the
#'  cell-type profiles. Defaults to `TRUE`.
#'  \item init_alpha - Numeric. Starting ambient fraction for every real
#'  barcode. With `freeze_ambient_profile = TRUE` the final result barely
#'  depends on it, so it sits at `alpha_cap`. Defaults to `0.9`.
#'  \item init_beta - Numeric. Starting bulk contamination fraction. Set below
#'  `init_alpha` on purpose: bulk and ambient are not fully separable, so this
#'  biases unassignable contamination towards ambient. Defaults to `0.1`.
#'  \item alpha_cap - Numeric. Ceiling on the per-cell ambient fraction before
#'  the log-likelihood converges. Barcodes wanting to exceed it are excluded
#'  from the cell-type profile update and allowed to switch cell type. Defaults
#'  to `0.9`.
#'  \item repulsion_strength - Numeric. Strength of the repulsion pushing
#'  cell-type profiles away from the ambient profile. Scales with cluster mass,
#'  so it is inert on small data and only bites at realistic cell counts.
#'  Defaults to `1e-04`.
#'  \item max_frac_gene_repulsion - Numeric. Ceiling on the fraction of any
#'  single profile entry that repulsion may remove. Defaults to `0.2`.
#'  \item celltype_lambda - Numeric. Pseudocount smoothing the cell-type profile
#'  update. Higher values give smoother profiles. Defaults to `50.0`.
#'  \item ambient_lambda - Numeric. Pseudocount smoothing the ambient profile
#'  estimate. Defaults to `50.0`.
#'  \item bulk_lambda - Numeric. Pseudocount smoothing the bulk profile
#'  estimate. Defaults to `10.0`.
#'  \item eps - Numeric. Floor on denominators. Defaults to `1e-12`.
#'  \item log_eps - Numeric. Floor on the argument of `log`. Defaults to
#'  `1e-300`.
#'  \item max_iter - Integer. Hard cap on EM iterations. Defaults to `2000L`.
#'  \item del0_ll_tol - Numeric. Log-likelihood change, as a fraction of the
#'  first EM step's change, below which stage one ends and parameter convergence
#'  starts being checked. Defaults to `0.001`.
#'  \item min_ll_tol - Numeric. Floor on the adaptive tolerance, relative to the
#'  current log-likelihood. Stops `del0_ll_tol` chasing floating point noise.
#'  Defaults to `1e-06`.
#'  \item tol_p - Numeric. Convergence threshold on the maximum row-wise L1
#'  change in the cell-type profiles. Defaults to `1e-04`.
#'  \item tol_f - Numeric. Convergence threshold on the change in the total
#'  contamination fraction. Defaults to `1e-04`.
#'  \item norm_from_rounded - Boolean. Derive the normalised layer from the
#'  integerised counts rather than the denoised floats. Consistent across the
#'  two layers at the cost of the sub-integer signal, which is where CellSweep
#'  is most informative. Defaults to `FALSE`.
#'  \item seed - Integer. Seed for the stochastic rounding of the denoised
#'  counts. Defaults to `42L`.
#' }
#'
#' @export
params_sc_cellsweep <- function(
  freeze_empties = TRUE,
  freeze_ambient_profile = TRUE,
  init_alpha = 0.9,
  init_beta = 0.1,
  alpha_cap = 0.9,
  repulsion_strength = 1e-04,
  max_frac_gene_repulsion = 0.2,
  celltype_lambda = 50.0,
  ambient_lambda = 50.0,
  bulk_lambda = 10.0,
  eps = 1e-12,
  log_eps = 1e-300,
  max_iter = 2000L,
  del0_ll_tol = 0.001,
  min_ll_tol = 1e-06,
  tol_p = 1e-04,
  tol_f = 1e-04,
  norm_from_rounded = FALSE,
  seed = 42L
) {
  # Checks
  checkmate::qassert(freeze_empties, "B1")
  checkmate::qassert(freeze_ambient_profile, "B1")
  checkmate::qassert(init_alpha, "N1[0.1,0.9]")
  checkmate::qassert(init_beta, "N1[0.1,0.9]")
  checkmate::qassert(alpha_cap, "N1[0,1]")
  checkmate::qassert(repulsion_strength, "N1[0,1e-3]")
  checkmate::qassert(max_frac_gene_repulsion, "N1(0,1]")
  checkmate::qassert(celltype_lambda, "N1[0,)")
  checkmate::qassert(ambient_lambda, "N1[0,)")
  checkmate::qassert(bulk_lambda, "N1[0,)")
  checkmate::qassert(eps, "N1(0,)")
  checkmate::qassert(log_eps, "N1(0,)")
  checkmate::qassert(max_iter, "I1[2,)")
  checkmate::qassert(del0_ll_tol, "N1(0,)")
  checkmate::qassert(min_ll_tol, "N1(0,)")
  checkmate::qassert(tol_p, "N1(0,)")
  checkmate::qassert(tol_f, "N1(0,)")
  checkmate::qassert(norm_from_rounded, "B1")
  checkmate::qassert(seed, "I1[0,)")

  if (!isTRUE(freeze_empties)) {
    stop(paste(
      "`freeze_empties = FALSE` is not supported. The reference gives",
      "empty droplets a cell-type component they have no label for,",
      "which indexes past the end of the profile matrix."
    ))
  }

  # Return
  res <- list(
    freeze_empties = freeze_empties,
    freeze_ambient_profile = freeze_ambient_profile,
    init_alpha = init_alpha,
    init_beta = init_beta,
    alpha_cap = alpha_cap,
    repulsion_strength = repulsion_strength,
    max_frac_gene_repulsion = max_frac_gene_repulsion,
    celltype_lambda = celltype_lambda,
    ambient_lambda = ambient_lambda,
    bulk_lambda = bulk_lambda,
    eps = eps,
    log_eps = log_eps,
    max_iter = max_iter,
    del0_ll_tol = del0_ll_tol,
    min_ll_tol = min_ll_tol,
    tol_p = tol_p,
    tol_f = tol_f,
    norm_from_rounded = norm_from_rounded,
    seed = seed
  )
  class(res) <- c("params_sc_cellsweep", "list")
  res
}

#' Default parameters for DSB ADT normalisation
#'
#' @param denoise_counts Boolean. Run Step II (cell-to-cell technical noise
#' removal). Defaults to `TRUE`.
#' @param use_isotype_controls Boolean. Include isotype controls in the noise
#' matrix in Step II. Requires `isotype_indices` to be passed at call time.
#' Defaults to `TRUE`.
#' @param pseudocount Numeric. Pseudocount added before the log transform. The
#' DSB paper recommends `10` with empty droplets and `1` without. Defaults to
#' `10.0`.
#' @param quantile_low Numeric or `NULL`. Optional numeric in `[0, 1)`. Lower
#' quantile for per-protein output clipping. If `NULL` (and `quantile_high` is
#' also `NULL`), no clipping is applied. Defaults to `NULL`.
#' @param quantile_high Numeric or `NULL`. Optional numeric in `(0, 1]`. Upper
#' quantile for per-protein output clipping. If `NULL` (and `quantile_low` is
#' also `NULL`), no clipping is applied. Defaults to `NULL`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item denoise_counts - Boolean. Run Step II (cell-to-cell technical noise
#'  removal). Defaults to `TRUE`.
#'  \item use_isotype_controls - Boolean. Include isotype controls in the noise
#'  matrix in Step II. Requires `isotype_indices` to be passed at call time.
#'  Defaults to `TRUE`.
#'  \item pseudocount - Numeric. Pseudocount added before the log transform. The
#'  DSB paper recommends `10` with empty droplets and `1` without. Defaults to
#'  `10.0`.
#'  \item quantile_low - Numeric or `NULL`. Optional numeric in `[0, 1)`. Lower
#'  quantile for per-protein output clipping. If `NULL` (and `quantile_high` is
#'  also `NULL`), no clipping is applied. Defaults to `NULL`.
#'  \item quantile_high - Numeric or `NULL`. Optional numeric in `(0, 1]`. Upper
#'  quantile for per-protein output clipping. If `NULL` (and `quantile_low` is
#'  also `NULL`), no clipping is applied. Defaults to `NULL`.
#' }
#'
#' @export
params_sc_dsb <- function(
  denoise_counts = TRUE,
  use_isotype_controls = TRUE,
  pseudocount = 10.0,
  quantile_low = NULL,
  quantile_high = NULL
) {
  # Checks
  checkmate::qassert(denoise_counts, "B1")
  checkmate::qassert(use_isotype_controls, "B1")
  checkmate::qassert(pseudocount, "N1(0,)")
  checkmate::qassert(quantile_low, c("N1[0,1)", "0"))
  checkmate::qassert(quantile_high, c("N1(0,1]", "0"))

  if (xor(is.null(quantile_low), is.null(quantile_high))) {
    stop("quantile_low and quantile_high must both be provided or both NULL.")
  }
  if (
    !is.null(quantile_low) &&
      !is.null(quantile_high) &&
      quantile_low >= quantile_high
  ) {
    stop("quantile_low must be strictly less than quantile_high.")
  }

  # Return
  list(
    denoise_counts = denoise_counts,
    use_isotype_controls = use_isotype_controls,
    pseudocount = pseudocount,
    quantile_low = quantile_low,
    quantile_high = quantile_high
  )
}

#' Parameters for identifying empty droplets
#'
#' @description CellSweep trains its ambient profile on the empty droplets, so
#' it needs them called before it runs. Four ways to do that, in descending
#' order of how much you should trust them. `"supplied"` takes an existing
#' logical column from the obs table. This is the common case: if you have
#' CellRanger's filtered barcode list you already know which barcodes are empty,
#' and nothing here will beat that. `"umi_cutoff"` calls everything below an
#' absolute library size empty. `"expected_cells"` turns a cell count into that
#' cutoff via the sorted library sizes. `"knee"` finds the cutoff from the
#' curvature of the rank / log-count curve; it is experimental in the reference
#' too, and smoothing puts the curvature minimum a few ranks ahead of the actual
#' cliff, so it sweeps up the real barcodes nearest the transition.
#'
#' @param method String. How the empty droplets are called, see the description.
#' One of `c("supplied", "umi_cutoff", "expected_cells", "knee")`. Defaults to
#' `"supplied"`.
#' @param is_empty_column String or `NULL`. Name of the logical obs column
#' holding the mask. Required for `method = "supplied"`, ignored otherwise.
#' Defaults to `NULL`.
#' @param umi_cutoff Integer or `NULL`. Barcodes with a library size strictly
#' below this are empty. Required for `method = "umi_cutoff"`, ignored
#' otherwise. Defaults to `NULL`.
#' @param expected_cells Integer or `NULL`. Number of real cells expected in the
#' run. Required for `method = "expected_cells"`, ignored otherwise. Defaults to
#' `NULL`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item method - String. How the empty droplets are called, see the
#'  description. One of `c("supplied", "umi_cutoff", "expected_cells", "knee")`.
#'  Defaults to `"supplied"`.
#'  \item is_empty_column - String or `NULL`. Name of the logical obs column
#'  holding the mask. Required for `method = "supplied"`, ignored otherwise.
#'  Defaults to `NULL`.
#'  \item umi_cutoff - Integer or `NULL`. Barcodes with a library size strictly
#'  below this are empty. Required for `method = "umi_cutoff"`, ignored
#'  otherwise. Defaults to `NULL`.
#'  \item expected_cells - Integer or `NULL`. Number of real cells expected in
#'  the run. Required for `method = "expected_cells"`, ignored otherwise.
#'  Defaults to `NULL`.
#' }
#'
#' @export
params_sc_empty_droplets <- function(
  method = c("supplied", "umi_cutoff", "expected_cells", "knee"),
  is_empty_column = NULL,
  umi_cutoff = NULL,
  expected_cells = NULL
) {
  method <- match.arg(method)

  # Checks
  checkmate::assertChoice(
    method,
    c("supplied", "umi_cutoff", "expected_cells", "knee")
  )
  checkmate::qassert(is_empty_column, c("S1", "0"))
  checkmate::qassert(umi_cutoff, c("I1[1,)", "0"))
  checkmate::qassert(expected_cells, c("I1[1,)", "0"))

  required <- switch(
    method,
    supplied = "is_empty_column",
    umi_cutoff = "umi_cutoff",
    expected_cells = "expected_cells",
    knee = NULL
  )
  if (!is.null(required) && is.null(get(required))) {
    stop(sprintf("`method = '%s'` needs `%s`.", method, required))
  }

  # Return
  res <- list(
    method = method,
    is_empty_column = is_empty_column,
    umi_cutoff = umi_cutoff,
    expected_cells = expected_cells
  )
  class(res) <- c("params_sc_empty_droplets", "list")
  res
}

#' Fast single cell clustering parameters
#'
#' @param kmeans_iters Integer. Number of iterations for k-means clustering.
#' Defaults to `100L`.
#' @param batch_size Integer. Batch size for mini batch k-means clustering.
#' Defaults to `4096L`.
#' @param drift_threshold Numeric. The drift for the mini batch k-means
#' clustering. If the centroid drift is below this, the mini batch k-means
#' terminates. Defaults to `1e-04`.
#' @param lr_alpha Numeric. Learning rate alpha parameter for mini batch
#' k-means. Defaults to `1.0`.
#' @param full_snn Boolean. Shall the full shared nearest neighbour graph be
#' generated that generates edges between all cells instead of between only
#' neighbours. Defaults to `FALSE`.
#' @param pruning Numeric or `NULL`. Weights below this threshold will be set to
#' 0 in the generation of the sNN graph. If not provided, defaults to `1 /
#' ceil(k * 0.8)`. Defaults to `NULL`.
#' @param snn_similarity String. The Jaccard similarity calculates the Jaccard
#' between the neighbours, whereas the rank method calculates edge weights based
#' on the ranking of shared neighbours. For the rank method, the weight is
#' determined by finding the shared neighbour with the lowest combined rank
#' across both cells, where lower-ranked (closer) shared neighbours result in
#' higher edge weights Both methods produce weights normalised to the range `[0,
#' 1]`. One of `c("jaccard", "rank")`. Defaults to `"jaccard"`.
#' @param louvain_iters Integer. Number of iterations for Louvain clustering.
#' Defaults to `10L`.
#' @param knn List. Optional overrides for kNN parameters. See
#' [bixverse::params_knn_defaults()] for available parameters: `k`,
#' `knn_method`, `ann_dist`, `search_budget`, `n_trees`, `delta`,
#' `diversify_prob`, `ef_budget`, `extract_knn`, `m`, `ef_construction`,
#' `ef_search`, `n_list` and `n_probe`. Sets the default `k = 5L`. See
#' [params_knn_defaults()] for the available elements. Defaults to `list(k =
#' 5L)`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item kmeans_iters - Integer. Number of iterations for k-means clustering.
#'  Defaults to `100L`.
#'  \item batch_size - Integer. Batch size for mini batch k-means clustering.
#'  Defaults to `4096L`.
#'  \item drift_threshold - Numeric. The drift for the mini batch k-means
#'  clustering. If the centroid drift is below this, the mini batch k-means
#'  terminates. Defaults to `1e-04`.
#'  \item lr_alpha - Numeric. Learning rate alpha parameter for mini batch
#'  k-means. Defaults to `1.0`.
#'  \item louvain_iters - Integer. Number of iterations for Louvain clustering.
#'  Defaults to `10L`.
#'  \item full_snn - Boolean. Shall the full shared nearest neighbour graph be
#'  generated that generates edges between all cells instead of between only
#'  neighbours. Defaults to `FALSE`.
#'  \item pruning - Numeric or `NULL`. Weights below this threshold will be set
#'  to 0 in the generation of the sNN graph. If not provided, defaults to `1 /
#'  ceil(k * 0.8)`. Defaults to `NULL`.
#'  \item snn_similarity - String. The Jaccard similarity calculates the Jaccard
#'  between the neighbours, whereas the rank method calculates edge weights
#'  based on the ranking of shared neighbours. For the rank method, the weight
#'  is determined by finding the shared neighbour with the lowest combined rank
#'  across both cells, where lower-ranked (closer) shared neighbours result in
#'  higher edge weights Both methods produce weights normalised to the range
#'  `[0, 1]`. One of `c("jaccard", "rank")`. Defaults to `"jaccard"`.
#'  \item The elements of [params_knn_defaults()], overridden by `knn`, spliced
#'  in at this position.
#' }
#'
#' @export
params_sc_fast_cluster <- function(
  kmeans_iters = 100L,
  batch_size = 4096L,
  drift_threshold = 1e-04,
  lr_alpha = 1.0,
  full_snn = FALSE,
  pruning = NULL,
  snn_similarity = c("jaccard", "rank"),
  louvain_iters = 10L,
  knn = list(k = 5L)
) {
  snn_similarity <- match.arg(snn_similarity)

  # Checks
  checkmate::qassert(kmeans_iters, "I1[1,)")
  checkmate::qassert(batch_size, "I1[1,)")
  checkmate::qassert(drift_threshold, "N1")
  checkmate::qassert(lr_alpha, "N1")
  checkmate::qassert(full_snn, "B1")
  checkmate::qassert(pruning, c("N1", "0"))
  checkmate::assertChoice(snn_similarity, c("jaccard", "rank"))
  checkmate::qassert(louvain_iters, "I1[1,)")

  # Merge
  knn <- utils::modifyList(params_knn_defaults(), knn, keep.null = TRUE)

  # Return
  c(
    list(
      kmeans_iters = kmeans_iters,
      batch_size = batch_size,
      drift_threshold = drift_threshold,
      lr_alpha = lr_alpha,
      louvain_iters = louvain_iters,
      full_snn = full_snn,
      pruning = pruning,
      snn_similarity = snn_similarity
    ),
    knn
  )
}

#' Wrapper function for the fastMNN parameters
#'
#' @param ndist Numeric. Number of median distances for the tricube kernel
#' bandwidth. Defaults to `3.0`.
#' @param cos_norm Boolean. Apply cosine normalisation before computing
#' distances. Defaults to `TRUE`.
#' @param no_pcs Integer. Number of PCs to use for MNN calculations. Defaults to
#' `30L`.
#' @param sparse_svd Boolean. Shall the sparse SVD be used. Defaults to `TRUE`.
#' @param knn List. Optional overrides for kNN parameters. See
#' [bixverse::params_knn_defaults()] for available parameters: `k`,
#' `knn_method`, `ann_dist`, `search_budget`, `n_trees`, `delta`,
#' `diversify_prob`, `ef_budget`, `extract_knn`, `m`, `ef_construction`,
#' `ef_search`, `n_list` and `n_probe`. See [params_knn_defaults()] for the
#' available elements. Defaults to `list(k = 20L)`.
#' @param pca List. Parameters to feed through to the optional recalculation of
#' the PCA, see [params_sc_pca()]. See [params_sc_pca()] for the available
#' elements. Defaults to `params_sc_pca()`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item ndist - Numeric. Number of median distances for the tricube kernel
#'  bandwidth. Defaults to `3.0`.
#'  \item cos_norm - Boolean. Apply cosine normalisation before computing
#'  distances. Defaults to `TRUE`.
#'  \item no_pcs - Integer. Number of PCs to use for MNN calculations. Defaults
#'  to `30L`.
#'  \item sparse_svd - Boolean. Shall the sparse SVD be used. Defaults to
#'  `TRUE`.
#'  \item The elements of [params_knn_defaults()], overridden by `knn`, spliced
#'  in at this position.
#'  \item The elements of [params_sc_pca()], overridden by `pca`, spliced in at
#'  this position.
#' }
#'
#' @export
params_sc_fastmnn <- function(
  ndist = 3.0,
  cos_norm = TRUE,
  no_pcs = 30L,
  sparse_svd = TRUE,
  knn = list(k = 20L),
  pca = params_sc_pca()
) {
  # Checks
  checkmate::qassert(ndist, "N1(0,)")
  checkmate::qassert(cos_norm, "B1")
  checkmate::qassert(no_pcs, "I1[1,)")
  checkmate::qassert(sparse_svd, "B1")

  # Merge
  knn <- utils::modifyList(
    params_knn_defaults(),
    utils::modifyList(
      list(k = 20L, ann_dist = "cosine"),
      knn,
      keep.null = TRUE
    ),
    keep.null = TRUE
  )
  pca <- utils::modifyList(params_sc_pca(), pca, keep.null = TRUE)

  # Return
  c(
    list(
      ndist = ndist,
      cos_norm = cos_norm,
      no_pcs = no_pcs,
      sparse_svd = sparse_svd
    ),
    knn,
    pca
  )
}

#' Wrapper function for gene trend parameters
#'
#' @description Parameters controlling the landmark Gaussian process that
#' [bixverse::run_gene_trends_sc()] fits per branch. The kernel is a Matern-5/2
#' one and the prediction grid doubles as the landmark set. The defaults come
#' from the reference and are prior-dominated. Palantir's pseudotime is min-max
#' scaled to `[0, 1]`, so a `length_scale` of `1.0` spans the entire domain and
#' a `sigma` of `1.0` sits at roughly the signal scale of log-normalised
#' expression. The posterior will flatten genuine transient structure and
#' resolve almost any gene into a smooth monotone or single-peaked curve. That
#' is a presentation choice, not inference. Shorten `length_scale` before
#' believing a bump.
#'
#' @param resolution Integer. Grid points per branch. Kept at the default even
#' when a branch holds fewer cells, as the reference does. Defaults to `500L`.
#' @param weighting String. With `"hard_mask"` every selected cell enters its
#' branch's fit with equal weight, which is what the reference does. With
#' `"fate_probability"` every cell enters every fit weighted by its fate
#' probability, which is more defensible: a cell at 0.6 is not a member. One of
#' `c("hard_mask", "fate_probability")`. Defaults to `"hard_mask"`.
#' @param length_scale Numeric. Matern-5/2 length scale. Defaults to `1.0`.
#' @param sigma Numeric. Noise standard deviation. Defaults to `1.0`.
#' @param jitter Numeric. Added to the landmark covariance diagonal before the
#' Cholesky. Defaults to `1e-06`.
#' @param max_jitter_retries Integer. Times the jitter is raised and the
#' Cholesky retried before giving up. Defaults to `3L`.
#' @param chunk_size Integer. Training points held at once when accumulating the
#' cross-covariance. Defaults to `2048L`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item resolution - Integer. Grid points per branch. Kept at the default even
#'  when a branch holds fewer cells, as the reference does. Defaults to `500L`.
#'  \item weighting - String. With `"hard_mask"` every selected cell enters its
#'  branch's fit with equal weight, which is what the reference does. With
#'  `"fate_probability"` every cell enters every fit weighted by its fate
#'  probability, which is more defensible: a cell at 0.6 is not a member. One of
#'  `c("hard_mask", "fate_probability")`. Defaults to `"hard_mask"`.
#'  \item length_scale - Numeric. Matern-5/2 length scale. Defaults to `1.0`.
#'  \item sigma - Numeric. Noise standard deviation. Defaults to `1.0`.
#'  \item jitter - Numeric. Added to the landmark covariance diagonal before the
#'  Cholesky. Defaults to `1e-06`.
#'  \item max_jitter_retries - Integer. Times the jitter is raised and the
#'  Cholesky retried before giving up. Defaults to `3L`.
#'  \item chunk_size - Integer. Training points held at once when accumulating
#'  the cross-covariance. Defaults to `2048L`.
#' }
#'
#' @references Setty, et al., Nat. Biotechnol., 2019.
#'
#' @export
params_sc_gene_trends <- function(
  resolution = 500L,
  weighting = c("hard_mask", "fate_probability"),
  length_scale = 1.0,
  sigma = 1.0,
  jitter = 1e-06,
  max_jitter_retries = 3L,
  chunk_size = 2048L
) {
  weighting <- match.arg(weighting)

  # Checks
  checkmate::qassert(resolution, "I1[2,)")
  checkmate::assertChoice(weighting, c("hard_mask", "fate_probability"))
  checkmate::qassert(length_scale, "N1(0,)")
  checkmate::qassert(sigma, "N1(0,)")
  checkmate::qassert(jitter, "N1[0,)")
  checkmate::qassert(max_jitter_retries, "I1[0,)")
  checkmate::qassert(chunk_size, "I1[1,)")

  # Return
  list(
    resolution = resolution,
    weighting = weighting,
    length_scale = length_scale,
    sigma = sigma,
    jitter = jitter,
    max_jitter_retries = max_jitter_retries,
    chunk_size = chunk_size
  )
}

#' Default parameters for Harmony batch correction
#'
#' @param k Integer or `NULL`. Number of clusters for k-means clustering. If not
#' provided, it will be automatically determined as `min(round(N / 30), 100)`.
#' Defaults to `NULL`.
#' @param sigma Numeric vector. Per-cluster diversity weights. Either a single
#' value (broadcast to all clusters) or a vector of length k. Defaults to `0.1`.
#' @param theta Numeric vector. Per-variable diversity penalties. Either a
#' single value (broadcast to all variables) or a vector of length equal to the
#' number of batch variables. Defaults to `2.0`.
#' @param lambda Numeric vector. Ridge regression penalty for the linear model.
#' Typically a single value that is broadcast to all design matrix columns.
#' Defaults to `1.0`.
#' @param block_size Numeric. Fraction of cells to update per block during
#' optimisation (0.0-1.0). Lower values reduce memory usage but increase
#' computation time. Defaults to `0.2`.
#' @param max_iter_kmeans Integer. Maximum number of k-means iterations per
#' Harmony round. Defaults to `20L`.
#' @param max_iter_harmony Integer. Maximum number of Harmony outer iterations.
#' Defaults to `10L`.
#' @param epsilon_kmeans Numeric. Convergence threshold for k-means clustering.
#' Stops when the relative change in cluster assignments falls below this value.
#' Defaults to `1e-05`.
#' @param epsilon_harmony Numeric. Convergence threshold for Harmony. Stops when
#' the relative change in the objective function falls below this value.
#' Defaults to `1e-04`.
#' @param window_size Integer. Number of previous iterations to consider when
#' checking convergence. Defaults to `2L`.
#' @param kmeans List. Optional overrides for the k-means clustering algorithm
#' Possible parameters are `"k_means_iter"`, `"k_means_init"`, `"gemm"` and
#' `"hamerly"`, see [params_kmeans_defaults()]. See [params_kmeans_defaults()]
#' for the available elements. Defaults to `list()`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item k - Integer or `NULL`. Number of clusters for k-means clustering. If
#'  not provided, it will be automatically determined as `min(round(N / 30),
#'  100)`. Defaults to `NULL`.
#'  \item sigma - Numeric vector. Per-cluster diversity weights. Either a single
#'  value (broadcast to all clusters) or a vector of length k. Defaults to
#'  `0.1`.
#'  \item theta - Numeric vector. Per-variable diversity penalties. Either a
#'  single value (broadcast to all variables) or a vector of length equal to the
#'  number of batch variables. Defaults to `2.0`.
#'  \item lambda - Numeric vector. Ridge regression penalty for the linear
#'  model. Typically a single value that is broadcast to all design matrix
#'  columns. Defaults to `1.0`.
#'  \item block_size - Numeric. Fraction of cells to update per block during
#'  optimisation (0.0-1.0). Lower values reduce memory usage but increase
#'  computation time. Defaults to `0.2`.
#'  \item max_iter_kmeans - Integer. Maximum number of k-means iterations per
#'  Harmony round. Defaults to `20L`.
#'  \item max_iter_harmony - Integer. Maximum number of Harmony outer
#'  iterations. Defaults to `10L`.
#'  \item epsilon_kmeans - Numeric. Convergence threshold for k-means
#'  clustering. Stops when the relative change in cluster assignments falls
#'  below this value. Defaults to `1e-05`.
#'  \item epsilon_harmony - Numeric. Convergence threshold for Harmony. Stops
#'  when the relative change in the objective function falls below this value.
#'  Defaults to `1e-04`.
#'  \item window_size - Integer. Number of previous iterations to consider when
#'  checking convergence. Defaults to `2L`.
#'  \item The elements of [params_kmeans_defaults()], overridden by `kmeans`,
#'  spliced in at this position.
#' }
#'
#' @export
params_sc_harmony <- function(
  k = NULL,
  sigma = 0.1,
  theta = 2.0,
  lambda = 1.0,
  block_size = 0.2,
  max_iter_kmeans = 20L,
  max_iter_harmony = 10L,
  epsilon_kmeans = 1e-05,
  epsilon_harmony = 1e-04,
  window_size = 2L,
  kmeans = list()
) {
  # Checks
  checkmate::qassert(k, c("I1[1,)", "0"))
  checkmate::qassert(sigma, "N+[0,)")
  checkmate::qassert(theta, "N+[0,)")
  checkmate::qassert(lambda, "N+[0,)")
  checkmate::qassert(block_size, "N1(0,1]")
  checkmate::qassert(max_iter_kmeans, "I1[1,)")
  checkmate::qassert(max_iter_harmony, "I1[1,)")
  checkmate::qassert(epsilon_kmeans, "N1(0,)")
  checkmate::qassert(epsilon_harmony, "N1(0,)")
  checkmate::qassert(window_size, "I1[1,)")

  # Merge
  kmeans <- utils::modifyList(
    params_kmeans_defaults(),
    kmeans,
    keep.null = TRUE
  )

  # Return
  res <- c(
    list(
      k = k,
      sigma = sigma,
      theta = theta,
      lambda = lambda,
      block_size = block_size,
      max_iter_kmeans = max_iter_kmeans,
      max_iter_harmony = max_iter_harmony,
      epsilon_kmeans = epsilon_kmeans,
      epsilon_harmony = epsilon_harmony,
      window_size = window_size
    ),
    kmeans
  )
  class(res) <- c("params_sc_harmony", "list")
  res
}

#' Default parameters for Harmony v2 batch correction
#'
#' @param k Integer or `NULL`. Number of clusters for k-means clustering. If not
#' provided, it will be automatically determined as `min(round(N / 30), 100)`.
#' Defaults to `NULL`.
#' @param sigma Numeric vector. Per-cluster diversity weights. Either a single
#' value (broadcast to all clusters) or a vector of length k. Defaults to `0.1`.
#' @param theta Numeric vector. Per-variable diversity penalties. Either a
#' single value (broadcast to all variables) or a vector of length equal to the
#' number of batch variables. Defaults to `2.0`.
#' @param lambda Numeric vector. Ridge regression penalty for the linear model.
#' Typically a single value that is broadcast to all design matrix columns.
#' Ignored when `use_dynamic_lambda = TRUE`. Defaults to `1.0`.
#' @param block_size Numeric. Fraction of cells to update per block during
#' optimisation (0.0-1.0). Lower values reduce memory usage but increase
#' computation time. Defaults to `0.2`.
#' @param max_iter_kmeans Integer. Maximum number of k-means iterations per
#' Harmony round. Defaults to `4L`.
#' @param max_iter_harmony Integer. Maximum number of Harmony outer iterations.
#' Defaults to `10L`.
#' @param epsilon_kmeans Numeric. Convergence threshold for k-means clustering.
#' Stops when the relative change in cluster assignments falls below this value.
#' Defaults to `0.001`.
#' @param epsilon_harmony Numeric. Convergence threshold for Harmony. Stops when
#' the relative change in the objective function falls below this value.
#' Defaults to `0.01`.
#' @param window_size Integer. Number of previous iterations to consider when
#' checking convergence. Defaults to `3L`.
#' @param alpha Numeric. Scaling factor for dynamic lambda estimation. Must be
#' in (0, 1). Only relevant when `use_dynamic_lambda = TRUE`. Defaults to `0.2`.
#' @param tau Numeric. Scaling factor for theta based on batch size. A value of
#' 0 disables batch-size scaling of theta. Defaults to `0.0`.
#' @param batch_proportion_cutoff Numeric. Cutoff for pruning batches with small
#' proportions during ridge regression. Defaults to `1e-05`.
#' @param use_dynamic_lambda Boolean. If `TRUE`, lambda is estimated dynamically
#' per cluster instead of using the fixed `lambda` value. Defaults to `FALSE`.
#' @param kmeans List. Optional overrides for the k-means clustering algorithm
#' Possible parameters are `"k_means_iter"`, `"k_means_init"`, `"gemm"` and
#' `"hamerly"`, see [params_kmeans_defaults()]. See [params_kmeans_defaults()]
#' for the available elements. Defaults to `list()`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item k - Integer or `NULL`. Number of clusters for k-means clustering. If
#'  not provided, it will be automatically determined as `min(round(N / 30),
#'  100)`. Defaults to `NULL`.
#'  \item sigma - Numeric vector. Per-cluster diversity weights. Either a single
#'  value (broadcast to all clusters) or a vector of length k. Defaults to
#'  `0.1`.
#'  \item theta - Numeric vector. Per-variable diversity penalties. Either a
#'  single value (broadcast to all variables) or a vector of length equal to the
#'  number of batch variables. Defaults to `2.0`.
#'  \item lambda - Numeric vector. Ridge regression penalty for the linear
#'  model. Typically a single value that is broadcast to all design matrix
#'  columns. Ignored when `use_dynamic_lambda = TRUE`. Defaults to `1.0`.
#'  \item block_size - Numeric. Fraction of cells to update per block during
#'  optimisation (0.0-1.0). Lower values reduce memory usage but increase
#'  computation time. Defaults to `0.2`.
#'  \item max_iter_kmeans - Integer. Maximum number of k-means iterations per
#'  Harmony round. Defaults to `4L`.
#'  \item max_iter_harmony - Integer. Maximum number of Harmony outer
#'  iterations. Defaults to `10L`.
#'  \item epsilon_kmeans - Numeric. Convergence threshold for k-means
#'  clustering. Stops when the relative change in cluster assignments falls
#'  below this value. Defaults to `0.001`.
#'  \item epsilon_harmony - Numeric. Convergence threshold for Harmony. Stops
#'  when the relative change in the objective function falls below this value.
#'  Defaults to `0.01`.
#'  \item window_size - Integer. Number of previous iterations to consider when
#'  checking convergence. Defaults to `3L`.
#'  \item alpha - Numeric. Scaling factor for dynamic lambda estimation. Must be
#'  in (0, 1). Only relevant when `use_dynamic_lambda = TRUE`. Defaults to
#'  `0.2`.
#'  \item tau - Numeric. Scaling factor for theta based on batch size. A value
#'  of 0 disables batch-size scaling of theta. Defaults to `0.0`.
#'  \item batch_proportion_cutoff - Numeric. Cutoff for pruning batches with
#'  small proportions during ridge regression. Defaults to `1e-05`.
#'  \item use_dynamic_lambda - Boolean. If `TRUE`, lambda is estimated
#'  dynamically per cluster instead of using the fixed `lambda` value. Defaults
#'  to `FALSE`.
#'  \item The elements of [params_kmeans_defaults()], overridden by `kmeans`,
#'  spliced in at this position.
#' }
#'
#' @export
params_sc_harmony_v2 <- function(
  k = NULL,
  sigma = 0.1,
  theta = 2.0,
  lambda = 1.0,
  block_size = 0.2,
  max_iter_kmeans = 4L,
  max_iter_harmony = 10L,
  epsilon_kmeans = 0.001,
  epsilon_harmony = 0.01,
  window_size = 3L,
  alpha = 0.2,
  tau = 0.0,
  batch_proportion_cutoff = 1e-05,
  use_dynamic_lambda = FALSE,
  kmeans = list()
) {
  # Checks
  checkmate::qassert(k, c("I1[1,)", "0"))
  checkmate::qassert(sigma, "N+[0,)")
  checkmate::qassert(theta, "N+[0,)")
  checkmate::qassert(lambda, "N+[0,)")
  checkmate::qassert(block_size, "N1(0,1]")
  checkmate::qassert(max_iter_kmeans, "I1[1,)")
  checkmate::qassert(max_iter_harmony, "I1[1,)")
  checkmate::qassert(epsilon_kmeans, "N1(0,)")
  checkmate::qassert(epsilon_harmony, "N1(0,)")
  checkmate::qassert(window_size, "I1[1,)")
  checkmate::qassert(alpha, "N1(0,1)")
  checkmate::qassert(tau, "N1[0,)")
  checkmate::qassert(batch_proportion_cutoff, "N1(0,)")
  checkmate::qassert(use_dynamic_lambda, "B1")

  # Merge
  kmeans <- utils::modifyList(
    params_kmeans_defaults(),
    kmeans,
    keep.null = TRUE
  )

  # Return
  res <- c(
    list(
      k = k,
      sigma = sigma,
      theta = theta,
      lambda = lambda,
      block_size = block_size,
      max_iter_kmeans = max_iter_kmeans,
      max_iter_harmony = max_iter_harmony,
      epsilon_kmeans = epsilon_kmeans,
      epsilon_harmony = epsilon_harmony,
      window_size = window_size,
      alpha = alpha,
      tau = tau,
      batch_proportion_cutoff = batch_proportion_cutoff,
      use_dynamic_lambda = use_dynamic_lambda
    ),
    kmeans
  )
  class(res) <- c("params_sc_harmony_v2", "list")
  res
}

#' Wrapper function for parameters for HotSpot
#'
#' @description `weighted_graph` controls how the kNN distances become edge
#' weights. The default of `FALSE` follows the reference implementation: the
#' distances only decide who is a neighbour and every retained edge weighs one.
#' Set it to `TRUE` for the Gaussian kernel, whose width is the `ceil(k /
#' neighborhood_factor)`-th neighbour distance.
#'
#' @param model String. Model to use for modelling the GEX. One of `c("danb",
#' "normal", "bernoulli")`. Defaults to `"danb"`.
#' @param normalise Boolean. Shall the data be normalised. Defaults to `TRUE`.
#' @param weighted_graph Boolean. Shall the Gaussian kernel be applied to the
#' neighbour distances. Defaults to `FALSE`.
#' @param neighborhood_factor Numeric. Kernel width is the `ceil(k /
#' neighborhood_factor)`-th neighbour distance. Only read when `weighted_graph =
#' TRUE`. Defaults to `3.0`.
#' @param knn List. Optional overrides for kNN parameters. See
#' [bixverse::params_knn_defaults()] for available parameters: `k`,
#' `knn_method`, `ann_dist`, `search_budget`, `n_trees`, `delta`,
#' `diversify_prob`, `ef_budget`, `extract_knn`, `m`, `ef_construction`,
#' `ef_search`, `n_list` and `n_probe`. See [params_knn_defaults()] for the
#' available elements. Defaults to `list()`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item model - String. Model to use for modelling the GEX. One of `c("danb",
#'  "normal", "bernoulli")`. Defaults to `"danb"`.
#'  \item normalise - Boolean. Shall the data be normalised. Defaults to `TRUE`.
#'  \item weighted_graph - Boolean. Shall the Gaussian kernel be applied to the
#'  neighbour distances. Defaults to `FALSE`.
#'  \item neighborhood_factor - Numeric. Kernel width is the `ceil(k /
#'  neighborhood_factor)`-th neighbour distance. Only read when `weighted_graph
#'  = TRUE`. Defaults to `3.0`.
#'  \item The elements of [params_knn_defaults()], overridden by `knn`, spliced
#'  in at this position.
#' }
#'
#' @references DeTomaso and Yosef, Cell Systems, 2021
#'
#' @export
params_sc_hotspot <- function(
  model = c("danb", "normal", "bernoulli"),
  normalise = TRUE,
  weighted_graph = FALSE,
  neighborhood_factor = 3.0,
  knn = list()
) {
  model <- match.arg(model)

  # Checks
  checkmate::assertChoice(model, c("danb", "normal", "bernoulli"))
  checkmate::qassert(normalise, "B1")
  checkmate::qassert(weighted_graph, "B1")
  checkmate::qassert(neighborhood_factor, "R1(0,)")

  # Merge
  knn <- utils::modifyList(params_knn_defaults(), knn, keep.null = TRUE)

  # Return
  c(
    list(
      model = model,
      normalise = normalise,
      weighted_graph = weighted_graph,
      neighborhood_factor = neighborhood_factor
    ),
    knn
  )
}

#' Wrapper function for HVG detection parameters.
#'
#' @param method String. `"residual"` ranks genes by the residual variance of a
#' model fitted with [bixverse::fit_residuals_sc()], and needs that fit on the
#' object first. It also treats `hvg_no` as a per-group count and returns the
#' union across groups, so a grouped fit can select more than `hvg_no` genes.
#' One of `c("vst", "meanvarbin", "dispersion", "residual")`. Defaults to
#' `"vst"`.
#' @param loess_span Numeric. The span parameter for the loess function that is
#' used to standardise the variance for `method = "vst"`. Defaults to `0.3`.
#' @param num_bin Integer. Not yet implemented. Defaults to `20L`.
#' @param bin_method String. The binning method. One of `c("equal_width",
#' "equal_freq")`. Defaults to `"equal_width"`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item method - String. `"residual"` ranks genes by the residual variance of
#'  a model fitted with [bixverse::fit_residuals_sc()], and needs that fit on
#'  the object first. It also treats `hvg_no` as a per-group count and returns
#'  the union across groups, so a grouped fit can select more than `hvg_no`
#'  genes. One of `c("vst", "meanvarbin", "dispersion", "residual")`. Defaults
#'  to `"vst"`.
#'  \item loess_span - Numeric. The span parameter for the loess function that
#'  is used to standardise the variance for `method = "vst"`. Defaults to `0.3`.
#'  \item num_bin - Integer. Not yet implemented. Defaults to `20L`.
#'  \item bin_method - String. The binning method. One of `c("equal_width",
#'  "equal_freq")`. Defaults to `"equal_width"`.
#' }
#'
#' @export
params_sc_hvg <- function(
  method = c("vst", "meanvarbin", "dispersion", "residual"),
  loess_span = 0.3,
  num_bin = 20L,
  bin_method = c("equal_width", "equal_freq")
) {
  method <- match.arg(method)
  bin_method <- match.arg(bin_method)

  # Checks
  checkmate::assertChoice(
    method,
    c("vst", "meanvarbin", "dispersion", "residual")
  )
  checkmate::qassert(loess_span, "N1[0.1, 1]")
  checkmate::qassert(num_bin, "I1")
  checkmate::assertChoice(bin_method, c("equal_width", "equal_freq"))

  # Return
  list(
    method = method,
    loess_span = loess_span,
    num_bin = num_bin,
    bin_method = bin_method
  )
}

#' Parameters for single cell kNN searches
#'
#' @param k Integer. Number of neighbours. Defaults to `15L`.
#' @param knn_method String. Which method to use for the approximate nearest
#' neighbour search. One of `c("kmknn", "hnsw", "annoy", "nndescent", "ivf",
#' "exhaustive")`. Defaults to `"kmknn"`.
#' @param ann_dist String. Distance metric to use. One of `c("euclidean",
#' "cosine")`. Defaults to `"euclidean"`.
#' @param n_trees Integer. Annoy param: number of trees. Defaults to `50L`.
#' @param search_budget Integer or `NULL`. Annoy param: optional search budget
#' per tree. If `NULL`, defaults to `n_trees * k * 20L` internally. Defaults to
#' `NULL`.
#' @param delta Numeric. NNDescent param: early termination criterion. Defaults
#' to `0.001`.
#' @param diversify_prob Numeric. NNDescent param: diversification probability
#' applied at the end of index construction. Defaults to `0.0`.
#' @param ef_budget Integer or `NULL`. NNDescent param: optional query budget.
#' Higher values improve recall at the cost of speed. Defaults to `NULL`.
#' @param extract_knn Boolean. NNDescent param: hand back the graph the descent
#' already built instead of beam searching it. Skips the query pass entirely, so
#' it is much faster, at the cost of some recall. Rows the descent never filled
#' come back padded with duplicate edges. Ignored by every other method.
#' Defaults to `FALSE`.
#' @param m Integer. HNSW param: number of connections between layers. Defaults
#' to `16L`.
#' @param ef_construction Integer. HNSW param: size of the dynamic candidate
#' list during construction. Defaults to `200L`.
#' @param ef_search Integer. HNSW param: size of the candidate list at query
#' time. Higher values improve recall at the cost of speed. Defaults to `100L`.
#' @param n_list Integer or `NULL`. IVF param: number of clusters to generate.
#' If `NULL`, defaults to `sqrt(n)` internally. Defaults to `NULL`.
#' @param n_probe Integer or `NULL`. IVF param: number of clusters to query. If
#' `NULL`, defaults to `sqrt(n_list)` internally. Defaults to `NULL`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item k - Integer. Number of neighbours. Defaults to `15L`.
#'  \item knn_method - String. Which method to use for the approximate nearest
#'  neighbour search. One of `c("kmknn", "hnsw", "annoy", "nndescent", "ivf",
#'  "exhaustive")`. Defaults to `"kmknn"`.
#'  \item ann_dist - String. Distance metric to use. One of `c("euclidean",
#'  "cosine")`. Defaults to `"euclidean"`.
#'  \item n_trees - Integer. Annoy param: number of trees. Defaults to `50L`.
#'  \item search_budget - Integer or `NULL`. Annoy param: optional search budget
#'  per tree. If `NULL`, defaults to `n_trees * k * 20L` internally. Defaults to
#'  `NULL`.
#'  \item delta - Numeric. NNDescent param: early termination criterion.
#'  Defaults to `0.001`.
#'  \item diversify_prob - Numeric. NNDescent param: diversification probability
#'  applied at the end of index construction. Defaults to `0.0`.
#'  \item ef_budget - Integer or `NULL`. NNDescent param: optional query budget.
#'  Higher values improve recall at the cost of speed. Defaults to `NULL`.
#'  \item extract_knn - Boolean. NNDescent param: hand back the graph the
#'  descent already built instead of beam searching it. Skips the query pass
#'  entirely, so it is much faster, at the cost of some recall. Rows the descent
#'  never filled come back padded with duplicate edges. Ignored by every other
#'  method. Defaults to `FALSE`.
#'  \item m - Integer. HNSW param: number of connections between layers.
#'  Defaults to `16L`.
#'  \item ef_construction - Integer. HNSW param: size of the dynamic candidate
#'  list during construction. Defaults to `200L`.
#'  \item ef_search - Integer. HNSW param: size of the candidate list at query
#'  time. Higher values improve recall at the cost of speed. Defaults to `100L`.
#'  \item n_list - Integer or `NULL`. IVF param: number of clusters to generate.
#'  If `NULL`, defaults to `sqrt(n)` internally. Defaults to `NULL`.
#'  \item n_probe - Integer or `NULL`. IVF param: number of clusters to query.
#'  If `NULL`, defaults to `sqrt(n_list)` internally. Defaults to `NULL`.
#' }
#'
#' @export
params_sc_knn <- function(
  k = 15L,
  knn_method = c("kmknn", "hnsw", "annoy", "nndescent", "ivf", "exhaustive"),
  ann_dist = c("euclidean", "cosine"),
  n_trees = 50L,
  search_budget = NULL,
  delta = 0.001,
  diversify_prob = 0.0,
  ef_budget = NULL,
  extract_knn = FALSE,
  m = 16L,
  ef_construction = 200L,
  ef_search = 100L,
  n_list = NULL,
  n_probe = NULL
) {
  knn_method <- match.arg(knn_method)
  ann_dist <- match.arg(ann_dist)

  # Checks
  checkmate::qassert(k, "I1[1,)")
  checkmate::assertChoice(
    knn_method,
    c("kmknn", "hnsw", "annoy", "nndescent", "ivf", "exhaustive")
  )
  checkmate::assertChoice(ann_dist, c("euclidean", "cosine"))
  checkmate::qassert(n_trees, "I1[1,)")
  checkmate::qassert(search_budget, c("I1[1,)", "0"))
  checkmate::qassert(delta, "N1(0,)")
  checkmate::qassert(diversify_prob, "N1[0,1]")
  checkmate::qassert(ef_budget, c("I1[1,)", "0"))
  checkmate::qassert(extract_knn, "B1")
  checkmate::qassert(m, "I1[1,)")
  checkmate::qassert(ef_construction, "I1[1,)")
  checkmate::qassert(ef_search, "I1[1,)")
  checkmate::qassert(n_list, c("I1[1,)", "0"))
  checkmate::qassert(n_probe, c("I1[1,)", "0"))

  # Return
  list(
    k = k,
    knn_method = knn_method,
    ann_dist = ann_dist,
    n_trees = n_trees,
    search_budget = search_budget,
    delta = delta,
    diversify_prob = diversify_prob,
    ef_budget = ef_budget,
    extract_knn = extract_knn,
    m = m,
    ef_construction = ef_construction,
    ef_search = ef_search,
    n_list = n_list,
    n_probe = n_probe
  )
}

#' Wrapper function for MAGIC imputation parameters
#'
#' @description Parameters controlling the MAGIC imputation run by
#' [bixverse::run_magic_sc()]. The defaults mirror the reference implementation.
#'
#' @param n_steps Integer. Diffusion steps applied to the counts. Zero is legal
#' and hands back the un-imputed values, which is a cheap way to compare the
#' two. Defaults to `3L`.
#' @param clip_threshold Numeric. Imputed values below this are zeroed after the
#' last step. Defaults to `0.01`.
#' @param gene_batch_size Integer. Genes streamed off the binary store per
#' block. Bounds the scratch memory and is clamped to the number of requested
#' genes. Defaults to `1000L`.
#' @param layer String. Which stored layer to impute. The operator preserves
#' per-cell mass, so imputed values sit on the scale of whatever went in:
#' imputing raw counts and imputing log-normalised counts are different
#' operations rather than the same one rescaled. One of `c("norm", "raw")`.
#' Defaults to `"norm"`.
#' @param allow_large Boolean. Skip the output size guard. The dense output is
#' capped at 1e9 elements, i.e. 4 GB of `f32`. Defaults to `FALSE`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item n_steps - Integer. Diffusion steps applied to the counts. Zero is
#'  legal and hands back the un-imputed values, which is a cheap way to compare
#'  the two. Defaults to `3L`.
#'  \item clip_threshold - Numeric. Imputed values below this are zeroed after
#'  the last step. Defaults to `0.01`.
#'  \item gene_batch_size - Integer. Genes streamed off the binary store per
#'  block. Bounds the scratch memory and is clamped to the number of requested
#'  genes. Defaults to `1000L`.
#'  \item layer - String. Which stored layer to impute. The operator preserves
#'  per-cell mass, so imputed values sit on the scale of whatever went in:
#'  imputing raw counts and imputing log-normalised counts are different
#'  operations rather than the same one rescaled. One of `c("norm", "raw")`.
#'  Defaults to `"norm"`.
#'  \item allow_large - Boolean. Skip the output size guard. The dense output is
#'  capped at 1e9 elements, i.e. 4 GB of `f32`. Defaults to `FALSE`.
#' }
#'
#' @references van Dijk, et al., Cell, 2018.
#'
#' @export
params_sc_magic <- function(
  n_steps = 3L,
  clip_threshold = 0.01,
  gene_batch_size = 1000L,
  layer = c("norm", "raw"),
  allow_large = FALSE
) {
  layer <- match.arg(layer)

  # Checks
  checkmate::qassert(n_steps, "I1[0,)")
  checkmate::qassert(clip_threshold, "N1[0,)")
  checkmate::qassert(gene_batch_size, "I1[1,)")
  checkmate::assertChoice(layer, c("norm", "raw"))
  checkmate::qassert(allow_large, "B1")

  # Return
  list(
    n_steps = n_steps,
    clip_threshold = clip_threshold,
    gene_batch_size = gene_batch_size,
    layer = layer,
    allow_large = allow_large
  )
}

#' Wrapper function to generate QC metric params for single cell
#'
#' @param min_unique_genes Integer. Minimum number of unique genes per cell/spot
#' to be included. Defaults to `100L`.
#' @param min_lib_size Integer. Minimum library size per cell/spot to be
#' included. Defaults to `250L`.
#' @param min_cells Integer. Minimum number of cells a gene has to be expressed
#' to be included. Defaults to `10L`.
#' @param target_size Numeric. The target size for the normalisation. Defaults
#' to `10000.0`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item min_unique_genes - Integer. Minimum number of unique genes per
#'  cell/spot to be included. Defaults to `100L`.
#'  \item min_lib_size - Integer. Minimum library size per cell/spot to be
#'  included. Defaults to `250L`.
#'  \item min_cells - Integer. Minimum number of cells a gene has to be
#'  expressed to be included. Defaults to `10L`.
#'  \item target_size - Numeric. The target size for the normalisation. Defaults
#'  to `10000.0`.
#' }
#'
#' @export
params_sc_min_quality <- function(
  min_unique_genes = 100L,
  min_lib_size = 250L,
  min_cells = 10L,
  target_size = 10000.0
) {
  # Checks
  checkmate::qassert(min_unique_genes, "I1")
  checkmate::qassert(min_lib_size, "I1")
  checkmate::qassert(min_cells, "I1")
  checkmate::qassert(target_size, "N1")

  # Return
  list(
    min_unique_genes = min_unique_genes,
    min_lib_size = min_lib_size,
    min_cells = min_cells,
    target_size = target_size
  )
}

#' Wrapper function to provide data for mtx-based loading
#'
#' @param path_mtx Any. Path to the .mtx file Required.
#' @param path_obs Any. Path to the file containing cell/barcode info. Required.
#' @param path_var Any. Path to the file containing gene/variable info.
#' Required.
#' @param cells_as_rows Boolean. Do cells represent the rows or columns.
#' Required.
#' @param has_hdr Boolean. Do the plain text files have headers. Required.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item path_mtx - Any. Path to the .mtx file Required.
#'  \item path_obs - Any. Path to the file containing cell/barcode info.
#'  Required.
#'  \item path_var - Any. Path to the file containing gene/variable info.
#'  Required.
#'  \item cells_as_rows - Boolean. Do cells represent the rows or columns.
#'  Required.
#'  \item has_hdr - Boolean. Do the plain text files have headers. Required.
#' }
#'
#' @export
params_sc_mtx_io <- function(
  path_mtx,
  path_obs,
  path_var,
  cells_as_rows,
  has_hdr
) {
  # Checks
  checkmate::qassert(cells_as_rows, "B1")
  checkmate::qassert(has_hdr, "B1")

  checkmate::assertFileExists(path_mtx)
  checkmate::assertFileExists(path_obs)
  checkmate::assertFileExists(path_var)
  path_mtx <- path.expand(path_mtx)
  path_obs <- path.expand(path_obs)
  path_var <- path.expand(path_var)

  # Return
  list(
    path_mtx = path_mtx,
    path_obs = path_obs,
    path_var = path_var,
    cells_as_rows = cells_as_rows,
    has_hdr = has_hdr
  )
}

#' Wrapper function for parameters for neighbour identification in single cell
#'
#' @param full_snn Boolean. Shall the full shared nearest neighbour graph be
#' generated that generates edges between all cells instead of between only
#' neighbours. Defaults to `TRUE`.
#' @param pruning Numeric. Weights below this threshold will be set to 0 in the
#' generation of the sNN graph. Seurat uses for example `1/15` with `k = 20`. As
#' the default k is set to 15, we set it to `1/12`. Track this against `k`
#' rather than leaving it: the threshold is a share of the neighbourhood, so the
#' same value prunes far harder at a larger `k`. Over-pruning fails quietly, in
#' that you still get a clustering, but cells left with too few shared
#' neighbours drop out as singleton communities, which then show up downstream
#' as one-cell clusters with inflated [bixverse::run_paga_sc()] connectivities.
#' Defaults to `0.08333333333333333`.
#' @param snn_similarity String. The Jaccard similarity calculates the Jaccard
#' between the neighbours, whereas the rank method calculates edge weights based
#' on the ranking of shared neighbours. For the rank method, the weight is
#' determined by finding the shared neighbour with the lowest combined rank
#' across both cells, where lower-ranked (closer) shared neighbours result in
#' higher edge weights Both methods produce weights normalised to the range `[0,
#' 1]`. One of `c("jaccard", "rank")`. Defaults to `"jaccard"`.
#' @param knn List. Optional overrides for kNN parameters. See
#' [bixverse::params_knn_defaults()] for available parameters: `k`,
#' `knn_method`, `ann_dist`, `search_budget`, `n_trees`, `delta`,
#' `diversify_prob`, `ef_budget`, `extract_knn`, `m`, `ef_construction`,
#' `ef_search`, `n_list` and `n_probe`. See [params_knn_defaults()] for the
#' available elements. Defaults to `list()`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item full_snn - Boolean. Shall the full shared nearest neighbour graph be
#'  generated that generates edges between all cells instead of between only
#'  neighbours. Defaults to `TRUE`.
#'  \item pruning - Numeric. Weights below this threshold will be set to 0 in
#'  the generation of the sNN graph. Seurat uses for example `1/15` with `k =
#'  20`. As the default k is set to 15, we set it to `1/12`. Track this against
#'  `k` rather than leaving it: the threshold is a share of the neighbourhood,
#'  so the same value prunes far harder at a larger `k`. Over-pruning fails
#'  quietly, in that you still get a clustering, but cells left with too few
#'  shared neighbours drop out as singleton communities, which then show up
#'  downstream as one-cell clusters with inflated [bixverse::run_paga_sc()]
#'  connectivities. Defaults to `0.08333333333333333`.
#'  \item snn_similarity - String. The Jaccard similarity calculates the Jaccard
#'  between the neighbours, whereas the rank method calculates edge weights
#'  based on the ranking of shared neighbours. For the rank method, the weight
#'  is determined by finding the shared neighbour with the lowest combined rank
#'  across both cells, where lower-ranked (closer) shared neighbours result in
#'  higher edge weights Both methods produce weights normalised to the range
#'  `[0, 1]`. One of `c("jaccard", "rank")`. Defaults to `"jaccard"`.
#'  \item The elements of [params_knn_defaults()], overridden by `knn`, spliced
#'  in at this position.
#' }
#'
#' @export
params_sc_neighbours <- function(
  full_snn = TRUE,
  pruning = 0.08333333333333333,
  snn_similarity = c("jaccard", "rank"),
  knn = list()
) {
  snn_similarity <- match.arg(snn_similarity)

  # Checks
  checkmate::qassert(full_snn, "B1")
  checkmate::qassert(pruning, "N1[0, 1]")
  checkmate::assertChoice(snn_similarity, c("jaccard", "rank"))

  # Merge
  knn <- utils::modifyList(params_knn_defaults(), knn, keep.null = TRUE)

  # Return
  c(
    list(
      full_snn = full_snn,
      pruning = pruning,
      snn_similarity = snn_similarity
    ),
    knn
  )
}

#' Wrapper function for Palantir parameters
#'
#' @description Parameters controlling the Palantir trajectory inference. The
#' kNN graph you hand to [bixverse::run_palantir_sc()] feeds the diffusion
#' kernel. The geodesics are measured over a second kNN graph that Palantir
#' builds internally on the multiscale space, and `knn` is what controls that
#' one. It is a different knob from `k` in the kNN parameter block, which sizes
#' the backend index. Palantir overrides `k` and `ann_dist` for its internal
#' search, so only `knn_method` and the backend tuning parameters have an
#' effect.
#'
#' @param n_dcs Integer. Diffusion components to extract before the multiscale
#' scaling. Defaults to `10L`.
#' @param n_eigs Integer or `NULL`. Eigenvectors to retain, not components: the
#' trivial leading eigenvector is counted here and then dropped, so `3L` leaves
#' two multiscale components. If `NULL`, the count is picked from the largest
#' eigengap, as the reference does. Defaults to `NULL`.
#' @param knn Integer. Neighbours for the geodesic graph over the multiscale
#' space, in the reference's self-inclusive convention. Defaults to `30L`.
#' @param num_waypoints Integer. Target waypoint count for the max-min sampler.
#' Defaults to `1200L`.
#' @param scale_components Boolean. Min-max scale each multiscale component to
#' `[0, 1]` before any distance is taken. Defaults to `TRUE`.
#' @param use_early_cell_as_start Boolean. Use the provided early cell directly
#' rather than snapping it to the nearest diffusion-map boundary cell. Defaults
#' to `TRUE`.
#' @param max_iterations Integer. Iteration cap for the pseudotime refinement.
#' Defaults to `25L`.
#' @param branch_prob_threshold Numeric. Fate probabilities below this are
#' zeroed. Defaults to `0.01`.
#' @param lanczos_basis_size Integer or `NULL`. Krylov basis vectors held at
#' once during the diffusion-map eigendecomposition. If `NULL`, derived from the
#' requested component count. Defaults to `NULL`.
#' @param lanczos_max_restarts Integer. Maximum restart cycles for the Lanczos
#' solver. Defaults to `16L`.
#' @param lanczos_tol Numeric. Relative residual tolerance for the Lanczos
#' solver. Defaults to `1e-08`.
#' @param knn_params List. Optional overrides for the kNN parameters of the
#' internal multiscale search. See [bixverse::params_knn_defaults()] for
#' available parameters: `k`, `knn_method`, `ann_dist`, `search_budget`,
#' `n_trees`, `delta`, `diversify_prob`, `ef_budget`, `m`, `ef_construction`,
#' `ef_search`, `n_list` and `n_probe`. See [params_knn_defaults()] for the
#' available elements. Defaults to `list()`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item n_dcs - Integer. Diffusion components to extract before the multiscale
#'  scaling. Defaults to `10L`.
#'  \item n_eigs - Integer or `NULL`. Eigenvectors to retain, not components:
#'  the trivial leading eigenvector is counted here and then dropped, so `3L`
#'  leaves two multiscale components. If `NULL`, the count is picked from the
#'  largest eigengap, as the reference does. Defaults to `NULL`.
#'  \item knn - Integer. Neighbours for the geodesic graph over the multiscale
#'  space, in the reference's self-inclusive convention. Defaults to `30L`.
#'  \item num_waypoints - Integer. Target waypoint count for the max-min
#'  sampler. Defaults to `1200L`.
#'  \item scale_components - Boolean. Min-max scale each multiscale component to
#'  `[0, 1]` before any distance is taken. Defaults to `TRUE`.
#'  \item use_early_cell_as_start - Boolean. Use the provided early cell
#'  directly rather than snapping it to the nearest diffusion-map boundary cell.
#'  Defaults to `TRUE`.
#'  \item max_iterations - Integer. Iteration cap for the pseudotime refinement.
#'  Defaults to `25L`.
#'  \item branch_prob_threshold - Numeric. Fate probabilities below this are
#'  zeroed. Defaults to `0.01`.
#'  \item lanczos_basis_size - Integer or `NULL`. Krylov basis vectors held at
#'  once during the diffusion-map eigendecomposition. If `NULL`, derived from
#'  the requested component count. Defaults to `NULL`.
#'  \item lanczos_max_restarts - Integer. Maximum restart cycles for the Lanczos
#'  solver. Defaults to `16L`.
#'  \item lanczos_tol - Numeric. Relative residual tolerance for the Lanczos
#'  solver. Defaults to `1e-08`.
#'  \item The elements of [params_knn_defaults()], overridden by `knn_params`,
#'  spliced in at this position.
#' }
#'
#' @references Setty, et al., Nat. Biotechnol., 2019.
#'
#' @export
params_sc_palantir <- function(
  n_dcs = 10L,
  n_eigs = NULL,
  knn = 30L,
  num_waypoints = 1200L,
  scale_components = TRUE,
  use_early_cell_as_start = TRUE,
  max_iterations = 25L,
  branch_prob_threshold = 0.01,
  lanczos_basis_size = NULL,
  lanczos_max_restarts = 16L,
  lanczos_tol = 1e-08,
  knn_params = list()
) {
  # Checks
  checkmate::qassert(n_dcs, "I1[3,)")
  checkmate::qassert(n_eigs, c("I1[3,)", "0"))
  checkmate::qassert(knn, "I1[6,)")
  checkmate::qassert(num_waypoints, "I1[1,)")
  checkmate::qassert(scale_components, "B1")
  checkmate::qassert(use_early_cell_as_start, "B1")
  checkmate::qassert(max_iterations, "I1[2,)")
  checkmate::qassert(branch_prob_threshold, "N1[0,1]")
  checkmate::qassert(lanczos_basis_size, c("I1[1,)", "0"))
  checkmate::qassert(lanczos_max_restarts, "I1[1,)")
  checkmate::qassert(lanczos_tol, "N1(0,)")

  # Merge
  knn_params <- utils::modifyList(
    params_knn_defaults(),
    knn_params,
    keep.null = TRUE
  )

  # Return
  c(
    list(
      n_dcs = n_dcs,
      n_eigs = n_eigs,
      knn = knn,
      num_waypoints = num_waypoints,
      scale_components = scale_components,
      use_early_cell_as_start = use_early_cell_as_start,
      max_iterations = max_iterations,
      branch_prob_threshold = branch_prob_threshold,
      lanczos_basis_size = lanczos_basis_size,
      lanczos_max_restarts = lanczos_max_restarts,
      lanczos_tol = lanczos_tol
    ),
    knn_params
  )
}

#' Wrapper for PCA specifically designed for single cells
#'
#' @param mean_center Boolean. Shall the data be mean centred Defaults to
#' `TRUE`.
#' @param normalise_variance Boolean. Shall the data have normalised variance
#' Defaults to `TRUE`.
#' @param randomised Boolean. Shall fast, approximate randomised SVD be used.
#' Defaults to `TRUE`.
#' @param clr Boolean. Shall the CLR-type `PFlogPF` be applied, see Booeshaghi,
#' et al. Defaults to `FALSE`.
#' @param size_factor Numeric. The used size factor during I/O. It needs to be
#' the same as during I/O to have correct results when using the `PFlogPF`
#' transformation. Defaults to `10000.0`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item mean_center - Boolean. Shall the data be mean centred Defaults to
#'  `TRUE`.
#'  \item normalise_variance - Boolean. Shall the data have normalised variance
#'  Defaults to `TRUE`.
#'  \item randomised - Boolean. Shall fast, approximate randomised SVD be used.
#'  Defaults to `TRUE`.
#'  \item clr - Boolean. Shall the CLR-type `PFlogPF` be applied, see
#'  Booeshaghi, et al. Defaults to `FALSE`.
#'  \item size_factor - Numeric. The used size factor during I/O. It needs to be
#'  the same as during I/O to have correct results when using the `PFlogPF`
#'  transformation. Defaults to `10000.0`.
#' }
#'
#' @export
params_sc_pca <- function(
  mean_center = TRUE,
  normalise_variance = TRUE,
  randomised = TRUE,
  clr = FALSE,
  size_factor = 10000.0
) {
  # Checks
  checkmate::qassert(mean_center, "B1")
  checkmate::qassert(normalise_variance, "B1")
  checkmate::qassert(randomised, "B1")
  checkmate::qassert(clr, "B1")
  checkmate::qassert(size_factor, "N1")

  # Return
  list(
    mean_center = mean_center,
    normalise_variance = normalise_variance,
    randomised = randomised,
    clr = clr,
    size_factor = size_factor
  )
}

#' Wrapper function for scTransform (v2) parameters
#'
#' @description Defaults are sctransform's own with `vst.flavor = "v2"` applied.
#' Only the step-1 fit scales with `n_genes` and `n_cells`: those bound the
#' subsample the negative binomial models are fitted on, and every later pass
#' streams gene by gene. Raising them costs fitting time, not memory.
#'
#' @param n_genes Integer. Genes in the step-1 subsample. Defaults to `2000L`.
#' @param n_cells Integer. Cells in the step-1 subsample. Defaults to `2000L`.
#' @param min_cells Integer. Minimum number of cells a gene must be detected in
#' to be modelled. Defaults to `5L`.
#' @param bw_adjust Numeric. Bandwidth multiplier for the kernel regression that
#' regularises the parameters. Defaults to `3.0`.
#' @param gmean_eps Numeric. Offset in the geometric mean. Defaults to `1.0`.
#' @param outlier_th Numeric. Threshold, in median absolute deviations, past
#' which a step-1 fit is treated as an outlier. Defaults to `10.0`.
#' @param poisson_diff_theta Numeric. Below this, the fitted dispersion is taken
#' as the Poisson limit. Defaults to `0.001`.
#' @param clip_min Numeric or `NULL`. Lower residual clipping bound. `NULL` uses
#' `-sqrt(n_cells)`. Must be given together with `clip_max`. Defaults to `NULL`.
#' @param clip_max Numeric or `NULL`. Upper residual clipping bound. `NULL` uses
#' `sqrt(n_cells)`. Must be given together with `clip_min`. Defaults to `NULL`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item n_genes - Integer. Genes in the step-1 subsample. Defaults to `2000L`.
#'  \item n_cells - Integer. Cells in the step-1 subsample. Defaults to `2000L`.
#'  \item min_cells - Integer. Minimum number of cells a gene must be detected
#'  in to be modelled. Defaults to `5L`.
#'  \item bw_adjust - Numeric. Bandwidth multiplier for the kernel regression
#'  that regularises the parameters. Defaults to `3.0`.
#'  \item gmean_eps - Numeric. Offset in the geometric mean. Defaults to `1.0`.
#'  \item outlier_th - Numeric. Threshold, in median absolute deviations, past
#'  which a step-1 fit is treated as an outlier. Defaults to `10.0`.
#'  \item poisson_diff_theta - Numeric. Below this, the fitted dispersion is
#'  taken as the Poisson limit. Defaults to `0.001`.
#'  \item clip_min - Numeric or `NULL`. Lower residual clipping bound. `NULL`
#'  uses `-sqrt(n_cells)`. Must be given together with `clip_max`. Defaults to
#'  `NULL`.
#'  \item clip_max - Numeric or `NULL`. Upper residual clipping bound. `NULL`
#'  uses `sqrt(n_cells)`. Must be given together with `clip_min`. Defaults to
#'  `NULL`.
#' }
#'
#' @references Choudhary and Satija, Genome Biology, 2022.
#'
#' @export
params_sc_sctransform <- function(
  n_genes = 2000L,
  n_cells = 2000L,
  min_cells = 5L,
  bw_adjust = 3.0,
  gmean_eps = 1.0,
  outlier_th = 10.0,
  poisson_diff_theta = 0.001,
  clip_min = NULL,
  clip_max = NULL
) {
  # Checks
  checkmate::qassert(n_genes, "I1[1,)")
  checkmate::qassert(n_cells, "I1[1,)")
  checkmate::qassert(min_cells, "I1[1,)")
  checkmate::qassert(bw_adjust, "N1(0,)")
  checkmate::qassert(gmean_eps, "N1[0,)")
  checkmate::qassert(outlier_th, "N1(0,)")
  checkmate::qassert(poisson_diff_theta, "N1(0,)")
  checkmate::qassert(clip_min, c("N1", "0"))
  checkmate::qassert(clip_max, c("N1", "0"))

  assert_clip_range(clip_min, clip_max)

  # Return
  list(
    n_genes = n_genes,
    n_cells = n_cells,
    min_cells = min_cells,
    bw_adjust = bw_adjust,
    gmean_eps = gmean_eps,
    outlier_th = outlier_th,
    poisson_diff_theta = poisson_diff_theta,
    clip_min = clip_min,
    clip_max = clip_max
  )
}

#' Wrapper function for the SEACells parameters
#'
#' @param n_sea_cells Integer. Number of SEA cells to detect. Required.
#' @param max_fw_iters Integer. Maximum iterations for the Franke-Wolfe
#' algorithm. Defaults to `50L`.
#' @param convergence_epsilon Numeric. Convergence threshold. Algorithm stops
#' when RSS change < epsilon * RSS(0). Defaults to `0.001`.
#' @param max_iter Integer. Maximum iterations to run SEACells for. Defaults to
#' `100L`.
#' @param min_iter Integer. Minimum iterations to run SEACells for. Defaults to
#' `10L`.
#' @param greedy_threshold Integer. Maximum number of cells before defaulting to
#' rapid random selection of archetypes. Defaults to `20000L`.
#' @param graph_building String. Graph building method. Defaults to `"union"`.
#' @param pruning Boolean. Shall tiny values be pruned during Franke-Wolfe
#' updates. Defaults to `TRUE`.
#' @param pruning_threshold Numeric. If `pruning = TRUE` values below which
#' threshold shall be pruned. Defaults to `1e-07`.
#' @param n_landmarks Integer or `NULL`. If provided, it will use the Nystroem
#' extension during the archetype finding. Useful for larger data sets. Defaults
#' to `NULL`.
#' @param knn List. Optional overrides for kNN parameters. See
#' [bixverse::params_knn_defaults()] for available parameters: `k`,
#' `knn_method`, `ann_dist`, `search_budget`, `n_trees`, `delta`,
#' `diversify_prob`, `ef_budget`, `extract_knn`, `m`, `ef_construction`,
#' `ef_search`, `n_list` and `n_probe`. See [params_knn_defaults()] for the
#' available elements. Defaults to `list()`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item n_sea_cells - Integer. Number of SEA cells to detect. Required.
#'  \item max_fw_iters - Integer. Maximum iterations for the Franke-Wolfe
#'  algorithm. Defaults to `50L`.
#'  \item convergence_epsilon - Numeric. Convergence threshold. Algorithm stops
#'  when RSS change < epsilon * RSS(0). Defaults to `0.001`.
#'  \item max_iter - Integer. Maximum iterations to run SEACells for. Defaults
#'  to `100L`.
#'  \item min_iter - Integer. Minimum iterations to run SEACells for. Defaults
#'  to `10L`.
#'  \item greedy_threshold - Integer. Maximum number of cells before defaulting
#'  to rapid random selection of archetypes. Defaults to `20000L`.
#'  \item graph_building - String. Graph building method. Defaults to `"union"`.
#'  \item pruning - Boolean. Shall tiny values be pruned during Franke-Wolfe
#'  updates. Defaults to `TRUE`.
#'  \item pruning_threshold - Numeric. If `pruning = TRUE` values below which
#'  threshold shall be pruned. Defaults to `1e-07`.
#'  \item n_landmarks - Integer or `NULL`. If provided, it will use the Nystroem
#'  extension during the archetype finding. Useful for larger data sets.
#'  Defaults to `NULL`.
#'  \item The elements of [params_knn_defaults()], overridden by `knn`, spliced
#'  in at this position.
#' }
#'
#' @export
params_sc_seacells <- function(
  n_sea_cells,
  max_fw_iters = 50L,
  convergence_epsilon = 0.001,
  max_iter = 100L,
  min_iter = 10L,
  greedy_threshold = 20000L,
  graph_building = "union",
  pruning = TRUE,
  pruning_threshold = 1e-07,
  n_landmarks = NULL,
  knn = list()
) {
  # Checks
  checkmate::qassert(n_sea_cells, "I1[1,)")
  checkmate::qassert(max_fw_iters, "I1[1,)")
  checkmate::qassert(convergence_epsilon, "N1")
  checkmate::qassert(max_iter, "I1[1,)")
  checkmate::qassert(min_iter, "I1[1,)")
  checkmate::qassert(greedy_threshold, "I1[1,)")
  checkmate::qassert(graph_building, "S1")
  checkmate::qassert(pruning, "B1")
  checkmate::qassert(pruning_threshold, "N1")
  checkmate::qassert(n_landmarks, c("I1", "0"))

  # Merge
  knn <- utils::modifyList(
    params_knn_defaults(),
    utils::modifyList(list(k = 25L), knn, keep.null = TRUE),
    keep.null = TRUE
  )

  # Return
  c(
    list(
      n_sea_cells = n_sea_cells,
      max_fw_iters = max_fw_iters,
      convergence_epsilon = convergence_epsilon,
      max_iter = max_iter,
      min_iter = min_iter,
      greedy_threshold = greedy_threshold,
      graph_building = graph_building,
      pruning = pruning,
      pruning_threshold = pruning_threshold,
      n_landmarks = n_landmarks
    ),
    knn
  )
}

#' Wrapper function for the Seurat CCA parameters
#'
#' @param num_cc Integer. Number of canonical correlation dimensions to compute
#' for the anchor space. The effective rank used is `max(num_cc, dims)`.
#' Defaults to `30L`.
#' @param dims Integer. Number of dimensions used for the anchor kNN queries and
#' the size of the returned embedding. Defaults to `30L`.
#' @param k_anchor Integer. Neighbourhood size for the mutual nearest neighbour
#' anchor search. Defaults to `5L`.
#' @param k_filter Integer. Neighbourhood size for the gene-space anchor filter.
#' Defaults to `200L`.
#' @param k_score Integer. Neighbourhood size for the shared-neighbour anchor
#' scoring. Defaults to `30L`.
#' @param k_weight Integer. Neighbourhood size for the kernel weights applied
#' during the correction. Defaults to `100L`.
#' @param n_top_features Integer. Number of top-loading genes used for the
#' gene-space anchor filter. Defaults to `200L`.
#' @param l2_norm Boolean. Shall the canonical correlation embedding be
#' L2-normalised per cell. Defaults to `TRUE`.
#' @param sd Numeric. Bandwidth divisor of the Gaussian kernel used for the
#' anchor weights. Defaults to `1.0`.
#' @param knn List. Optional overrides for kNN parameters. See
#' [bixverse::params_knn_defaults()] for available parameters: `k`,
#' `knn_method`, `ann_dist`, `search_budget`, `n_trees`, `delta`,
#' `diversify_prob`, `ef_budget`, `extract_knn`, `m`, `ef_construction`,
#' `ef_search`, `n_list` and `n_probe`. Note that `k` is unused here, the
#' neighbourhood sizes come from `k_anchor`, `k_filter`, `k_score` and
#' `k_weight`. See [params_knn_defaults()] for the available elements. Defaults
#' to `list()`.
#' @param pca List. Parameters to feed through to the optional recalculation of
#' the PCA, see [params_sc_pca()]. See [params_sc_pca()] for the available
#' elements. Defaults to `params_sc_pca()`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item num_cc - Integer. Number of canonical correlation dimensions to
#'  compute for the anchor space. The effective rank used is `max(num_cc,
#'  dims)`. Defaults to `30L`.
#'  \item dims - Integer. Number of dimensions used for the anchor kNN queries
#'  and the size of the returned embedding. Defaults to `30L`.
#'  \item k_anchor - Integer. Neighbourhood size for the mutual nearest
#'  neighbour anchor search. Defaults to `5L`.
#'  \item k_filter - Integer. Neighbourhood size for the gene-space anchor
#'  filter. Defaults to `200L`.
#'  \item k_score - Integer. Neighbourhood size for the shared-neighbour anchor
#'  scoring. Defaults to `30L`.
#'  \item k_weight - Integer. Neighbourhood size for the kernel weights applied
#'  during the correction. Defaults to `100L`.
#'  \item n_top_features - Integer. Number of top-loading genes used for the
#'  gene-space anchor filter. Defaults to `200L`.
#'  \item l2_norm - Boolean. Shall the canonical correlation embedding be
#'  L2-normalised per cell. Defaults to `TRUE`.
#'  \item sd - Numeric. Bandwidth divisor of the Gaussian kernel used for the
#'  anchor weights. Defaults to `1.0`.
#'  \item The elements of [params_knn_defaults()], overridden by `knn`, spliced
#'  in at this position.
#'  \item The elements of [params_sc_pca()], overridden by `pca`, spliced in at
#'  this position.
#' }
#'
#' @references Stuart, et al., Cell, 2019
#'
#' @export
params_sc_seurat_cca <- function(
  num_cc = 30L,
  dims = 30L,
  k_anchor = 5L,
  k_filter = 200L,
  k_score = 30L,
  k_weight = 100L,
  n_top_features = 200L,
  l2_norm = TRUE,
  sd = 1.0,
  knn = list(),
  pca = params_sc_pca()
) {
  # Checks
  checkmate::qassert(num_cc, "I1[1,)")
  checkmate::qassert(dims, "I1[1,)")
  checkmate::qassert(k_anchor, "I1[1,)")
  checkmate::qassert(k_filter, "I1[0,)")
  checkmate::qassert(k_score, "I1[1,)")
  checkmate::qassert(k_weight, "I1[1,)")
  checkmate::qassert(n_top_features, "I1[1,)")
  checkmate::qassert(l2_norm, "B1")
  checkmate::qassert(sd, "N1(0,)")

  # Merge
  knn <- utils::modifyList(
    params_knn_defaults(),
    utils::modifyList(list(ann_dist = "cosine"), knn, keep.null = TRUE),
    keep.null = TRUE
  )
  pca <- utils::modifyList(params_sc_pca(), pca, keep.null = TRUE)

  # Return
  c(
    list(
      num_cc = num_cc,
      dims = dims,
      k_anchor = k_anchor,
      k_filter = k_filter,
      k_score = k_score,
      k_weight = k_weight,
      n_top_features = n_top_features,
      l2_norm = l2_norm,
      sd = sd
    ),
    knn,
    pca
  )
}

