#' Wrapper function for parameters for SuperCell generation
#'
#' @param walk_length Integer. Walk length for the Walktrap algorithm. Defaults
#' to `3L`.
#' @param graining_factor Numeric. Graining level of data (proportion of number
#' of single cells in the initial dataset to the number of metacells in the
#' final dataset). (One meta cell per 20 cells.) Defaults to `20.0`.
#' @param use_kernel Boolean. Shall a kernel function akin to MAGIC be applied
#' akin to the approach in SuperCell2, see Hérault, et al., bioRxiv, 2026 and
#' van Dijk, et al., Cell, 2018. Defaults to `TRUE`.
#' @param k_ith Integer or `NULL`. The k-ith neighbour to use for the kernel.
#' Defaults to `NULL`.
#' @param max_support Integer or `NULL`. Caps each cell's walk-probability
#' vector to its top entries by mass, bounding memory at ~`max_support *
#' n_cells` on large data. Makes the result an approximation. `NULL` (default)
#' keeps the walks exact. Defaults to `NULL`.
#' @param knn List. Optional overrides for kNN parameters. See
#' [bixverse::params_knn_defaults()] for available parameters: `k`,
#' `knn_method`, `ann_dist`, `search_budget`, `n_trees`, `delta`,
#' `diversify_prob`, `ef_budget`, `extract_knn`, `m`, `ef_construction`,
#' `ef_search`, `n_list` and `n_probe`. See [params_knn_defaults()] for the
#' available elements. Defaults to `list()`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item walk_length - Integer. Walk length for the Walktrap algorithm.
#'  Defaults to `3L`.
#'  \item graining_factor - Numeric. Graining level of data (proportion of
#'  number of single cells in the initial dataset to the number of metacells in
#'  the final dataset). (One meta cell per 20 cells.) Defaults to `20.0`.
#'  \item use_kernel - Boolean. Shall a kernel function akin to MAGIC be applied
#'  akin to the approach in SuperCell2, see Hérault, et al., bioRxiv, 2026 and
#'  van Dijk, et al., Cell, 2018. Defaults to `TRUE`.
#'  \item k_ith - Integer or `NULL`. The k-ith neighbour to use for the kernel.
#'  Defaults to `NULL`.
#'  \item max_support - Integer or `NULL`. Caps each cell's walk-probability
#'  vector to its top entries by mass, bounding memory at ~`max_support *
#'  n_cells` on large data. Makes the result an approximation. `NULL` (default)
#'  keeps the walks exact. Defaults to `NULL`.
#'  \item The elements of [params_knn_defaults()], overridden by `knn`, spliced
#'  in at this position.
#' }
#'
#' @export
params_sc_supercell <- function(
  walk_length = 3L,
  graining_factor = 20.0,
  use_kernel = TRUE,
  k_ith = NULL,
  max_support = NULL,
  knn = list()
) {
  # Checks
  checkmate::qassert(walk_length, "I1[1,)")
  checkmate::qassert(graining_factor, "N1")
  checkmate::qassert(use_kernel, "B1")
  checkmate::qassert(k_ith, c("I1", "0"))
  checkmate::qassert(max_support, c("I1[1,)", "0"))

  # Merge
  knn <- utils::modifyList(
    params_knn_defaults(),
    utils::modifyList(list(k = 5L, ann_dist = "cosine"), knn, keep.null = TRUE),
    keep.null = TRUE
  )

  # Return
  c(
    list(
      walk_length = walk_length,
      graining_factor = graining_factor,
      use_kernel = use_kernel,
      k_ith = k_ith,
      max_support = max_support
    ),
    knn
  )
}

#' Default parameters for generation of synthetic CellSweep data
#'
#' @description Shapes the fixture with a planted ambient profile that
#' [bixverse::generate_cellsweep_test_data()] builds. The defaults give 600 real
#' barcodes over 3 cell types plus 2000 empty droplets, on 200 genes.
#'
#' @details
#' The soup is the first cell type plus flat background rather than a mixture
#' of every cell type profile. A soup sitting in the span of the cell type
#' profiles makes the contamination fraction unidentifiable, and the fixture
#' would then be testing the repulsion term rather than the model.
#'
#' @param n_real Integer. Number of real barcodes. Cell types are assigned
#' round-robin over them. Defaults to `600L`.
#' @param n_empty Integer. Number of empty droplets. The ambient profile is
#' estimated off these, so at least 30 and preferably a lot more. Defaults to
#' `2000L`.
#' @param n_genes Integer. Number of genes. Defaults to `200L`.
#' @param n_celltypes Integer. Number of cell types. Defaults to `3L`.
#' @param n_markers Integer. Width of each cell type's marker block. The blocks
#' are contiguous and disjoint, so `n_markers * n_celltypes` has to fit into
#' `n_genes`. Defaults to `20L`.
#' @param marker_weight Numeric. Enrichment of a marker gene over background in
#' its own cell type's profile. Must exceed 1. Defaults to `25.0`.
#' @param ambient_dominance Numeric. Fraction of the soup coming from the first
#' cell type. The remainder is flat background. Defaults to `0.6`.
#' @param alpha_mean Numeric. Mean planted ambient fraction across real
#' barcodes. Defaults to `0.3`.
#' @param alpha_sd Numeric. Spread of the planted ambient fraction. Defaults to
#' `0.12`.
#' @param real_lib_size Integer. Expected library size of a real barcode.
#' Defaults to `3000L`.
#' @param empty_lib_size Integer. Expected library size of an empty droplet.
#' Defaults to `120L`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item n_real - Integer. Number of real barcodes. Cell types are assigned
#'  round-robin over them. Defaults to `600L`.
#'  \item n_empty - Integer. Number of empty droplets. The ambient profile is
#'  estimated off these, so at least 30 and preferably a lot more. Defaults to
#'  `2000L`.
#'  \item n_genes - Integer. Number of genes. Defaults to `200L`.
#'  \item n_celltypes - Integer. Number of cell types. Defaults to `3L`.
#'  \item n_markers - Integer. Width of each cell type's marker block. The
#'  blocks are contiguous and disjoint, so `n_markers * n_celltypes` has to fit
#'  into `n_genes`. Defaults to `20L`.
#'  \item marker_weight - Numeric. Enrichment of a marker gene over background
#'  in its own cell type's profile. Must exceed 1. Defaults to `25.0`.
#'  \item ambient_dominance - Numeric. Fraction of the soup coming from the
#'  first cell type. The remainder is flat background. Defaults to `0.6`.
#'  \item alpha_mean - Numeric. Mean planted ambient fraction across real
#'  barcodes. Defaults to `0.3`.
#'  \item alpha_sd - Numeric. Spread of the planted ambient fraction. Defaults
#'  to `0.12`.
#'  \item real_lib_size - Integer. Expected library size of a real barcode.
#'  Defaults to `3000L`.
#'  \item empty_lib_size - Integer. Expected library size of an empty droplet.
#'  Defaults to `120L`.
#' }
#'
#' @export
params_sc_synthetic_cellsweep <- function(
  n_real = 600L,
  n_empty = 2000L,
  n_genes = 200L,
  n_celltypes = 3L,
  n_markers = 20L,
  marker_weight = 25.0,
  ambient_dominance = 0.6,
  alpha_mean = 0.3,
  alpha_sd = 0.12,
  real_lib_size = 3000L,
  empty_lib_size = 120L
) {
  # Checks
  checkmate::qassert(n_real, "I1[1,)")
  checkmate::qassert(n_empty, "I1[30,)")
  checkmate::qassert(n_genes, "I1[1,)")
  checkmate::qassert(n_celltypes, "I1[1,)")
  checkmate::qassert(n_markers, "I1[1,)")
  checkmate::qassert(marker_weight, "N1(1,)")
  checkmate::qassert(ambient_dominance, "N1[0,1]")
  checkmate::qassert(alpha_mean, "N1[0.02,0.85]")
  checkmate::qassert(alpha_sd, "N1[0,)")
  checkmate::qassert(real_lib_size, "I1[1,)")
  checkmate::qassert(empty_lib_size, "I1[1,)")

  checkmate::assertTRUE(n_markers * n_celltypes <= n_genes)

  # Return
  list(
    n_real = n_real,
    n_empty = n_empty,
    n_genes = n_genes,
    n_celltypes = n_celltypes,
    n_markers = n_markers,
    marker_weight = marker_weight,
    ambient_dominance = ambient_dominance,
    alpha_mean = alpha_mean,
    alpha_sd = alpha_sd,
    real_lib_size = real_lib_size,
    empty_lib_size = empty_lib_size
  )
}

#' Default parameters for generation of synthetic single cell data (RNA)
#'
#' @description For the generation of synthetic single cell data mostly for
#' testing or showcasing purposes. The default configurations generates 1000
#' cells x 100 genes with genes 1:10 being cell markers for cell type 1, genes
#' 11:20 for cell type 2 and genes 21:30 for cell type.
#'
#' @param n_cells Integer. Number of cells. Defaults to `1000L`.
#' @param n_genes Integer. Number of genes. Defaults to `100L`.
#' @param n_batches Integer. Number of batches. Defaults to `1L`.
#' @param marker_genes Any. A nested list that indicates which gene indices are
#' markers for which cell. Defaults to `list(cell_type_1 = list(marker_genes =
#' 0:9), cell_type_2 = list(marker_genes = 10:19), cell_type_3 =
#' list(marker_genes = 20:29))`.
#' @param batch_effect_strength String. The strength of the batch effect to add.
#' One of `c("strong", "medium", "weak")`. Defaults to `"strong"`.
#' @param n_samples Integer or `NULL`. Shall sample membership be added to the
#' synthetic data. If you want sample information you need to provide
#' `n_samples` and `sample_bias`. Defaults to `NULL`.
#' @param sample_bias Any. One of `c("even", "slightly_uneven", "very_uneven")`
#' Defaults to `NULL`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item n_cells - Integer. Number of cells. Defaults to `1000L`.
#'  \item n_genes - Integer. Number of genes. Defaults to `100L`.
#'  \item marker_genes - Any. A nested list that indicates which gene indices
#'  are markers for which cell. Defaults to `list(cell_type_1 =
#'  list(marker_genes = 0:9), cell_type_2 = list(marker_genes = 10:19),
#'  cell_type_3 = list(marker_genes = 20:29))`.
#'  \item n_batches - Integer. Number of batches. Defaults to `1L`.
#'  \item batch_effect_strength - String. The strength of the batch effect to
#'  add. One of `c("strong", "medium", "weak")`. Defaults to `"strong"`.
#'  \item n_samples - Integer or `NULL`. Shall sample membership be added to the
#'  synthetic data. If you want sample information you need to provide
#'  `n_samples` and `sample_bias`. Defaults to `NULL`.
#'  \item sample_bias - Any. One of `c("even", "slightly_uneven",
#'  "very_uneven")` Defaults to `NULL`.
#' }
#'
#' @export
params_sc_synthetic_data <- function(
  n_cells = 1000L,
  n_genes = 100L,
  n_batches = 1L,
  marker_genes = list(
    cell_type_1 = list(marker_genes = 0:9),
    cell_type_2 = list(marker_genes = 10:19),
    cell_type_3 = list(marker_genes = 20:29)
  ),
  batch_effect_strength = c("strong", "medium", "weak"),
  n_samples = NULL,
  sample_bias = NULL
) {
  batch_effect_strength <- match.arg(batch_effect_strength)

  # Checks
  checkmate::qassert(n_cells, "I1")
  checkmate::qassert(n_genes, "I1")
  checkmate::qassert(n_batches, "I1")
  checkmate::assertChoice(batch_effect_strength, c("strong", "medium", "weak"))
  checkmate::qassert(n_samples, c("I1", "0"))

  checkmate::assertList(marker_genes, types = "list", names = "named")
  checkmate::assert(
    checkmate::testNull(sample_bias),
    checkmate::testChoice(
      sample_bias,
      c("even", "slightly_uneven", "very_uneven")
    )
  )
  if (is.null(n_samples) != is.null(sample_bias)) {
    stop(paste(
      "`n_samples` and `sample_bias` must be provided together.",
      "Supply both to add sample membership, or neither to omit it."
    ))
  }

  # Return
  list(
    n_cells = n_cells,
    n_genes = n_genes,
    marker_genes = marker_genes,
    n_batches = n_batches,
    batch_effect_strength = batch_effect_strength,
    n_samples = n_samples,
    sample_bias = sample_bias
  )
}

#' Default parameters for generation of synthetic single cell data (ADT)
#'
#' @description For the generation of synthetic single cell data mostly for
#' testing or showcasing purposes. In this case, ADT counts to test multi-modal
#' integration. The default configurations generates 1000 cells x 15 proteins
#' with probes 1:3 being cell markers for cell type 1, genes 4:6 for cell type 2
#' and genes 7:9 for cell type. Columns 13:15 represents isotype controls.
#'
#' @param n_cells Integer. Number of cells. Defaults to `1000L`.
#' @param n_proteins Integer. Number of proteins Defaults to `15L`.
#' @param n_batches Integer. Number of batches. Defaults to `1L`.
#' @param marker_genes Any. A nested list that indicates which gene indices are
#' markers for which cell. Defaults to `list(cell_type_1 = list(marker_genes =
#' 0:2), cell_type_2 = list(marker_genes = 3:5), cell_type_3 = list(marker_genes
#' = 6:8))`.
#' @param isotype_controls Integer vector. The columns that defines the isotype
#' controls. (0-indexed!) Defaults to `12:14`.
#' @param batch_effect_strength String. The strength of the batch effect to add.
#' One of `c("strong", "medium", "weak")`. Defaults to `"strong"`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item n_cells - Integer. Number of cells. Defaults to `1000L`.
#'  \item n_proteins - Integer. Number of proteins Defaults to `15L`.
#'  \item marker_genes - Any. A nested list that indicates which gene indices
#'  are markers for which cell. Defaults to `list(cell_type_1 =
#'  list(marker_genes = 0:2), cell_type_2 = list(marker_genes = 3:5),
#'  cell_type_3 = list(marker_genes = 6:8))`.
#'  \item n_batches - Integer. Number of batches. Defaults to `1L`.
#'  \item isotype_controls - Integer vector. The columns that defines the
#'  isotype controls. (0-indexed!) Defaults to `12:14`.
#'  \item batch_effect_strength - String. The strength of the batch effect to
#'  add. One of `c("strong", "medium", "weak")`. Defaults to `"strong"`.
#' }
#'
#' @export
params_sc_synthetic_data_adt <- function(
  n_cells = 1000L,
  n_proteins = 15L,
  n_batches = 1L,
  marker_genes = list(
    cell_type_1 = list(marker_genes = 0:2),
    cell_type_2 = list(marker_genes = 3:5),
    cell_type_3 = list(marker_genes = 6:8)
  ),
  isotype_controls = 12:14,
  batch_effect_strength = c("strong", "medium", "weak")
) {
  batch_effect_strength <- match.arg(batch_effect_strength)

  # Checks
  checkmate::qassert(n_cells, "I1")
  checkmate::qassert(n_proteins, "I1")
  checkmate::qassert(n_batches, "I1")
  checkmate::qassert(isotype_controls, "I+")
  checkmate::assertChoice(batch_effect_strength, c("strong", "medium", "weak"))

  checkmate::assertList(marker_genes, types = "list", names = "named")

  # Return
  list(
    n_cells = n_cells,
    n_proteins = n_proteins,
    marker_genes = marker_genes,
    n_batches = n_batches,
    isotype_controls = isotype_controls,
    batch_effect_strength = batch_effect_strength
  )
}

#' Default parameters for generation of synthetic DIALOGUE data
#'
#' @description Shapes the fixture with a planted multicellular programme that
#' [bixverse::generate_dialogue_test_data()] builds. The defaults give 14
#' samples x 25 cells x 3 cell types = 1050 cells over 400 genes.
#'
#' @details
#' `n_genes` defaults higher here than on the Rust side, which plants the same
#' structure into 90. R runs the counts through the normal ingestion path, and
#' on a small panel the planted genes are a large enough share of the library
#' that log-normalisation divides the signal back out: at 90 genes the library
#' size tracks the programme at an r of 0.75 and background genes pick up a
#' spurious correlation of their own. At 400 the planted block is a few percent
#' of the library and the contrast survives. The Rust tests feed the planted
#' layer straight in, so they never meet this.
#'
#' @param n_samples Integer. Samples the experiment spans. DIALOGUE needs at
#' least 5. Defaults to `14L`.
#' @param cells_per_sample Integer. Cells per sample per cell type. Defaults to
#' `25L`.
#' @param n_cell_types Integer. Number of cell types. Must be at least 2.
#' Defaults to `3L`.
#' @param n_features Integer. Feature columns per cell type. Must be at least 2.
#' Defaults to `8L`.
#' @param n_sample_features Integer. Feature columns carrying a per-sample
#' component. The first of those is the shared programme, the rest are
#' cell-type-specific nuisance; anything past this count is pure noise and
#' exists so the ANOVA filter has something to reject. Defaults to `5L`.
#' @param n_genes Integer. Number of genes. Defaults to `400L`.
#' @param n_planted Integer. Planted genes per cell type. The blocks are
#' contiguous, so `n_planted * n_cell_types` has to fit into `n_genes`. Defaults
#' to `8L`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item n_samples - Integer. Samples the experiment spans. DIALOGUE needs at
#'  least 5. Defaults to `14L`.
#'  \item cells_per_sample - Integer. Cells per sample per cell type. Defaults
#'  to `25L`.
#'  \item n_cell_types - Integer. Number of cell types. Must be at least 2.
#'  Defaults to `3L`.
#'  \item n_features - Integer. Feature columns per cell type. Must be at least
#'  2. Defaults to `8L`.
#'  \item n_sample_features - Integer. Feature columns carrying a per-sample
#'  component. The first of those is the shared programme, the rest are
#'  cell-type-specific nuisance; anything past this count is pure noise and
#'  exists so the ANOVA filter has something to reject. Defaults to `5L`.
#'  \item n_genes - Integer. Number of genes. Defaults to `400L`.
#'  \item n_planted - Integer. Planted genes per cell type. The blocks are
#'  contiguous, so `n_planted * n_cell_types` has to fit into `n_genes`.
#'  Defaults to `8L`.
#' }
#'
#' @references Jerby-Arnon & Regev, Nature Biotechnology, 2022
#'
#' @export
params_sc_synthetic_dialogue <- function(
  n_samples = 14L,
  cells_per_sample = 25L,
  n_cell_types = 3L,
  n_features = 8L,
  n_sample_features = 5L,
  n_genes = 400L,
  n_planted = 8L
) {
  # Checks
  checkmate::qassert(n_samples, "I1[1,)")
  checkmate::qassert(cells_per_sample, "I1[1,)")
  checkmate::qassert(n_cell_types, "I1[2,)")
  checkmate::qassert(n_features, "I1[2,)")
  checkmate::qassert(n_sample_features, "I1[1,)")
  checkmate::qassert(n_genes, "I1[1,)")
  checkmate::qassert(n_planted, "I1[0,)")

  checkmate::assertTRUE(n_sample_features <= n_features)
  checkmate::assertTRUE(n_planted * n_cell_types <= n_genes)

  # Return
  list(
    n_samples = n_samples,
    cells_per_sample = cells_per_sample,
    n_cell_types = n_cell_types,
    n_features = n_features,
    n_sample_features = n_sample_features,
    n_genes = n_genes,
    n_planted = n_planted
  )
}

#' Wrapper function for parameters for VISION with auto-correlation
#'
#' @param n_perm Integer. Number of random gene sets to generate per cluster.
#' Defaults to `500L`.
#' @param n_cluster Integer. Number of clusters for the random gene set
#' clustering generation. Defaults to `5L`.
#' @param knn List. Optional overrides for kNN parameters. See
#' [bixverse::params_knn_defaults()] for available parameters: `k`,
#' `knn_method`, `ann_dist`, `search_budget`, `n_trees`, `delta`,
#' `diversify_prob`, `ef_budget`, `extract_knn`, `m`, `ef_construction`,
#' `ef_search`, `n_list` and `n_probe`. See [params_knn_defaults()] for the
#' available elements. Defaults to `list()`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item n_perm - Integer. Number of random gene sets to generate per cluster.
#'  Defaults to `500L`.
#'  \item n_cluster - Integer. Number of clusters for the random gene set
#'  clustering generation. Defaults to `5L`.
#'  \item The elements of [params_knn_defaults()], overridden by `knn`, spliced
#'  in at this position.
#' }
#'
#' @export
params_sc_vision <- function(
  n_perm = 500L,
  n_cluster = 5L,
  knn = list()
) {
  # Checks
  checkmate::qassert(n_perm, "I1[1,)")
  checkmate::qassert(n_cluster, "I1[1,)")

  # Merge
  knn <- utils::modifyList(
    params_knn_defaults(),
    utils::modifyList(list(k = 15L, nn_max_iter = 15L), knn, keep.null = TRUE),
    keep.null = TRUE
  )

  # Return
  c(
    list(
      n_perm = n_perm,
      n_cluster = n_cluster
    ),
    knn
  )
}

#' Wrapper function for WNN parameters
#'
#' @param k_nn Integer. Final number of multimodal neighbours per cell. Defaults
#' to `20L`.
#' @param knn_range Integer. Candidate pool size per modality. Each cell's kNN
#' input must contain at least this many neighbours. Defaults to `200L`.
#' @param sigma_method String. Bandwidth method. One of `c("snn_farthest",
#' "sigma_idx")`. Defaults to `"snn_farthest"`.
#' @param sigma_idx Integer. `"sigma_idx"` only: 0-based kNN index for
#' bandwidth.e. `k_nn - 1`). Defaults to `19L`.
#' @param snn_type String. sNN type. The limited version only considers edges
#' that exist in the kNN. One of `c("full_connection", "limited")`. Defaults to
#' `"full_connection"`.
#' @param s_nn Integer. `"snn_farthest"` only: kNN size used to build the SNN
#' graph. Defaults to `20L`.
#' @param sd_scale Numeric. Multiplier on sigma. Defaults to `1.0`.
#' @param kernel_power Numeric. Kernel exponent power. Defaults to `1.0`.
#' @param cross_const Numeric. Cross-modality kernel stabiliser. Defaults to
#' `1e-04`.
#' @param sigma_floor Numeric. Minimum sigma value (avoids division by zero).
#' Defaults to `1e-08`.
#' @param knn List. Optional overrides for kNN parameters. See
#' [bixverse::params_knn_defaults()] for available parameters: `k`,
#' `knn_method`, `ann_dist`, `search_budget`, `n_trees`, `delta`,
#' `diversify_prob`, `ef_budget`, `extract_knn`, `m`, `ef_construction`,
#' `ef_search`, `n_list` and `n_probe`. See [params_knn_defaults()] for the
#' available elements. Defaults to `list()`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item k_nn - Integer. Final number of multimodal neighbours per cell.
#'  Defaults to `20L`.
#'  \item knn_range - Integer. Candidate pool size per modality. Each cell's kNN
#'  input must contain at least this many neighbours. Defaults to `200L`.
#'  \item sigma_method - String. Bandwidth method. One of `c("snn_farthest",
#'  "sigma_idx")`. Defaults to `"snn_farthest"`.
#'  \item sigma_idx - Integer. `"sigma_idx"` only: 0-based kNN index for
#'  bandwidth.e. `k_nn - 1`). Defaults to `19L`.
#'  \item snn_type - String. sNN type. The limited version only considers edges
#'  that exist in the kNN. One of `c("full_connection", "limited")`. Defaults to
#'  `"full_connection"`.
#'  \item s_nn - Integer. `"snn_farthest"` only: kNN size used to build the SNN
#'  graph. Defaults to `20L`.
#'  \item sd_scale - Numeric. Multiplier on sigma. Defaults to `1.0`.
#'  \item kernel_power - Numeric. Kernel exponent power. Defaults to `1.0`.
#'  \item cross_const - Numeric. Cross-modality kernel stabiliser. Defaults to
#'  `1e-04`.
#'  \item sigma_floor - Numeric. Minimum sigma value (avoids division by zero).
#'  Defaults to `1e-08`.
#'  \item The elements of [params_knn_defaults()], overridden by `knn`, spliced
#'  in at this position.
#' }
#'
#' @export
params_sc_wnn <- function(
  k_nn = 20L,
  knn_range = 200L,
  sigma_method = c("snn_farthest", "sigma_idx"),
  sigma_idx = 19L,
  snn_type = c("full_connection", "limited"),
  s_nn = 20L,
  sd_scale = 1.0,
  kernel_power = 1.0,
  cross_const = 1e-04,
  sigma_floor = 1e-08,
  knn = list()
) {
  sigma_method <- match.arg(sigma_method)
  snn_type <- match.arg(snn_type)

  # Checks
  checkmate::qassert(k_nn, "I1[1,)")
  checkmate::qassert(knn_range, "I1[1,)")
  checkmate::assertChoice(sigma_method, c("snn_farthest", "sigma_idx"))
  checkmate::qassert(sigma_idx, "I1[0,)")
  checkmate::assertChoice(snn_type, c("full_connection", "limited"))
  checkmate::qassert(s_nn, "I1[1,)")
  checkmate::qassert(sd_scale, "N1(0,)")
  checkmate::qassert(kernel_power, "N1(0,)")
  checkmate::qassert(cross_const, "N1[0,)")
  checkmate::qassert(sigma_floor, "N1(0,)")

  # Merge
  knn <- utils::modifyList(params_knn_defaults(), knn, keep.null = TRUE)

  # Return
  c(
    list(
      k_nn = k_nn,
      knn_range = knn_range,
      sigma_method = sigma_method,
      sigma_idx = sigma_idx,
      snn_type = snn_type,
      s_nn = s_nn,
      sd_scale = sd_scale,
      kernel_power = kernel_power,
      cross_const = cross_const,
      sigma_floor = sigma_floor
    ),
    knn
  )
}

#' Wrapper function for scDblFinder doublet detection parameters
#'
#' @description Constructor for the scDblFinder parameters. This method combines
#' cluster-aware doublet simulation with a gradient-boosted classifier trained
#' on engineered features.
#'
#' @param n_genes Integer. Number of top-expressed genes to use as features.
#' Defaults to `1352L`.
#' @param doublet_ratio Numeric. Ratio of simulated doublets to observed cells.
#' Defaults to `1.0`.
#' @param heterotypic_bias Numeric. Fraction of simulated pairs forced to come
#' from different clusters (0-1). Defaults to `1.0`.
#' @param cluster_resolution Numeric. Resolution for the initial Louvain
#' clustering. Defaults to `1.0`.
#' @param cluster_iters Integer. Number of Louvain iterations per clustering
#' step. Defaults to `10L`.
#' @param fast_cluster Boolean. Shall fast Louvain clustering be applied, i.e.,
#' k-means clustering and use the centroids for kNN graph generation and Louvain
#' clustering with then backpropagating the membership based on centroid
#' proximity. Defaults to `FALSE`.
#' @param n_iterations Integer. Number of refinement iterations. Typically 2-3.
#' Defaults to `3L`.
#' @param gbm_n_trees Integer. Maximum number of boosting rounds for the GBM
#' classifier. Defaults to `200L`.
#' @param max_depth Integer. Maximum tree depth. Shallow trees (3-5) work best.
#' Defaults to `4L`.
#' @param learning_rate Numeric. Shrinkage applied to each tree. Defaults to
#' `0.3`.
#' @param min_samples_leaf Integer. Minimum training samples per leaf. Defaults
#' to `20L`.
#' @param subsample_rate Numeric. Fraction of samples used per tree. Defaults to
#' `0.75`.
#' @param cv_folds Integer. Number of cross-validation folds for boosting round
#' selection. Defaults to `5L`.
#' @param cv_early_stop Integer. Early stopping patience per CV fold. Defaults
#' to `2L`.
#' @param se_fraction Numeric. Multiplier on the standard error for the SE rule
#' used in round selection. Defaults to `1.0`.
#' @param include_pcs Any. Number of leading principal components to include as
#' classifier features. Defaults to `19L`.
#' @param expected_doublet_rate Numeric or `NULL`. Expected doublet rate as a
#' percentage. If not provided, will be calculated internally. Defaults to
#' `NULL`.
#' @param cxds_genes Integer or `NULL`. Number of CXDS genes to consider. If not
#' provided, defaults to `500L`. Defaults to `NULL`.
#' @param manual_threshold Numeric or `NULL`. Manual score threshold. If `NULL`
#' (default), expected-rate thresholding is used. Defaults to `NULL`.
#' @param normalisation List. Optional overrides for normalisation parameters.
#' See [bixverse::params_norm_doublets_defaults()]. See
#' [params_norm_doublets_defaults()] for the available elements. Defaults to
#' `list(mean_center = TRUE)`.
#' @param pca List. Optional overrides for PCA parameters. See
#' [bixverse::params_pca_defaults()]. See [params_pca_defaults()] for the
#' available elements. Defaults to `list()`.
#' @param knn List. Optional overrides for kNN parameters. See
#' [bixverse::params_knn_defaults()]. NNDescent works better for the larger
#' k-values often used here. See [params_knn_defaults()] for the available
#' elements. Defaults to `list(k = 0L)`.
#' @param fast_cluster_params List. Optional overrides for the fast clustering
#' parameters. Only relevant if `fast_cluster = TRUE`. See
#' [params_fast_cluster_default()] for available parameters: `km_type`,
#' `n_centroids`, `kmeans_iters` and `batch_size`. See
#' [params_fast_cluster_default()] for the available elements. Defaults to
#' `list()`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item The elements of [params_norm_doublets_defaults()], overridden by
#'  `normalisation`, spliced in at this position.
#'  \item The elements of [params_pca_defaults()], overridden by `pca`, spliced
#'  in at this position.
#'  \item The elements of [params_knn_defaults()], overridden by `knn`, spliced
#'  in at this position.
#'  \item The elements of [params_fast_cluster_default()], overridden by
#'  `fast_cluster_params`, spliced in at this position.
#'  \item n_genes - Integer. Number of top-expressed genes to use as features.
#'  Defaults to `1352L`.
#'  \item doublet_ratio - Numeric. Ratio of simulated doublets to observed
#'  cells. Defaults to `1.0`.
#'  \item heterotypic_bias - Numeric. Fraction of simulated pairs forced to come
#'  from different clusters (0-1). Defaults to `1.0`.
#'  \item cluster_resolution - Numeric. Resolution for the initial Louvain
#'  clustering. Defaults to `1.0`.
#'  \item cluster_iters - Integer. Number of Louvain iterations per clustering
#'  step. Defaults to `10L`.
#'  \item fast_cluster - Boolean. Shall fast Louvain clustering be applied,
#'  i.e., k-means clustering and use the centroids for kNN graph generation and
#'  Louvain clustering with then backpropagating the membership based on
#'  centroid proximity. Defaults to `FALSE`.
#'  \item n_iterations - Integer. Number of refinement iterations. Typically
#'  2-3. Defaults to `3L`.
#'  \item gbm_n_trees - Integer. Maximum number of boosting rounds for the GBM
#'  classifier. Defaults to `200L`.
#'  \item max_depth - Integer. Maximum tree depth. Shallow trees (3-5) work
#'  best. Defaults to `4L`.
#'  \item learning_rate - Numeric. Shrinkage applied to each tree. Defaults to
#'  `0.3`.
#'  \item min_samples_leaf - Integer. Minimum training samples per leaf.
#'  Defaults to `20L`.
#'  \item subsample_rate - Numeric. Fraction of samples used per tree. Defaults
#'  to `0.75`.
#'  \item cv_folds - Integer. Number of cross-validation folds for boosting
#'  round selection. Defaults to `5L`.
#'  \item cv_early_stop - Integer. Early stopping patience per CV fold. Defaults
#'  to `2L`.
#'  \item se_fraction - Numeric. Multiplier on the standard error for the SE
#'  rule used in round selection. Defaults to `1.0`.
#'  \item include_pcs - Any. Number of leading principal components to include
#'  as classifier features. Defaults to `19L`.
#'  \item expected_doublet_rate - Numeric or `NULL`. Expected doublet rate as a
#'  percentage. If not provided, will be calculated internally. Defaults to
#'  `NULL`.
#'  \item manual_threshold - Numeric or `NULL`. Manual score threshold. If
#'  `NULL` (default), expected-rate thresholding is used. Defaults to `NULL`.
#'  \item cxds_genes - Integer or `NULL`. Number of CXDS genes to consider. If
#'  not provided, defaults to `500L`. Defaults to `NULL`.
#' }
#'
#' @export
params_scdblfinder <- function(
  n_genes = 1352L,
  doublet_ratio = 1.0,
  heterotypic_bias = 1.0,
  cluster_resolution = 1.0,
  cluster_iters = 10L,
  fast_cluster = FALSE,
  n_iterations = 3L,
  gbm_n_trees = 200L,
  max_depth = 4L,
  learning_rate = 0.3,
  min_samples_leaf = 20L,
  subsample_rate = 0.75,
  cv_folds = 5L,
  cv_early_stop = 2L,
  se_fraction = 1.0,
  include_pcs = 19L,
  expected_doublet_rate = NULL,
  cxds_genes = NULL,
  manual_threshold = NULL,
  normalisation = list(mean_center = TRUE),
  pca = list(),
  knn = list(k = 0L),
  fast_cluster_params = list()
) {
  # Checks
  checkmate::qassert(n_genes, "I1[1,)")
  checkmate::qassert(doublet_ratio, "N1(0,)")
  checkmate::qassert(heterotypic_bias, "N1[0,1]")
  checkmate::qassert(cluster_resolution, "N1(0,)")
  checkmate::qassert(cluster_iters, "I1[1,)")
  checkmate::qassert(fast_cluster, "B1")
  checkmate::qassert(n_iterations, "I1[1,)")
  checkmate::qassert(gbm_n_trees, "I1[1,)")
  checkmate::qassert(max_depth, "I1[1,)")
  checkmate::qassert(learning_rate, "N1(0,)")
  checkmate::qassert(min_samples_leaf, "I1[1,)")
  checkmate::qassert(subsample_rate, "N1(0,1]")
  checkmate::qassert(cv_folds, "I1[2,)")
  checkmate::qassert(cv_early_stop, "I1[1,)")
  checkmate::qassert(se_fraction, "N1[0,)")
  checkmate::qassert(expected_doublet_rate, c("N1(0,1]", "0"))
  checkmate::qassert(cxds_genes, c("I1", "0"))
  checkmate::qassert(manual_threshold, c("N1[0,)", "0"))

  # Merge
  normalisation <- utils::modifyList(
    params_norm_doublets_defaults(),
    normalisation,
    keep.null = TRUE
  )
  pca <- utils::modifyList(params_pca_defaults(), pca, keep.null = TRUE)
  knn <- utils::modifyList(params_knn_defaults(), knn, keep.null = TRUE)
  fast_cluster_params <- utils::modifyList(
    params_fast_cluster_default(),
    fast_cluster_params,
    keep.null = TRUE
  )

  # Return
  c(
    normalisation,
    pca,
    knn,
    fast_cluster_params,
    list(
      n_genes = n_genes,
      doublet_ratio = doublet_ratio,
      heterotypic_bias = heterotypic_bias,
      cluster_resolution = cluster_resolution,
      cluster_iters = cluster_iters,
      fast_cluster = fast_cluster,
      n_iterations = n_iterations,
      gbm_n_trees = gbm_n_trees,
      max_depth = max_depth,
      learning_rate = learning_rate,
      min_samples_leaf = min_samples_leaf,
      subsample_rate = subsample_rate,
      cv_folds = cv_folds,
      cv_early_stop = cv_early_stop,
      se_fraction = se_fraction,
      include_pcs = include_pcs,
      expected_doublet_rate = expected_doublet_rate,
      manual_threshold = manual_threshold,
      cxds_genes = cxds_genes
    )
  )
}

#' Constructor for SCENIC parameters
#'
#' @param min_counts Integer. Minimum total counts a gene needs to be included
#' in the analysis. Defaults to `50L`.
#' @param min_cells Numeric. Minimum proportion of cells (between 0 and 1) that
#' must express a gene for it to be considered. Defaults to `0.03`.
#' @param learner_type String. Regression learner to use. One of
#' `c("randomforest", "extratrees", "grnboost2")`. Defaults to `"randomforest"`.
#' @param gene_batch_strategy String. Strategy for grouping target genes into
#' batches. Only used for `"randomforest"` and `"extratrees"` learners; ignored
#' for `"grnboost2"`. One of `c("correlated", "random")`. Defaults to
#' `"correlated"`.
#' @param gene_batch_size Integer or `NULL`. Number of genes per batch. If
#' `NULL` (default), the batch size is determined automatically. Ignored for
#' `"grnboost2"`. Defaults to `NULL`.
#' @param n_pcs Integer. Number of PCs to use for the correlated gene batch
#' strategy. Defaults to `50L`.
#' @param n_subsample Integer. Cell subsampling threshold for the correlated
#' gene batch strategy. If the number of cells meets or exceeds this value,
#' `n_subsample` cells are randomly selected prior to running randomised SVD.
#' Defaults to `100000L`.
#' @param learner_params List. Optional overrides for the regression learner
#' parameters. For `"randomforest"`, see
#' [bixverse::params_scenic_random_forest_defaults()]. For `"extratrees"`, see
#' [bixverse::params_scenic_extra_trees_defaults()]. For `"grnboost2"`, see
#' [bixverse::params_scenic_gradient_boosting_defaults()]. Defaults to `list()`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item min_counts - Integer. Minimum total counts a gene needs to be included
#'  in the analysis. Defaults to `50L`.
#'  \item min_cells - Numeric. Minimum proportion of cells (between 0 and 1)
#'  that must express a gene for it to be considered. Defaults to `0.03`.
#'  \item learner_type - String. Regression learner to use. One of
#'  `c("randomforest", "extratrees", "grnboost2")`. Defaults to
#'  `"randomforest"`.
#'  \item gene_batch_strategy - String. Strategy for grouping target genes into
#'  batches. Only used for `"randomforest"` and `"extratrees"` learners; ignored
#'  for `"grnboost2"`. One of `c("correlated", "random")`. Defaults to
#'  `"correlated"`.
#'  \item gene_batch_size - Integer or `NULL`. Number of genes per batch. If
#'  `NULL` (default), the batch size is determined automatically. Ignored for
#'  `"grnboost2"`. Defaults to `NULL`.
#'  \item n_pcs - Integer. Number of PCs to use for the correlated gene batch
#'  strategy. Defaults to `50L`.
#'  \item n_subsample - Integer. Cell subsampling threshold for the correlated
#'  gene batch strategy. If the number of cells meets or exceeds this value,
#'  `n_subsample` cells are randomly selected prior to running randomised SVD.
#'  Defaults to `100000L`.
#'  \item The elements of the base list, overridden by `learner_params`, spliced
#'  in at this position.
#' }
#'
#' @export
params_scenic <- function(
  min_counts = 50L,
  min_cells = 0.03,
  learner_type = c("randomforest", "extratrees", "grnboost2"),
  gene_batch_strategy = c("correlated", "random"),
  gene_batch_size = NULL,
  n_pcs = 50L,
  n_subsample = 100000L,
  learner_params = list()
) {
  learner_type <- match.arg(learner_type)
  gene_batch_strategy <- match.arg(gene_batch_strategy)

  # Checks
  checkmate::qassert(min_counts, "I1[1,)")
  checkmate::qassert(min_cells, "N1(0,1]")
  checkmate::assertChoice(
    learner_type,
    c("randomforest", "extratrees", "grnboost2")
  )
  checkmate::assertChoice(gene_batch_strategy, c("correlated", "random"))
  checkmate::qassert(gene_batch_size, c("I1[1,)", "0"))
  checkmate::qassert(n_pcs, "I1[1,)")
  checkmate::qassert(n_subsample, "I1[1,)")

  # Merge
  learner_params <- utils::modifyList(
    switch(
      learner_type,
      extratrees = params_scenic_extra_trees_defaults(),
      grnboost2 = params_scenic_gradient_boosting_defaults(),
      params_scenic_random_forest_defaults()
    ),
    learner_params,
    keep.null = TRUE
  )

  # Return
  c(
    list(
      min_counts = min_counts,
      min_cells = min_cells,
      learner_type = learner_type,
      gene_batch_strategy = gene_batch_strategy,
      gene_batch_size = gene_batch_size,
      n_pcs = n_pcs,
      n_subsample = n_subsample
    ),
    learner_params
  )
}

#' Wrapper function for parameters for the SCENIC binarisation
#'
#' @description Each regulon gets its own threshold. A two-component Gaussian
#' mixture is fitted and compared against a single Gaussian by BIC; if the
#' mixture wins, the threshold is the kernel density minimum between the two
#' component means, otherwise it falls back to `mean + 2 * sd`. This follows
#' pySCENIC. AUCell fits six candidates and then lets the density trough
#' override all of them whenever one exists, so the two land in much the same
#' place. Turn `bw_adjust` up if shallow wobbles in the density are being picked
#' up as troughs. AUCell effectively runs at `2`.
#'
#' @param bw_adjust Numeric. Multiplier on the Silverman bandwidth of the kernel
#' density estimate. Higher values smooth more. Defaults to `1.0`.
#' @param n_grid Integer. Number of points at which the density is evaluated
#' between the two component means. Defaults to `512L`.
#' @param n_bins Integer. Number of histogram bins used to approximate the
#' density. Defaults to `512L`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item bw_adjust - Numeric. Multiplier on the Silverman bandwidth of the
#'  kernel density estimate. Higher values smooth more. Defaults to `1.0`.
#'  \item n_grid - Integer. Number of points at which the density is evaluated
#'  between the two component means. Defaults to `512L`.
#'  \item n_bins - Integer. Number of histogram bins used to approximate the
#'  density. Defaults to `512L`.
#' }
#'
#' @references Aibar, et al., Nat Methods, 2017
#'
#' @export
params_scenic_binarise <- function(
  bw_adjust = 1.0,
  n_grid = 512L,
  n_bins = 512L
) {
  # Checks
  checkmate::qassert(bw_adjust, "N1(0,)")
  checkmate::qassert(n_grid, "I1[3,)")
  checkmate::qassert(n_bins, "I1[2,)")

  bw_adjust <- as.double(bw_adjust)
  n_grid <- as.double(n_grid)
  n_bins <- as.double(n_bins)

  # Return
  list(
    bw_adjust = bw_adjust,
    n_grid = n_grid,
    n_bins = n_bins
  )
}

