#' Wrapper function for Scrublet doublet detection parameters
#'
#' @description Constructor for the various Scrublet parameters. In this case,
#' the default for the kNN graph generation was set to `"hnsw"` as this
#' algorithm showed the best performance in different empirical benchmarks.
#'
#' @param sim_doublet_ratio Numeric. Number of doublets to simulate relative to
#' the number of observed cells. For example, 2.0 simulates twice as many
#' doublets as there are cells. Defaults to `1.5`.
#' @param expected_doublet_rate Numeric. Expected doublet rate for the
#' experiment, typically 0.05-0.10 depending on cell loading. Must be between 0
#' and 1. Defaults to `0.1`.
#' @param stdev_doublet_rate Numeric. Uncertainty in the expected doublet rate.
#' Defaults to `0.02`.
#' @param n_bins_histogram Integer. Number of bins for histogram-based automatic
#' threshold detection. Typically 50-100. Defaults to `100L`.
#' @param manual_threshold Numeric or `NULL`. Manual doublet score threshold. If
#' `NULL` (default), threshold is automatically detected from simulated doublet
#' score distribution. Defaults to `NULL`.
#' @param normalisation List. Optional overrides for normalisation parameters.
#' See [bixverse::params_norm_doublets_defaults()] for available parameters:
#' `log_transform`, `mean_center`, `normalise_variance`, `target_size`. See
#' [params_norm_doublets_defaults()] for the available elements. Defaults to
#' `list()`.
#' @param hvg List. Optional overrides for highly variable gene selection
#' parameters. See [bixverse::params_hvg_defaults()] for available parameters:
#' `min_gene_var_pctl`, `hvg_method`, `loess_span`, `clip_max`. See
#' [params_hvg_defaults()] for the available elements. Defaults to `list()`.
#' @param pca List. Optional overrides for PCA parameters. See
#' [bixverse::params_pca_defaults()] for available parameters: `no_pcs`,
#' `random_svd`, `sparse` and `skip_first_pc`. See [params_pca_defaults()] for
#' the available elements. Defaults to `list()`.
#' @param knn List. Optional overrides for kNN parameters. See
#' [bixverse::params_knn_defaults()] for available parameters: `k`,
#' `knn_method`, `ann_dist`, `search_budget`, `n_trees`, `delta`,
#' `diversify_prob`, `ef_budget`, `extract_knn`, `m`, `ef_construction`,
#' `ef_search`, `n_list` and `n_probe`. Note: this function defaults to `k = 0L`
#' (automatic neighbour detection). See [params_knn_defaults()] for the
#' available elements. Defaults to `list(k = 0L)`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item The elements of [params_norm_doublets_defaults()], overridden by
#'  `normalisation`, spliced in at this position.
#'  \item The elements of [params_hvg_defaults()], overridden by `hvg`, spliced
#'  in at this position.
#'  \item The elements of [params_pca_defaults()], overridden by `pca`, spliced
#'  in at this position.
#'  \item The elements of [params_knn_defaults()], overridden by `knn`, spliced
#'  in at this position.
#'  \item sim_doublet_ratio - Numeric. Number of doublets to simulate relative
#'  to the number of observed cells. For example, 2.0 simulates twice as many
#'  doublets as there are cells. Defaults to `1.5`.
#'  \item expected_doublet_rate - Numeric. Expected doublet rate for the
#'  experiment, typically 0.05-0.10 depending on cell loading. Must be between 0
#'  and 1. Defaults to `0.1`.
#'  \item stdev_doublet_rate - Numeric. Uncertainty in the expected doublet
#'  rate. Defaults to `0.02`.
#'  \item n_bins_histogram - Integer. Number of bins for histogram-based
#'  automatic threshold detection. Typically 50-100. Defaults to `100L`.
#'  \item manual_threshold - Numeric or `NULL`. Manual doublet score threshold.
#'  If `NULL` (default), threshold is automatically detected from simulated
#'  doublet score distribution. Defaults to `NULL`.
#' }
#'
#' @export
params_scrublet <- function(
  sim_doublet_ratio = 1.5,
  expected_doublet_rate = 0.1,
  stdev_doublet_rate = 0.02,
  n_bins_histogram = 100L,
  manual_threshold = NULL,
  normalisation = list(),
  hvg = list(),
  pca = list(),
  knn = list(k = 0L)
) {
  # Checks
  checkmate::qassert(sim_doublet_ratio, "N1(0,)")
  checkmate::qassert(expected_doublet_rate, "N1[0,1]")
  checkmate::qassert(stdev_doublet_rate, "N1[0,1]")
  checkmate::qassert(n_bins_histogram, "I1[10,)")
  checkmate::qassert(manual_threshold, c("N1[0,)", "0"))

  # Merge
  normalisation <- utils::modifyList(
    params_norm_doublets_defaults(),
    normalisation,
    keep.null = TRUE
  )
  hvg <- utils::modifyList(params_hvg_defaults(), hvg, keep.null = TRUE)
  pca <- utils::modifyList(params_pca_defaults(), pca, keep.null = TRUE)
  knn <- utils::modifyList(params_knn_defaults(), knn, keep.null = TRUE)

  # Return
  c(
    normalisation,
    hvg,
    pca,
    knn,
    list(
      sim_doublet_ratio = sim_doublet_ratio,
      expected_doublet_rate = expected_doublet_rate,
      stdev_doublet_rate = stdev_doublet_rate,
      n_bins_histogram = n_bins_histogram,
      manual_threshold = manual_threshold
    )
  )
}

#' Parameters for the per-cell ScType assignment
#'
#' @description Controls the per-cell path of [assign_sc_type()]: how the raw
#' ScType scores are rescaled, how hard the scores get smoothed over the sNN
#' graph, and where the cut-offs for an Unknown call and for a mixed cluster
#' sit.
#'
#' @param alpha Numeric. Numeric in `[0, 1]`. Self-retention during smoothing.
#' Each iteration computes `alpha * original + (1 - alpha) * neighbour_average`.
#' Defaults to `0.5`.
#' @param iterations Integer. Integer >= 0. Number of smoothing iterations. `0`
#' disables smoothing. Defaults to `2L`.
#' @param tolerance Numeric. Numeric > 0. Convergence tolerance for the
#' smoothing. Defaults to `1e-04`.
#' @param calibration String. `"column_z"` standardises each cell type's score
#' column across cells, which removes the bias towards cell types whose marker
#' sets happen to produce larger scores. One of `c("none", "column_z")`.
#' Defaults to `"none"`.
#' @param score_floor Numeric. Numeric >= 0. Minimum score for a cell to get a
#' call instead of `NA`. Defaults to `0.25`.
#' @param purity_threshold Numeric. Numeric in `[0, 1]`. Cluster purity above
#' which the hybrid assignment keeps the cluster-level call. Defaults to `0.9`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item alpha - Numeric. Numeric in `[0, 1]`. Self-retention during smoothing.
#'  Each iteration computes `alpha * original + (1 - alpha) *
#'  neighbour_average`. Defaults to `0.5`.
#'  \item iterations - Integer. Integer >= 0. Number of smoothing iterations.
#'  `0` disables smoothing. Defaults to `2L`.
#'  \item tolerance - Numeric. Numeric > 0. Convergence tolerance for the
#'  smoothing. Defaults to `1e-04`.
#'  \item calibration - String. `"column_z"` standardises each cell type's score
#'  column across cells, which removes the bias towards cell types whose marker
#'  sets happen to produce larger scores. One of `c("none", "column_z")`.
#'  Defaults to `"none"`.
#'  \item score_floor - Numeric. Numeric >= 0. Minimum score for a cell to get a
#'  call instead of `NA`. Defaults to `0.25`.
#'  \item purity_threshold - Numeric. Numeric in `[0, 1]`. Cluster purity above
#'  which the hybrid assignment keeps the cluster-level call. Defaults to `0.9`.
#' }
#'
#' @references Zhou et al., NIPS, 2004.
#'
#' @export
params_sctype_cells <- function(
  alpha = 0.5,
  iterations = 2L,
  tolerance = 1e-04,
  calibration = c("none", "column_z"),
  score_floor = 0.25,
  purity_threshold = 0.9
) {
  calibration <- match.arg(calibration)

  # Checks
  checkmate::qassert(alpha, "N1[0,1]")
  checkmate::qassert(iterations, "I1[0,)")
  checkmate::qassert(tolerance, "N1(0,)")
  checkmate::assertChoice(calibration, c("none", "column_z"))
  checkmate::qassert(score_floor, "N1[0,)")
  checkmate::qassert(purity_threshold, "N1[0,1]")

  # Return
  res <- list(
    alpha = alpha,
    iterations = iterations,
    tolerance = tolerance,
    calibration = calibration,
    score_floor = score_floor,
    purity_threshold = purity_threshold
  )
  class(res) <- c("params_sctype_cells", "list")
  res
}

#' Wrapper function to generate SNF parameters
#'
#' @param k Integer. Number of neighbours to consider. Defaults to `20L`.
#' @param t Integer. Number of iterations for the SNF algorithm. Defaults to
#' `20L`.
#' @param mu Numeric. Normalisation factor for the Gaussian kernel width.
#' Defaults to `0.5`.
#' @param alpha Numeric. Normalisation parameter controlling the fusion
#' strength. Defaults to `1.0`.
#' @param normalise Boolean. Shall continuous values be Z-scored. Defaults to
#' `TRUE`.
#' @param distance_metric String. Which distance metric to use for the
#' continuous calculations. In case of pure categorical, Hamming will be used,
#' for mixed data types Gower distance is used. One of `c("euclidean",
#' "manhattan", "canberra", "cosine")`. Defaults to `"euclidean"`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item k - Integer. Number of neighbours to consider. Defaults to `20L`.
#'  \item t - Integer. Number of iterations for the SNF algorithm. Defaults to
#'  `20L`.
#'  \item mu - Numeric. Normalisation factor for the Gaussian kernel width.
#'  Defaults to `0.5`.
#'  \item alpha - Numeric. Normalisation parameter controlling the fusion
#'  strength. Defaults to `1.0`.
#'  \item distance_metric - String. Which distance metric to use for the
#'  continuous calculations. In case of pure categorical, Hamming will be used,
#'  for mixed data types Gower distance is used. One of `c("euclidean",
#'  "manhattan", "canberra", "cosine")`. Defaults to `"euclidean"`.
#'  \item normalise - Boolean. Shall continuous values be Z-scored. Defaults to
#'  `TRUE`.
#' }
#'
#' @export
params_snf <- function(
  k = 20L,
  t = 20L,
  mu = 0.5,
  alpha = 1.0,
  normalise = TRUE,
  distance_metric = c("euclidean", "manhattan", "canberra", "cosine")
) {
  distance_metric <- match.arg(distance_metric)

  # Checks
  checkmate::qassert(k, "I1")
  checkmate::qassert(t, "I1")
  checkmate::qassert(mu, "N1[0,1]")
  checkmate::qassert(alpha, "N1")
  checkmate::qassert(normalise, "B1")
  checkmate::assertChoice(
    distance_metric,
    c("euclidean", "manhattan", "canberra", "cosine")
  )

  # Return
  list(
    k = k,
    t = t,
    mu = mu,
    alpha = alpha,
    distance_metric = distance_metric,
    normalise = normalise
  )
}

#' Wrapper function to generate ssGSEA parameters
#'
#' @param alpha Numeric. The exponent defining the weight of the tail in the
#' random walk performed by ssGSEA. Defaults to `0.25`.
#' @param min_size Integer. Minimum number of genes per gene set. Defaults to
#' `5L`.
#' @param max_size Integer. Maximum number of genes per gene set. Defaults to
#' `500L`.
#' @param normalise Boolean. Shall the scores be normalised. Defaults to `TRUE`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item alpha - Numeric. The exponent defining the weight of the tail in the
#'  random walk performed by ssGSEA. Defaults to `0.25`.
#'  \item min_size - Integer. Minimum number of genes per gene set. Defaults to
#'  `5L`.
#'  \item max_size - Integer. Maximum number of genes per gene set. Defaults to
#'  `500L`.
#'  \item normalise - Boolean. Shall the scores be normalised. Defaults to
#'  `TRUE`.
#' }
#'
#' @export
params_ssgsea <- function(
  alpha = 0.25,
  min_size = 5L,
  max_size = 500L,
  normalise = TRUE
) {
  # Checks
  checkmate::qassert(alpha, "N1(0, 1)")
  checkmate::qassert(min_size, "I1[3,)")
  checkmate::qassert(max_size, "I1[4,)")
  checkmate::qassert(normalise, "B1")

  # Return
  list(
    alpha = alpha,
    min_size = min_size,
    max_size = max_size,
    normalise = normalise
  )
}

#' Default parameters for Symphony query mapping
#'
#' @param sigma Numeric. Soft-clustering fuzziness for query -> reference
#' centroid assignment. Symphony R default is 0.1. Defaults to `0.1`.
#' @param lambda Numeric. Ridge penalty on batch coefficients. Symphony R
#' hardcodes 1.0. Defaults to `1.0`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item sigma - Numeric. Soft-clustering fuzziness for query -> reference
#'  centroid assignment. Symphony R default is 0.1. Defaults to `0.1`.
#'  \item lambda - Numeric. Ridge penalty on batch coefficients. Symphony R
#'  hardcodes 1.0. Defaults to `1.0`.
#' }
#'
#' @export
params_symphony_map <- function(
  sigma = 0.1,
  lambda = 1.0
) {
  # Checks
  checkmate::qassert(sigma, "N1[0,)")
  checkmate::qassert(lambda, "N1[0,)")

  # Return
  res <- list(
    sigma = sigma,
    lambda = lambda
  )
  class(res) <- c("params_symphony_map", "list")
  res
}

#' Wrapper function to generate synthetic bulk RNAseq parameters
#'
#' @description Parameters for [bixverse::synthetic_bulk_cor_matrix()]. Counts
#' come from a negative binomial with a mean-dispersion trend; co-expression
#' modules are planted by putting each module's genes on a shared latent factor.
#' The `generator` picks how loadings and factors are drawn, which is what makes
#' a given dataset a fair or unfair benchmark for a given method: \itemize{
#' \item `"hub_modular"` - LogNormal loadings on a Normal factor. Some genes end
#' up far more connected than others, so this is the WGCNA-style default. \item
#' `"modular"` - Beta(5, 2) loadings on a Normal factor. Homogeneous
#' within-module correlation and no hubs. \item `"non_negative_factor"` -
#' LogNormal loadings on a Gamma factor. The activity matrix is non-negative by
#' construction, so NMF has a ground truth it can actually reach. \item
#' `"non_gaussian_factor"` - LogNormal loadings on a Laplace factor.
#' Non-Gaussian sources satisfy ICA identifiability. }
#'
#' @details
#' `noise_std` and `factor_std` default to `0.1` and `0.5`, not to the
#' `bixverse-rs` values of `0.3` and `0.3`. At the crate defaults the
#' `"modular"` generator plants modules too weakly to detect at 1000 genes by
#' 100 samples: the within-module minus cross-module mean absolute Spearman gap
#' comes out around `0.06`, against `0.17` to `0.23` for the other three. The
#' values here put all four generators in the `0.30` to `0.39` band, so a
#' comparison across generators reflects the method rather than the signal
#' strength it happened to be handed. Pass the crate values explicitly if you
#' want a harder problem.
#'
#' @param num_samples Integer. Number of samples (columns) to simulate. Defaults
#' to `100L`.
#' @param num_genes Integer. Number of genes (rows) to simulate. Defaults to
#' `1000L`.
#' @param module_sizes Integer vector. Sizes of the co-expression modules. The
#' sum must be smaller or equal to `num_genes`. Genes are assigned in contiguous
#' blocks from the first gene onwards, any remainder is background. Use
#' `integer(0)` for no modules. Must be an integer vector, see the note below.
#' Defaults to `c(100L, 100L, 100L)`.
#' @param generator String. Which topology and distribution family to plant.,
#' see the description. One of `c("hub_modular", "modular",
#' "non_negative_factor", "non_gaussian_factor")`. Defaults to `"hub_modular"`.
#' @param seed Integer. Seed for reproducibility purposes. Defaults to `123L`.
#' @param mean_exp_gamma_shape Numeric. Shape and scale of the Gamma the
#' per-gene mean expression is drawn from. Defaults to `5.0`.
#' @param mean_exp_gamma_scale Numeric. Shape and scale of the Gamma the
#' per-gene mean expression is drawn from. Defaults to `10.0`.
#' @param disp_intercept Numeric. Intercept and slope of the negative binomial
#' dispersion trend `disp = 1 / (a + b * mean)`. This is what gives you
#' heteroskedasticity: lowly expressed genes show higher variance. Defaults to
#' `0.2`.
#' @param disp_slope Numeric. Intercept and slope of the negative binomial
#' dispersion trend `disp = 1 / (a + b * mean)`. This is what gives you
#' heteroskedasticity: lowly expressed genes show higher variance. Defaults to
#' `0.3`.
#' @param noise_std Numeric. Per-gene per-sample noise standard deviation on the
#' latent log-signal. Smaller values track the module factor more tightly and
#' give stronger within-module correlation. Defaults to `0.1`.
#' @param factor_std Numeric. Standard deviation of the Normal factor. Only used
#' by `"hub_modular"` and `"modular"`; the other two generators draw their
#' factor from `factor_shape`/`factor_scale` instead. Defaults to `0.5`.
#' @param factor_shape Numeric. Shape and scale of the Gamma factor for
#' `"non_negative_factor"`. `factor_scale` doubles as the Laplace scale for
#' `"non_gaussian_factor"`. Defaults to `2.0`.
#' @param factor_scale Numeric. Shape and scale of the Gamma factor for
#' `"non_negative_factor"`. `factor_scale` doubles as the Laplace scale for
#' `"non_gaussian_factor"`. Defaults to `0.3`.
#' @param loading_mu Numeric. Location and scale of the LogNormal the loadings
#' are drawn from. Unused by `"modular"`, which draws Beta(5, 2). Defaults to
#' `0.0`.
#' @param loading_sigma Numeric. Location and scale of the LogNormal the
#' loadings are drawn from. Unused by `"modular"`, which draws Beta(5, 2).
#' Defaults to `0.7`.
#' @param hub_percentile Numeric. Top fraction of module genes flagged as hubs
#' by loading rank. Must be in `(0, 1]`. Defaults to `0.1`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item num_samples - Integer. Number of samples (columns) to simulate.
#'  Defaults to `100L`.
#'  \item num_genes - Integer. Number of genes (rows) to simulate. Defaults to
#'  `1000L`.
#'  \item module_sizes - Integer vector. Sizes of the co-expression modules. The
#'  sum must be smaller or equal to `num_genes`. Genes are assigned in
#'  contiguous blocks from the first gene onwards, any remainder is background.
#'  Use `integer(0)` for no modules. Must be an integer vector, see the note
#'  below. Defaults to `c(100L, 100L, 100L)`.
#'  \item generator - String. Which topology and distribution family to plant.,
#'  see the description. One of `c("hub_modular", "modular",
#'  "non_negative_factor", "non_gaussian_factor")`. Defaults to `"hub_modular"`.
#'  \item seed - Integer. Seed for reproducibility purposes. Defaults to `123L`.
#'  \item mean_exp_gamma_shape - Numeric. Shape and scale of the Gamma the
#'  per-gene mean expression is drawn from. Defaults to `5.0`.
#'  \item mean_exp_gamma_scale - Numeric. Shape and scale of the Gamma the
#'  per-gene mean expression is drawn from. Defaults to `10.0`.
#'  \item disp_intercept - Numeric. Intercept and slope of the negative binomial
#'  dispersion trend `disp = 1 / (a + b * mean)`. This is what gives you
#'  heteroskedasticity: lowly expressed genes show higher variance. Defaults to
#'  `0.2`.
#'  \item disp_slope - Numeric. Intercept and slope of the negative binomial
#'  dispersion trend `disp = 1 / (a + b * mean)`. This is what gives you
#'  heteroskedasticity: lowly expressed genes show higher variance. Defaults to
#'  `0.3`.
#'  \item noise_std - Numeric. Per-gene per-sample noise standard deviation on
#'  the latent log-signal. Smaller values track the module factor more tightly
#'  and give stronger within-module correlation. Defaults to `0.1`.
#'  \item factor_std - Numeric. Standard deviation of the Normal factor. Only
#'  used by `"hub_modular"` and `"modular"`; the other two generators draw their
#'  factor from `factor_shape`/`factor_scale` instead. Defaults to `0.5`.
#'  \item factor_shape - Numeric. Shape and scale of the Gamma factor for
#'  `"non_negative_factor"`. `factor_scale` doubles as the Laplace scale for
#'  `"non_gaussian_factor"`. Defaults to `2.0`.
#'  \item factor_scale - Numeric. Shape and scale of the Gamma factor for
#'  `"non_negative_factor"`. `factor_scale` doubles as the Laplace scale for
#'  `"non_gaussian_factor"`. Defaults to `0.3`.
#'  \item loading_mu - Numeric. Location and scale of the LogNormal the loadings
#'  are drawn from. Unused by `"modular"`, which draws Beta(5, 2). Defaults to
#'  `0.0`.
#'  \item loading_sigma - Numeric. Location and scale of the LogNormal the
#'  loadings are drawn from. Unused by `"modular"`, which draws Beta(5, 2).
#'  Defaults to `0.7`.
#'  \item hub_percentile - Numeric. Top fraction of module genes flagged as hubs
#'  by loading rank. Must be in `(0, 1]`. Defaults to `0.1`.
#' }
#'
#' @references Zhang & Horvath, Stat Appl Genet Mol Biol, 2005
#'
#' @export
params_synthetic_bulk_rnaseq <- function(
  num_samples = 100L,
  num_genes = 1000L,
  module_sizes = c(100L, 100L, 100L),
  generator = c(
    "hub_modular",
    "modular",
    "non_negative_factor",
    "non_gaussian_factor"
  ),
  seed = 123L,
  mean_exp_gamma_shape = 5.0,
  mean_exp_gamma_scale = 10.0,
  disp_intercept = 0.2,
  disp_slope = 0.3,
  noise_std = 0.1,
  factor_std = 0.5,
  factor_shape = 2.0,
  factor_scale = 0.3,
  loading_mu = 0.0,
  loading_sigma = 0.7,
  hub_percentile = 0.1
) {
  generator <- match.arg(generator)

  # Checks
  checkmate::qassert(num_samples, "I1[1,)")
  checkmate::qassert(num_genes, "I1[1,)")
  checkmate::qassert(module_sizes, "I*")
  checkmate::assertChoice(
    generator,
    c("hub_modular", "modular", "non_negative_factor", "non_gaussian_factor")
  )
  checkmate::qassert(seed, "I1[0,)")
  checkmate::qassert(mean_exp_gamma_shape, "N1(0,)")
  checkmate::qassert(mean_exp_gamma_scale, "N1(0,)")
  checkmate::qassert(disp_intercept, "N1(0,)")
  checkmate::qassert(disp_slope, "N1(0,)")
  checkmate::qassert(noise_std, "N1[0,)")
  checkmate::qassert(factor_std, "N1(0,)")
  checkmate::qassert(factor_shape, "N1(0,)")
  checkmate::qassert(factor_scale, "N1(0,)")
  checkmate::qassert(loading_mu, "N1")
  checkmate::qassert(loading_sigma, "N1(0,)")
  checkmate::qassert(hub_percentile, "N1(0,1]")

  checkmate::assertTRUE(sum(module_sizes) <= num_genes)

  # Return
  list(
    num_samples = num_samples,
    num_genes = num_genes,
    module_sizes = module_sizes,
    generator = generator,
    seed = seed,
    mean_exp_gamma_shape = mean_exp_gamma_shape,
    mean_exp_gamma_scale = mean_exp_gamma_scale,
    disp_intercept = disp_intercept,
    disp_slope = disp_slope,
    noise_std = noise_std,
    factor_std = factor_std,
    factor_shape = factor_shape,
    factor_scale = factor_scale,
    loading_mu = loading_mu,
    loading_sigma = loading_sigma,
    hub_percentile = hub_percentile
  )
}
